import ast as _nb9_ast
import functools as _nb9_functools
import inspect as _nb9_inspect
import textwrap as _nb9_textwrap


class _NotebookStageRegistry:
    """Compile declared source blocks as module code to preserve model scope."""

    def __init__(self, namespace):
        self.namespace = namespace
        self.stages = {}
        self.order = []
        self.completed = []

    def register(self, identifier):
        def decorate(function):
            source = _nb9_textwrap.dedent(_nb9_inspect.getsource(function))
            declaration = _nb9_ast.parse(source).body[0]
            module = _nb9_ast.Module(body=declaration.body, type_ignores=[])
            _nb9_ast.fix_missing_locations(module)
            code = compile(module, function.__code__.co_filename, "exec")
            self.stages[identifier] = code

            @_nb9_functools.wraps(function)
            def execute():
                return self.run(identifier)

            return execute

        return decorate

    def run(self, identifier):
        if identifier in self.completed:
            return
        position = self.order.index(identifier)
        missing = [
            key for key in self.order[:position] if key not in self.completed
        ]
        if missing:
            raise RuntimeError(
                "Earlier source stages are incomplete. Run the final workflow "
                "execution cell to preserve dependency order."
            )
        print(f"Running source stage: {identifier}")
        exec(self.stages[identifier], self.namespace)
        self.completed.append(identifier)

    def run_all(self):
        for identifier in self.order:
            self.run(identifier)


_nb9_registry = _NotebookStageRegistry(globals())
RUN_FULL_WORKFLOW = os.environ.get("MTAP_RUN_WORKFLOW", "0") == "1"
DEPLOYMENT_THRESHOLD = 0.75

