@_nb9_registry.register("s02_0")
def _nb9_stage_s02_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    from importlib import metadata as package_metadata
    import sys
    import numpy as np
    import pandas as pd

    PROJECT = Path(str(PROJECT_ROOT))
    PATIENT_FILE = (
        PROJECT / "data_processed" / "TCGA_primary_solid_MTAP_DNA_RNA.tsv"
    )
    RNA_FILE = (
        PROJECT
        / "data_raw/PANCAN/TCGA"
        / "EBPlusPlusAdjustPANCAN_IlluminaHiSeq_RNASeqV2.geneExp.tsv"
    )
    PURITY_FILE = (
        PROJECT
        / "data_processed"
        / "TCGA_primary_solid_MTAP_DNA_RNA_purity.tsv"
    )
    OUTPUT_DIR = (
        PROJECT / "data_processed" / "MTAP_RNA_prediction" / "01_input_audit"
    )
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    for package in [
        "numpy",
        "pandas",
        "scipy",
        "scikit-learn",
        "matplotlib",
        "joblib",
    ]:
        try:
            version = package_metadata.version(package)
        except package_metadata.PackageNotFoundError:
            version = "Not installed"
    for label, path in [
        ("Patient-level DNA/RNA table", PATIENT_FILE),
        ("Unified RNA matrix", RNA_FILE),
        ("Purity-linked table", PURITY_FILE),
    ]:
        pass
    for path in [PATIENT_FILE, RNA_FILE]:
        if not path.is_file():
            raise FileNotFoundError(
                "TCGA patient, RNA, and copy-number input audit: integrity check failed; condition: input or artifact integrity check."
            )
    patients = pd.read_csv(
        PATIENT_FILE,
        sep="\t",
        dtype={"patient_id": "string", "acronym": "string"},
    )
    required = {"patient_id", "acronym", "MTAP_GISTIC_call"}
    missing = required.difference(patients.columns)
    if missing:
        raise ValueError(
            "TCGA patient, RNA, and copy-number input audit: integrity check failed; condition: input or artifact integrity check."
        )
    patients["patient_id"] = patients["patient_id"].str.strip().str.upper()
    patients["acronym"] = patients["acronym"].str.strip().str.upper()
    patients["MTAP_GISTIC_call"] = pd.to_numeric(
        patients["MTAP_GISTIC_call"], errors="coerce"
    )
    invalid_identity = (
        patients["patient_id"].isna()
        | patients["patient_id"].eq("")
        | patients["acronym"].isna()
        | patients["acronym"].eq("")
    )
    invalid_call = ~patients["MTAP_GISTIC_call"].isin([-2, -1, 0, 1, 2])
    if invalid_identity.any() or invalid_call.any():
        invalid = patients.loc[invalid_identity | invalid_call].copy()
        invalid.to_csv(
            OUTPUT_DIR / "invalid_patient_records.tsv", sep="\t", index=False
        )
        raise ValueError(
            "TCGA patient, RNA, and copy-number input audit: integrity check failed; condition: input or artifact integrity check."
        )
    duplicated = patients["patient_id"].duplicated(keep=False)
    if duplicated.any():
        patients.loc[duplicated].to_csv(
            OUTPUT_DIR / "duplicated_patients.tsv", sep="\t", index=False
        )
        raise ValueError(
            "TCGA patient, RNA, and copy-number input audit: integrity check failed; condition: input or artifact integrity check."
        )
    patients["MTAP_GISTIC_call"] = patients["MTAP_GISTIC_call"].astype(int)
    patients["MTAP_deep_label"] = (
        patients["MTAP_GISTIC_call"].eq(-2).astype(int)
    )
    counts = (
        patients.groupby("acronym", observed=True)
        .agg(
            n_patients=("patient_id", "size"),
            n_positive=("MTAP_deep_label", "sum"),
        )
        .reset_index()
    )
    counts["n_negative"] = counts["n_patients"] - counts["n_positive"]
    counts["positive_pct"] = 100 * counts["n_positive"] / counts["n_patients"]
    counts["has_both_classes"] = counts["n_positive"].gt(0) & counts[
        "n_negative"
    ].gt(0)
    counts = counts.sort_values(
        ["n_positive", "acronym"], ascending=[False, True]
    ).reset_index(drop=True)
    rna_columns = pd.read_csv(RNA_FILE, sep="\t", nrows=0).columns.tolist()
    gene_id_column = rna_columns[0]
    sample_columns = rna_columns[1:]
    records = []
    for sample in sample_columns:
        barcode = str(sample).strip()
        fields = barcode.split("-")
        if len(fields) >= 4 and fields[0] == "TCGA" and (len(fields[3]) >= 2):
            sample_type = fields[3][:2]
            if sample_type == "01":
                records.append(
                    {
                        "patient_id": "-".join(fields[:3]),
                        "RNA_column": sample,
                        "sample_type": sample_type,
                    }
                )
    if not records:
        raise ValueError(
            "TCGA patient, RNA, and copy-number input audit: integrity check failed; condition: input or artifact integrity check."
        )
    rna_map = pd.DataFrame(records)
    rna_per_patient = rna_map.groupby("patient_id", as_index=False).agg(
        n_primary_RNA_columns=("RNA_column", "size"),
        primary_RNA_columns=("RNA_column", lambda values: ";".join(values)),
    )
    audited = patients.merge(
        rna_per_patient,
        on="patient_id",
        how="left",
        validate="one_to_one",
        indicator="RNA_header_match",
    )
    unmatched = audited.loc[audited["RNA_header_match"].ne("both")].copy()
    if not unmatched.empty:
        unmatched.to_csv(
            OUTPUT_DIR / "patients_without_primary_RNA.tsv",
            sep="\t",
            index=False,
        )
        raise ValueError(
            "TCGA patient, RNA, and copy-number input audit: integrity check failed; condition: input or artifact integrity check."
        )
    candidate_paths = set()
    known_processed = (
        PROJECT / "data_processed" / "TCGA_primary_solid_9p21_calls.tsv"
    )
    if known_processed.is_file():
        candidate_paths.add(known_processed)
    dna_search_root = PROJECT / "data_raw/PANCAN/TCGA"
    if dna_search_root.is_dir():
        for path in dna_search_root.rglob("*"):
            if not path.is_file():
                continue
            name = path.name.lower()
            is_candidate = (
                "thresholded" in name
                or "by_genes" in name
                or (
                    "9p21" in name
                    and (".tsv" in name or ".txt" in name or ".csv" in name)
                )
            )
            if is_candidate:
                candidate_paths.add(path)
    candidate_records = []
    if not candidate_paths:
        pass
    for index, path in enumerate(sorted(candidate_paths, key=str), start=1):
        size_mb = path.stat().st_size / 1024**2
        candidate_records.append({"path": str(path), "size_MB": size_mb})
        name = path.name.lower()
        if name.endswith(
            (".tsv", ".txt", ".tsv.gz", ".txt.gz", ".csv", ".csv.gz")
        ):
            separator = "," if ".csv" in name else "\t"
            try:
                preview = pd.read_csv(path, sep=separator, nrows=3)
            except Exception as error:
                pass
    audited.to_csv(
        OUTPUT_DIR / "TCGA_prediction_patient_audit.tsv", sep="\t", index=False
    )
    counts.to_csv(
        OUTPUT_DIR / "TCGA_prediction_label_counts_by_cancer.tsv",
        sep="\t",
        index=False,
    )
    rna_map.to_csv(
        OUTPUT_DIR / "TCGA_primary_RNA_column_map.tsv", sep="\t", index=False
    )
    pd.DataFrame(candidate_records, columns=["path", "size_MB"]).to_csv(
        OUTPUT_DIR / "existing_DNA_candidate_files.tsv", sep="\t", index=False
    )
    _public_summary(
        globals(), "TCGA patient, RNA, and copy-number input audit"
    )

