@_nb9_registry.register("s03a_0")
def _nb9_stage_s03a_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import json
    import numpy as np
    import pandas as pd
    from sklearn.model_selection import train_test_split

    PROJECT = Path(str(PROJECT_ROOT))
    PATIENT_FILE = (
        PROJECT / "data_processed/TCGA_primary_solid_MTAP_DNA_RNA.tsv"
    )
    DNA_FILE = PROJECT / "data_processed/TCGA_primary_solid_9p21_calls.tsv"
    OUTPUT_DIR = (
        PROJECT / "data_processed/MTAP_RNA_prediction/02_labels_and_split"
    )
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    RANDOM_SEED = 20261016
    TEST_FRACTION = 0.2
    SPLIT_FILE = OUTPUT_DIR / "fixed_patient_split.tsv"
    VALID_CALLS = [-2, -1, 0, 1, 2]
    for path in [PATIENT_FILE, DNA_FILE]:
        if not path.is_file():
            raise FileNotFoundError(
                "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
            )
    patients = pd.read_csv(
        PATIENT_FILE,
        sep="\t",
        dtype={"patient_id": "string", "acronym": "string"},
    )
    dna = pd.read_csv(
        DNA_FILE, sep="\t", dtype={"patient_id": "string", "acronym": "string"}
    )
    required_patient = {
        "patient_id",
        "acronym",
        "MTAP_GISTIC_call",
        "MTAP_RNA",
        "MTAP_log2_RNA",
    }
    required_dna = {
        "patient_id",
        "acronym",
        "MTAP_GISTIC_call",
        "CDKN2A_GISTIC_call",
        "CDKN2B_GISTIC_call",
    }
    for name, frame, required in [
        ("DNA/RNA table", patients, required_patient),
        ("9p21 table", dna, required_dna),
    ]:
        missing = required.difference(frame.columns)
        if missing:
            raise ValueError(
                "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
            )
        for column in ["patient_id", "acronym"]:
            frame[column] = frame[column].str.strip().str.upper()
            if frame[column].isna().any() or frame[column].eq("").any():
                raise ValueError(
                    "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
                )
        if frame["patient_id"].duplicated().any():
            raise ValueError(
                "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
            )
    dna_columns = [
        "patient_id",
        "acronym",
        "MTAP_GISTIC_call",
        "CDKN2A_GISTIC_call",
        "CDKN2B_GISTIC_call",
    ]
    cohort = patients.merge(
        dna[dna_columns].rename(
            columns={
                "acronym": "DNA_acronym",
                "MTAP_GISTIC_call": "MTAP_GISTIC_call_DNA",
            }
        ),
        on="patient_id",
        how="left",
        validate="one_to_one",
        indicator="DNA_match",
    )
    if cohort["DNA_match"].ne("both").any():
        raise ValueError(
            "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
        )
    call_columns = [
        "MTAP_GISTIC_call",
        "MTAP_GISTIC_call_DNA",
        "CDKN2A_GISTIC_call",
        "CDKN2B_GISTIC_call",
    ]
    for column in call_columns:
        cohort[column] = pd.to_numeric(cohort[column], errors="coerce")
        if not cohort[column].isin(VALID_CALLS).all():
            raise ValueError(
                "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
            )
        cohort[column] = cohort[column].astype(int)
    if not cohort["acronym"].eq(cohort["DNA_acronym"]).all():
        raise ValueError(
            "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
        )
    if not cohort["MTAP_GISTIC_call"].eq(cohort["MTAP_GISTIC_call_DNA"]).all():
        raise ValueError(
            "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
        )
    cohort = cohort.drop(
        columns=["DNA_acronym", "MTAP_GISTIC_call_DNA", "DNA_match"]
    )
    cohort["label_MTAP_deep"] = cohort["MTAP_GISTIC_call"].eq(-2).astype(int)
    cohort["label_MTAP_CDKN2B_codeep"] = (
        cohort["MTAP_GISTIC_call"].eq(-2) & cohort["CDKN2B_GISTIC_call"].eq(-2)
    ).astype(int)
    cohort["DNA_subgroup"] = np.select(
        [
            cohort["label_MTAP_CDKN2B_codeep"].eq(1),
            cohort["MTAP_GISTIC_call"].eq(-2),
            cohort["CDKN2B_GISTIC_call"].eq(-2),
            cohort["MTAP_GISTIC_call"].eq(-1),
            cohort["MTAP_GISTIC_call"].eq(0),
        ],
        [
            "MTAP_CDKN2B_codeep",
            "MTAP_deep_without_CDKN2B_deep",
            "CDKN2B_deep_without_MTAP_deep",
            "MTAP_shallow_without_CDKN2B_deep",
            "MTAP_neutral_without_CDKN2B_deep",
        ],
        default="MTAP_gain_without_CDKN2B_deep",
    )
    cross_table = pd.crosstab(
        cohort["MTAP_GISTIC_call"], cohort["CDKN2B_GISTIC_call"], dropna=False
    )
    n_mt = int(cohort["label_MTAP_deep"].sum())
    n_joint = int(cohort["label_MTAP_CDKN2B_codeep"].sum())
    if n_mt > 0:
        pass
    for column in ["MTAP_RNA", "MTAP_log2_RNA"]:
        cohort[column] = pd.to_numeric(cohort[column], errors="coerce")
    expression = cohort[["MTAP_RNA", "MTAP_log2_RNA"]].to_numpy(dtype=float)
    if not np.isfinite(expression).all():
        raise ValueError(
            "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
        )
    if cohort["MTAP_RNA"].lt(0).any():
        raise ValueError(
            "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
        )
    expected_log = np.log2(cohort["MTAP_RNA"].to_numpy(dtype=float) + 1.0)
    observed_log = cohort["MTAP_log2_RNA"].to_numpy(dtype=float)
    absolute_error = np.abs(expected_log - observed_log)
    if not np.allclose(expected_log, observed_log, rtol=1e-05, atol=1e-05):
        raise ValueError(
            "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
        )
    cohort.to_csv(
        OUTPUT_DIR / "TCGA_prediction_labeled_cohort.tsv",
        sep="\t",
        index=False,
    )
    cross_table.to_csv(
        OUTPUT_DIR / "MTAP_CDKN2B_GISTIC_crosstab.tsv", sep="\t"
    )
    label_by_cancer = cohort.groupby("acronym", as_index=False).agg(
        n_patients=("patient_id", "size"),
        n_MTAP_deep=("label_MTAP_deep", "sum"),
        n_codeep=("label_MTAP_CDKN2B_codeep", "sum"),
    )
    label_by_cancer.to_csv(
        OUTPUT_DIR / "DNA_labels_by_cancer.tsv", sep="\t", index=False
    )
    _public_summary(
        globals(), "TCGA cohort linkage and DNA target definitions"
    )

