# %%
@_nb9_registry.register("s03b_0")
def _nb9_stage_s03b_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    cohort = cohort.sort_values("patient_id").reset_index(drop=True)
    if SPLIT_FILE.is_file():
        split = pd.read_csv(
            SPLIT_FILE, sep="\t", dtype={"patient_id": "string"}
        )
        if not {"patient_id", "dataset_split", "label_MTAP_deep"}.issubset(
            split.columns
        ):
            raise ValueError(
                "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
            )
        if split["patient_id"].duplicated().any():
            raise ValueError(
                "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
            )
        if set(split["patient_id"]) != set(cohort["patient_id"]):
            raise ValueError(
                "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
            )
        check = cohort[["patient_id", "label_MTAP_deep"]].merge(
            split[["patient_id", "label_MTAP_deep"]],
            on="patient_id",
            suffixes=("_current", "_saved"),
            validate="one_to_one",
        )
        if (
            not check["label_MTAP_deep_current"]
            .eq(check["label_MTAP_deep_saved"])
            .all()
        ):
            raise ValueError(
                "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
            )
        if not split["dataset_split"].isin(["development", "test"]).all():
            raise ValueError(
                "TCGA labels, co-deletion checks, and fixed patient split: integrity check failed; condition: input or artifact integrity check."
            )
    else:
        development_ids, test_ids = train_test_split(
            cohort["patient_id"].to_numpy(),
            test_size=TEST_FRACTION,
            random_state=RANDOM_SEED,
            stratify=cohort["label_MTAP_deep"].to_numpy(),
        )
        test_ids = set(test_ids)
        split = cohort[["patient_id", "acronym", "label_MTAP_deep"]].copy()
        split["dataset_split"] = np.where(
            split["patient_id"].isin(test_ids), "test", "development"
        )
        split.to_csv(SPLIT_FILE, sep="\t", index=False)
    cohort = cohort.merge(
        split[["patient_id", "dataset_split"]],
        on="patient_id",
        how="left",
        validate="one_to_one",
    )
    cohort.to_csv(
        OUTPUT_DIR / "TCGA_prediction_cohort_with_split.tsv",
        sep="\t",
        index=False,
    )
    split_summary = cohort.groupby("dataset_split", as_index=False).agg(
        n_patients=("patient_id", "size"),
        n_positive=("label_MTAP_deep", "sum"),
    )
    split_summary["n_negative"] = (
        split_summary["n_patients"] - split_summary["n_positive"]
    )
    split_summary["positive_pct"] = (
        100 * split_summary["n_positive"] / split_summary["n_patients"]
    )
    split_cancer = cohort.groupby(
        ["acronym", "dataset_split"], as_index=False
    ).agg(
        n_patients=("patient_id", "size"),
        n_positive=("label_MTAP_deep", "sum"),
    )
    split_cancer["n_negative"] = (
        split_cancer["n_patients"] - split_cancer["n_positive"]
    )
    split_summary.to_csv(
        OUTPUT_DIR / "split_summary.tsv", sep="\t", index=False
    )
    split_cancer.to_csv(
        OUTPUT_DIR / "split_counts_by_cancer.tsv", sep="\t", index=False
    )
    config = {
        "main_target": "MTAP_GISTIC_call == -2",
        "secondary_target": "MTAP_GISTIC_call == -2 AND CDKN2B_GISTIC_call == -2",
        "random_seed": RANDOM_SEED,
        "test_fraction_on_initial_creation": TEST_FRACTION,
        "initial_split_stratification": "main DNA label",
        "n_patients": int(len(cohort)),
        "training_performed": False,
    }
    with open(
        OUTPUT_DIR / "preparation_config.json", "w", encoding="utf-8"
    ) as handle:
        json.dump(config, handle, ensure_ascii=False, indent=2)
    _public_summary(globals(), "Fixed 80/20 development and holdout split")

