# %% [markdown]
##### Reference pan-cancer source-code preparation

# %%
@_nb9_registry.register("s09_0")
def _nb9_stage_s09_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path, PurePosixPath
    import hashlib
    import stat
    import zipfile

    PROJECT = Path(str(PROJECT_ROOT))
    ZIP_FILE = None
    DESTINATION = PROJECT / "code_external" / "greenelab_pancancer"
    if ZIP_FILE is None:
        candidates = sorted(
            (
                path
                for path in PROJECT.rglob("*")
                if path.is_file()
                and path.suffix.lower() == ".zip"
                and ("pancancer" in path.name.lower())
            )
        )
        for index, path in enumerate(candidates, start=1):
            pass
        if len(candidates) == 0:
            raise FileNotFoundError(
                "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
            )
        if len(candidates) > 1:
            raise ValueError(
                "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
            )
        ZIP_FILE = candidates[0]
    else:
        ZIP_FILE = Path(ZIP_FILE)
    if not ZIP_FILE.is_file():
        raise FileNotFoundError(
            "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
        )
    if not zipfile.is_zipfile(ZIP_FILE):
        raise ValueError(
            "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
        )
    with zipfile.ZipFile(ZIP_FILE) as archive:
        main_script_suffix = "scripts/pancancer_classifier.py"
        matches = [
            info.filename
            for info in archive.infolist()
            if not info.is_dir()
            and (
                info.filename == main_script_suffix
                or info.filename.endswith("/" + main_script_suffix)
            )
        ]
        if len(matches) != 1:
            raise ValueError(
                "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
            )
        archive_prefix = matches[0][: -len(main_script_suffix)]
        planned_files = []
        for info in archive.infolist():
            if info.is_dir():
                continue
            if not info.filename.startswith(archive_prefix):
                continue
            relative_name = info.filename[len(archive_prefix) :]
            if not relative_name:
                continue
            if "\\" in relative_name:
                raise ValueError(
                    "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
                )
            relative_path = PurePosixPath(relative_name)
            if (
                relative_path.is_absolute()
                or ".." in relative_path.parts
                or ":" in relative_name
            ):
                raise ValueError(
                    "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
                )
            file_mode = info.external_attr >> 16
            if stat.S_ISLNK(file_mode):
                raise ValueError(
                    "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
                )
            target = DESTINATION.joinpath(*relative_path.parts)
            planned_files.append((info, target))
        if not planned_files:
            raise ValueError(
                "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
            )
        targets = [str(target) for _, target in planned_files]
        if len(targets) != len(set(targets)):
            raise ValueError(
                "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
            )
        for info, target in planned_files:
            if target.is_symlink():
                raise ValueError(
                    "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
                )
            if target.exists():
                if not target.is_file():
                    raise ValueError(
                        "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
                    )
                incoming_hash = hashlib.sha256(archive.read(info)).hexdigest()
                existing_hash = hashlib.sha256(target.read_bytes()).hexdigest()
                if incoming_hash != existing_hash:
                    raise ValueError(
                        "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
                    )
        n_written = 0
        n_reused = 0
        for info, target in planned_files:
            if target.is_file():
                n_reused += 1
                continue
            destination_root = DESTINATION.resolve()
            if not target.resolve().is_relative_to(destination_root):
                raise ValueError(
                    "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
                )
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as source:
                with target.open("xb") as output:
                    while True:
                        block = source.read(1024 * 1024)
                        if not block:
                            break
                        output.write(block)
            n_written += 1
    required_files = [
        "README.md",
        "environment.yml",
        "tp53_analysis.sh",
        "scripts/pancancer_classifier.py",
        "scripts/util/tcga_util.py",
    ]
    missing_files = []
    for relative_name in required_files:
        path = DESTINATION / relative_name
        if not path.is_file():
            missing_files.append(relative_name)
    if missing_files:
        raise FileNotFoundError(
            "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
        )
    lfs_pointers = []
    for relative_name in required_files:
        path = DESTINATION / relative_name
        with path.open("rb") as handle:
            start = handle.read(150)
        if start.startswith(b"version https://git-lfs.github.com/spec/v1"):
            lfs_pointers.append(str(path))
    if lfs_pointers:
        raise RuntimeError(
            "Reference pan-cancer source-code preparation: integrity check failed; condition: input or artifact integrity check."
        )
    utility_file = DESTINATION / "scripts/util/tcga_util.py"
    _public_summary(globals(), "Reference pan-cancer source-code preparation")

# %% [markdown]
##### 9p21.3 candidate features and Entrez identity audit

# %%
@_nb9_registry.register("s10_0")
def _nb9_stage_s10_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import re
    import pandas as pd

    PROJECT = Path(str(PROJECT_ROOT))
    DNA_FILE = (
        PROJECT
        / "data_raw/PANCAN/TCGA/all_thresholded.by_genes_whitelisted.tsv"
    )
    RNA_FILE = (
        PROJECT
        / "data_raw/PANCAN/TCGA/EBPlusPlusAdjustPANCAN_IlluminaHiSeq_RNASeqV2.geneExp.tsv"
    )
    OUTPUT_DIR = (
        PROJECT
        / "data_processed/MTAP_RNA_prediction/08_9p21_region_candidate_audit"
    )
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    TARGET_CYTOBAND = "9p21.3"
    EXPECTED_CORE_GENES = {"MTAP": "4507", "CDKN2A": "1029", "CDKN2B": "1030"}
    for path in [DNA_FILE, RNA_FILE]:
        if not path.is_file():
            raise FileNotFoundError(
                "9p21.3 candidate features and Entrez identity audit: integrity check failed; condition: input or artifact integrity check."
            )

    def clean_entrez(value):
        if pd.isna(value):
            return ""
        value = str(value).strip()
        if re.fullmatch("\\d+(?:\\.0+)?", value):
            return value.split(".")[0]
        return ""

    def parse_rna_gene_id(value):
        """Parse symbol/Entrez identifiers without replacing ambiguous members."""
        raw = str(value).strip()
        if "|" in raw:
            symbol, identifier = raw.rsplit("|", 1)
            return (raw, symbol.strip(), clean_entrez(identifier))
        return (raw, raw, "")

    dna_columns = ["Gene Symbol", "Locus ID", "Cytoband"]
    dna_annotation = pd.read_csv(
        DNA_FILE, sep="\t", usecols=dna_columns, dtype="string"
    )
    dna_annotation = dna_annotation.rename(
        columns={
            "Gene Symbol": "DNA_symbol",
            "Locus ID": "Entrez_ID",
            "Cytoband": "Cytoband",
        }
    )
    for column in ["DNA_symbol", "Cytoband"]:
        dna_annotation[column] = dna_annotation[column].fillna("").str.strip()
    dna_annotation["Entrez_ID"] = dna_annotation["Entrez_ID"].map(clean_entrez)
    candidates = dna_annotation.loc[
        dna_annotation["Cytoband"].eq(TARGET_CYTOBAND)
    ].copy()
    candidates = candidates.drop_duplicates().reset_index(drop=True)
    if candidates.empty:
        raise ValueError(
            "9p21.3 candidate features and Entrez identity audit: integrity check failed; condition: input or artifact integrity check."
        )
    for symbol, entrez in EXPECTED_CORE_GENES.items():
        matched = candidates.loc[candidates["Entrez_ID"].eq(entrez)]
        if matched.empty:
            raise ValueError(
                "9p21.3 candidate features and Entrez identity audit: integrity check failed; condition: input or artifact integrity check."
            )
    rna_header = pd.read_csv(RNA_FILE, sep="\t", nrows=0)
    gene_column = rna_header.columns[0]
    candidate_ids = set(
        candidates.loc[candidates["Entrez_ID"].ne(""), "Entrez_ID"]
    )
    rna_records = []
    for chunk in pd.read_csv(
        RNA_FILE,
        sep="\t",
        usecols=[gene_column],
        dtype="string",
        chunksize=4096,
    ):
        for value in chunk[gene_column].dropna():
            raw, symbol, entrez = parse_rna_gene_id(value)
            if entrez in candidate_ids:
                rna_records.append(
                    {
                        "Entrez_ID": entrez,
                        "RNA_gene_id": raw,
                        "RNA_symbol": symbol,
                    }
                )
    rna_matches = pd.DataFrame(
        rna_records, columns=["Entrez_ID", "RNA_gene_id", "RNA_symbol"]
    )
    rna_summary_rows = []
    for entrez, subset in rna_matches.groupby("Entrez_ID", sort=False):
        rna_summary_rows.append(
            {
                "Entrez_ID": entrez,
                "n_RNA_rows": len(subset),
                "RNA_gene_ids": "; ".join(sorted(set(subset["RNA_gene_id"]))),
                "RNA_symbols": "; ".join(sorted(set(subset["RNA_symbol"]))),
            }
        )
    rna_summary = pd.DataFrame(
        rna_summary_rows,
        columns=["Entrez_ID", "n_RNA_rows", "RNA_gene_ids", "RNA_symbols"],
    )
    audit = candidates.merge(
        rna_summary, on="Entrez_ID", how="left", validate="many_to_one"
    )
    audit["n_RNA_rows"] = audit["n_RNA_rows"].fillna(0).astype(int)
    for column in ["RNA_gene_ids", "RNA_symbols"]:
        audit[column] = audit[column].fillna("")
    audit["mapping_status"] = "Not_found_by_Entrez"
    audit.loc[audit["n_RNA_rows"].eq(1), "mapping_status"] = (
        "Unique_Entrez_match"
    )
    audit.loc[audit["n_RNA_rows"].gt(1), "mapping_status"] = (
        "Multiple_RNA_rows_review_required"
    )
    audit.loc[audit["Entrez_ID"].eq(""), "mapping_status"] = (
        "Missing_numeric_Entrez"
    )
    audit["is_core_three_gene"] = audit["Entrez_ID"].isin(
        EXPECTED_CORE_GENES.values()
    )
    audit = audit.sort_values(
        ["is_core_three_gene", "DNA_symbol"], ascending=[False, True]
    ).reset_index(drop=True)
    audit.to_csv(
        OUTPUT_DIR / "9p21_3_candidate_gene_RNA_mapping.tsv",
        sep="\t",
        index=False,
    )
    rna_matches.to_csv(
        OUTPUT_DIR / "9p21_3_matched_RNA_gene_rows.tsv", sep="\t", index=False
    )
    dna_annotation.groupby("Cytoband", dropna=False).size().rename(
        "n_annotation_rows"
    ).to_csv(OUTPUT_DIR / "DNA_cytoband_annotation_counts.tsv", sep="\t")
    _public_summary(
        globals(), "9p21.3 candidate features and Entrez identity audit"
    )

# %% [markdown]
##### RCANE source, architecture, and environment audit

# %%
@_nb9_registry.register("s21_0")
def _nb9_stage_s21_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    from importlib import metadata
    from collections import deque
    import csv
    import hashlib
    import re
    import sys

    PROJECT = Path(str(PROJECT_ROOT))
    SOURCE = PROJECT / "code_external/RCANE"
    OUT = (
        PROJECT
        / "data_processed/MTAP_RNA_prediction"
        / "13_RCANE_source_audit"
    )
    if not SOURCE.is_dir():
        raise FileNotFoundError(
            "RCANE source, architecture, and environment audit: integrity check failed; condition: input or artifact integrity check."
        )
    required = [
        "README.md",
        "requirements.txt",
        "preprocess.py",
        "train.py",
        "predict.py",
        "postprocess.py",
    ]
    missing = [name for name in required if not (SOURCE / name).is_file()]
    if missing:
        raise FileNotFoundError(
            "RCANE source, architecture, and environment audit: integrity check failed; condition: input or artifact integrity check."
        )
    OUT.mkdir(parents=True, exist_ok=True)
    report = []

    def record(text=""):
        report.append(str(text))

    def sha256_file(path):
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for block in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(block)
        return digest.hexdigest()

    record("===== Environment =====")
    record(f"Python：{sys.executable}")
    record(f"Version: {sys.version}")
    record(f"Source path: {SOURCE}")
    excluded_parts = {
        ".git",
        "__pycache__",
        ".ipynb_checkpoints",
        ".venv",
        "venv",
    }
    files = sorted(
        (
            path
            for path in SOURCE.rglob("*")
            if path.is_file()
            and (
                not excluded_parts.intersection(path.relative_to(SOURCE).parts)
            )
        )
    )
    inventory = []
    for path in files:
        inventory.append(
            {
                "relative_path": str(path.relative_to(SOURCE)),
                "size_bytes": path.stat().st_size,
                "suffix": path.suffix.lower(),
            }
        )
    inventory_file = OUT / "RCANE_file_inventory.tsv"
    with inventory_file.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(
            handle,
            fieldnames=["relative_path", "size_bytes", "suffix"],
            delimiter="\t",
        )
        writer.writeheader()
        writer.writerows(inventory)
    record("\n===== Source files =====")
    for item in inventory:
        record(f"{item['relative_path']}\t{item['size_bytes']} bytes")
        if item["suffix"] in {".py", ".yaml", ".yml"} or Path(
            item["relative_path"]
        ).name in {"README.md", "requirements.txt"}:
            pass
    record("\n===== Installed package versions =====")
    for package in [
        "numpy",
        "pandas",
        "scipy",
        "scikit-learn",
        "torch",
        "torch-geometric",
        "PyYAML",
    ]:
        try:
            version = metadata.version(package)
        except metadata.PackageNotFoundError:
            version = "Not installed"
        record(f"{package}: {version}")
    source_paths = {SOURCE / name for name in required}
    for name in ["train_config.yaml", "predict_config.yaml"]:
        path = SOURCE / name
        if path.is_file():
            source_paths.add(path)
    model_dir = SOURCE / "model"
    if model_dir.is_dir():
        source_paths.update(model_dir.rglob("*.py"))
        source_paths.update(model_dir.rglob("*.yaml"))
        source_paths.update(model_dir.rglob("*.yml"))
    MAX_SOURCE_BYTES = 2 * 1024 * 1024
    requirements_text = (SOURCE / "requirements.txt").read_text(
        encoding="utf-8-sig", errors="replace"
    )
    for path in sorted(source_paths):
        if not path.is_file():
            continue
        relative = path.relative_to(SOURCE)
        record("\n" + "=" * 72)
        record(f"File: {relative}")
        record(f"SHA256：{sha256_file(path)}")
        if path.stat().st_size > MAX_SOURCE_BYTES:
            record("File exceeds 2 MB; contents were not collected.")
            continue
        text = path.read_text(encoding="utf-8-sig", errors="replace")
        record(text)
    table_suffixes = {".csv", ".tsv", ".txt", ".bed"}
    MAX_TABLE_BYTES = 25 * 1024 * 1024
    mtap_pattern = re.compile(
        "(?<![A-Za-z0-9])MTAP(?![A-Za-z0-9])", flags=re.IGNORECASE
    )
    table_paths = [
        path
        for path in files
        if path.suffix.lower() in table_suffixes
        and path.name != "requirements.txt"
    ]
    total_hits = 0
    for path in table_paths:
        relative = path.relative_to(SOURCE)
        size = path.stat().st_size
        record("\n" + "-" * 72)
        record(f"Table: {relative}")
        record(f"Size: {size:,} bytes")
        if size > MAX_TABLE_BYTES:
            record("File exceeds 25 MB; contents were not scanned.")
            continue
        first_lines = []
        hit_contexts = []
        previous = deque(maxlen=1)
        pending_next = False
        n_hits = 0
        with path.open("r", encoding="utf-8-sig", errors="replace") as handle:
            for line_number, line in enumerate(handle, start=1):
                line = line.rstrip("\n\r")
                if line_number <= 3:
                    first_lines.append(f"Row {line_number}: {line[:2500]}")
                if pending_next:
                    hit_contexts.append(
                        f"Next row{line_number}：{line[:6000]}"
                    )
                    pending_next = False
                if mtap_pattern.search(line):
                    n_hits += 1
                    if n_hits <= 20:
                        for prev_number, prev_line in previous:
                            hit_contexts.append(
                                f"Previous row{prev_number}：{prev_line[:6000]}"
                            )
                        hit_contexts.append(
                            f"MTAP matching row{line_number}：{line[:12000]}"
                        )
                        pending_next = True
                previous.append((line_number, line))
        for line in first_lines:
            record(line)
        record(f"Rows containing MTAP: {n_hits}")
        for line in hit_contexts:
            record(line)
        total_hits += n_hits
        if n_hits:
            for line in hit_contexts:
                if line.startswith("MTAP matching row"):
                    pass
    weight_files = [
        path
        for path in files
        if path.suffix.lower() in {".pth", ".pt", ".ckpt", ".h5", ".hdf5"}
    ]
    record("\n===== Pretrained weights =====")
    if weight_files:
        for path in weight_files:
            description = (
                f"{path.relative_to(SOURCE)} ({path.stat().st_size:,} bytes)"
            )
            record(description)
    else:
        record("No common weight format was found.")
    record("\n===== Audit scope =====")
    record("No packages were installed or updated.")
    record("Reference source code was not executed or modified.")
    record("Pretrained models were not loaded.")
    record("TCGA expression was not read.")
    record("No model training or test evaluation was performed.")
    record(
        "MTAP text matches require additional regional-resolution verification."
    )
    report_file = OUT / "RCANE_source_review.txt"
    report_file.write_text("\n".join(report), encoding="utf-8")
    _public_summary(
        globals(), "RCANE source, architecture, and environment audit"
    )

