@_nb9_registry.register("s35_0")
def _nb9_stage_s35_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import json
    import numpy as np
    import pandas as pd

    BASE = Path(
        str(
            PROJECT_ROOT
            / "data_processed/MTAP_RNA_prediction/15_region_multitask_DL"
        )
    )
    TRAIN_DIR = BASE / "08_TPM_retraining/01_expression_inputs_44"
    CPTAC_DIR = BASE / "08_TPM_retraining/CPTAC_inputs_44"
    OLD_REVIEW = BASE / "07_CPTAC_expression_scale_review"
    OUT = BASE / "08_TPM_retraining/01b_TPM_scale_review"
    OUT.mkdir(parents=True, exist_ok=True)
    CANCER_MAP = {
        "BRCA": "BRCA",
        "CCRCC": "KIRC",
        "COAD": "COAD",
        "GBM": "GBM",
        "HNSCC": "HNSC",
        "LSCC": "LUSC",
        "LUAD": "LUAD",
        "OV": "OV",
        "PDAC": "PAAD",
        "UCEC": "UCEC",
    }
    with (TRAIN_DIR / "TPM_44_feature_specification.json").open(
        "r", encoding="utf-8"
    ) as handle:
        specification = json.load(handle)
    features = specification["expression_feature_order"]
    train = pd.read_csv(
        TRAIN_DIR / "X_development_log2TPM_plus_1.tsv", sep="\t", index_col=0
    )
    train.index = train.index.astype(str)
    train = train.loc[:, features].apply(pd.to_numeric, errors="raise")
    meta = pd.read_csv(
        TRAIN_DIR / "development_metadata.tsv",
        sep="\t",
        usecols=["patient_id", "acronym"],
        dtype=str,
    ).set_index("patient_id")
    if train.index.duplicated().any() or meta.index.duplicated().any():
        raise ValueError(
            "TCGA/CPTAC TPM input compatibility: integrity check failed; condition: input or artifact integrity check."
        )
    if set(train.index) != set(meta.index):
        raise ValueError(
            "TCGA/CPTAC TPM input compatibility: integrity check failed; condition: input or artifact integrity check."
        )
    meta = meta.loc[train.index]
    if not np.isfinite(train.to_numpy()).all():
        raise ValueError(
            "TCGA/CPTAC TPM input compatibility: integrity check failed; condition: input or artifact integrity check."
        )
    gene_rows = []
    patient_rows = []
    cohort_rows = []
    for database_cancer, model_cancer in CANCER_MAP.items():
        external = pd.read_csv(
            CPTAC_DIR / database_cancer / "X_44_log2TPM_plus_1.tsv",
            sep="\t",
            index_col=0,
        )
        external.index = external.index.astype(str)
        external = external.loc[:, features].apply(
            pd.to_numeric, errors="raise"
        )
        if external.index.duplicated().any():
            raise ValueError(
                "TCGA/CPTAC TPM input compatibility: integrity check failed; condition: input or artifact integrity check."
            )
        if not np.isfinite(external.to_numpy()).all():
            raise ValueError(
                "TCGA/CPTAC TPM input compatibility: integrity check failed; condition: input or artifact integrity check."
            )
        same_cancer = train.loc[meta.index[meta["acronym"].eq(model_cancer)]]
        if same_cancer.empty:
            raise ValueError(
                "TCGA/CPTAC TPM input compatibility: integrity check failed; condition: input or artifact integrity check."
            )
        reference_sd = same_cancer.std(ddof=0).replace(0, np.nan)
        median_shift = (
            external.median() - same_cancer.median()
        ) / reference_sd
        p01 = same_cancer.quantile(0.01)
        p99 = same_cancer.quantile(0.99)
        outside = external.lt(p01) | external.gt(p99)
        diagnostic_z = (external - same_cancer.mean()) / reference_sd
        for gene in features:
            gene_rows.append(
                {
                    "database_cancer": database_cancer,
                    "model_cancer": model_cancer,
                    "feature": gene,
                    "n_TCGA": len(same_cancer),
                    "n_CPTAC": len(external),
                    "TCGA_median": same_cancer[gene].median(),
                    "CPTAC_median": external[gene].median(),
                    "TCGA_SD": reference_sd[gene],
                    "median_shift_in_same_cancer_TCGA_SD": median_shift[gene],
                    "CPTAC_fraction_outside_TCGA_P01_P99": outside[
                        gene
                    ].mean(),
                }
            )
        patient_qc = pd.DataFrame(
            {
                "patient_id": external.index,
                "database_cancer": database_cancer,
                "n_features_outside_same_cancer_TCGA_P01_P99": outside.sum(
                    axis=1
                ).to_numpy(),
                "n_features_abs_same_cancer_z_gt_3": diagnostic_z.abs()
                .gt(3)
                .sum(axis=1)
                .to_numpy(),
            }
        )
        patient_rows.append(patient_qc)
        cohort_rows.append(
            {
                "database_cancer": database_cancer,
                "n_TCGA": len(same_cancer),
                "n_CPTAC": len(external),
                "n_features": len(features),
                "median_abs_gene_median_shift_SD": median_shift.abs().median(),
                "n_genes_abs_median_shift_gt_1SD": int(
                    median_shift.abs().gt(1).sum()
                ),
                "n_genes_abs_median_shift_gt_3SD": int(
                    median_shift.abs().gt(3).sum()
                ),
                "median_n_features_outside_same_cancer_P01_P99": outside.sum(
                    axis=1
                ).median(),
            }
        )
    gene_table = pd.DataFrame(gene_rows)
    cohort_table = pd.DataFrame(cohort_rows)
    core_table = gene_table.loc[
        gene_table["feature"].isin(["MTAP", "CDKN2A", "CDKN2B"])
    ].copy()
    old_file = OLD_REVIEW / "core_three_genes_scale_comparison.tsv"
    if old_file.is_file():
        old = pd.read_csv(old_file, sep="\t")
        old = old[
            [
                "database_cancer",
                "feature",
                "median_shift_in_same_cancer_TCGA_SD",
            ]
        ].rename(
            columns={
                "median_shift_in_same_cancer_TCGA_SD": "old_EBPP_median_shift_SD"
            }
        )
        core_table = core_table.merge(
            old,
            on=["database_cancer", "feature"],
            how="left",
            validate="one_to_one",
        )
        core_table["absolute_shift_reduced"] = (
            core_table["median_shift_in_same_cancer_TCGA_SD"].abs()
            < core_table["old_EBPP_median_shift_SD"].abs()
        )
    gene_table.to_csv(
        OUT / "TPM_44_gene_scale_comparison.tsv", sep="\t", index=False
    )
    core_table.to_csv(
        OUT / "TPM_core_genes_vs_previous_scale.tsv", sep="\t", index=False
    )
    cohort_table.to_csv(
        OUT / "TPM_cohort_scale_summary.tsv", sep="\t", index=False
    )
    pd.concat(patient_rows, ignore_index=True).to_csv(
        OUT / "TPM_patient_input_range_diagnostics.tsv", sep="\t", index=False
    )
    display_columns = [
        "database_cancer",
        "feature",
        "TCGA_median",
        "CPTAC_median",
        "median_shift_in_same_cancer_TCGA_SD",
    ]
    if "old_EBPP_median_shift_SD" in core_table.columns:
        display_columns += [
            "old_EBPP_median_shift_SD",
            "absolute_shift_reduced",
        ]
    _public_summary(globals(), "TCGA/CPTAC TPM input compatibility")

