    from pathlib import Path
    import hashlib
    import importlib.util
    import json
    import warnings
    import joblib
    import numpy as np
    import pandas as pd
    import matplotlib.pyplot as plt
    import sklearn
    from sklearn.base import clone
    from sklearn.exceptions import ConvergenceWarning
    from sklearn.linear_model import SGDClassifier
    from sklearn.model_selection import GridSearchCV, StratifiedKFold
    from sklearn.pipeline import Pipeline
    from sklearn.preprocessing import StandardScaler

    PROJECT = Path(str(PROJECT_ROOT))
    AUTHOR_DIR = PROJECT / "code_external/greenelab_pancancer"
    AUTHOR_UTIL = AUTHOR_DIR / "scripts/util/tcga_util.py"
    PREDICTION_DIR = PROJECT / "data_processed/MTAP_RNA_prediction"
    EXPRESSION_FILE = (
        PREDICTION_DIR
        / "03_baseline_models/cohort_with_three_gene_expression.tsv"
    )
    PREVIOUS_OOF_FILE = (
        PREDICTION_DIR / "03_baseline_models/development_OOF_predictions.tsv"
    )
    OUTPUT_DIR = PREDICTION_DIR / "07_greenelab_SGD_adaptation"
    FIGURE_DIR = OUTPUT_DIR / "figures"
    MODEL_DIR = OUTPUT_DIR / "models"
    CV_DIR = OUTPUT_DIR / "inner_CV"
    for directory in [OUTPUT_DIR, FIGURE_DIR, MODEL_DIR, CV_DIR]:
        directory.mkdir(parents=True, exist_ok=True)
    SEED = 20261016
    FEATURES = ["MTAP_log2_RNA", "CDKN2A_log2_RNA", "CDKN2B_log2_RNA"]
    LABEL = "label_MTAP_deep"
    PRIMARY_SELECTION_METRIC = "AP"
    PARAM_GRID = {
        "classify__alpha": [0.0001, 0.001, 0.01, 0.1, 1.0],
        "classify__l1_ratio": [0.1, 0.25, 0.5, 0.75, 0.9],
    }
    PALETTE = ["#33539E", "#7FACD6", "#BFB8DA", "#E8B7D4", "#A5678E"]
    for file in [AUTHOR_UTIL, EXPRESSION_FILE, PREVIOUS_OOF_FILE]:
        if not file.is_file():
            raise FileNotFoundError(
                "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
            )
    spec = importlib.util.spec_from_file_location(
        "greenelab_tcga_util", AUTHOR_UTIL
    )
    author_util = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(author_util)
    get_threshold_metrics = author_util.get_threshold_metrics
    author_hash = hashlib.sha256(AUTHOR_UTIL.read_bytes()).hexdigest()
    expression = pd.read_csv(
        EXPRESSION_FILE, sep="\t", dtype={"patient_id": str}
    )
    previous = pd.read_csv(
        PREVIOUS_OOF_FILE, sep="\t", dtype={"patient_id": str}
    )
    required_expression = {
        "patient_id",
        "acronym",
        "dataset_split",
        LABEL,
        *FEATURES,
    }
    required_previous = {
        "patient_id",
        LABEL,
        "CV_fold",
        "probability_MTAP_only",
        "probability_Three_gene",
    }
    for name, frame, required in [
        ("Expression cache", expression, required_expression),
        ("Existing OOF file", previous, required_previous),
    ]:
        missing = required.difference(frame.columns)
        if missing:
            raise ValueError(
                "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
            )
        if frame["patient_id"].duplicated().any():
            raise ValueError(
                "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
            )
    development = expression.loc[
        expression["dataset_split"].eq("development")
    ].copy()
    del expression
    if set(development["patient_id"]) != set(previous["patient_id"]):
        raise ValueError(
            "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
        )
    development = development.set_index("patient_id")
    previous = previous.set_index("patient_id")
    development = development.sort_index()
    previous = previous.reindex(development.index)
    for column in [LABEL, *FEATURES]:
        development[column] = pd.to_numeric(
            development[column], errors="raise"
        )
    if development[LABEL].isna().any():
        raise ValueError(
            "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
        )
    if not development[LABEL].isin([0, 1]).all():
        raise ValueError(
            "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
        )
    if not np.array_equal(
        development[LABEL].to_numpy(),
        pd.to_numeric(previous[LABEL], errors="raise").to_numpy(),
    ):
        raise ValueError(
            "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
        )
    X = development[FEATURES].astype(float)
    y = development[LABEL].astype(int)
    if not np.isfinite(X.to_numpy()).all():
        raise ValueError(
            "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
        )
    folds_numeric = pd.to_numeric(previous["CV_fold"], errors="raise")
    if folds_numeric.isna().any() or (folds_numeric % 1 != 0).any():
        raise ValueError(
            "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
        )
    folds = folds_numeric.astype(int)
    if sorted(folds.unique().tolist()) != [1, 2, 3, 4, 5]:
        raise ValueError(
            "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
        )
    if len(y) != 7431 or int(y.sum()) != 558:
        raise ValueError(
            "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
        )
    for column in ["probability_MTAP_only", "probability_Three_gene"]:
        previous[column] = pd.to_numeric(previous[column], errors="raise")
        if (
            not np.isfinite(previous[column]).all()
            or not previous[column].between(0, 1).all()
        ):
            raise ValueError(
                "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
            )
    pipeline = Pipeline(
        [
            ("scale", StandardScaler()),
            (
                "classify",
                SGDClassifier(
                    loss="log_loss",
                    penalty="elasticnet",
                    class_weight="balanced",
                    random_state=SEED,
                    max_iter=20000,
                    tol=1e-05,
                    n_iter_no_change=10,
                    shuffle=True,
                ),
            ),
        ]
    )
    SCORING = {"AP": "average_precision", "AUROC": "roc_auc"}
    convergence_records = []

    def fit_search(X_train, y_train, cv, stage):
        search = GridSearchCV(
            estimator=clone(pipeline),
            param_grid=PARAM_GRID,
            scoring=SCORING,
            refit=PRIMARY_SELECTION_METRIC,
            cv=cv,
            n_jobs=1,
            return_train_score=False,
            error_score="raise",
        )
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter("always", ConvergenceWarning)
            search.fit(X_train, y_train)
        convergence_messages = [
            str(item.message)
            for item in caught
            if issubclass(item.category, ConvergenceWarning)
        ]
        for message in convergence_messages:
            convergence_records.append({"stage": stage, "warning": message})
        if convergence_messages:
            pd.DataFrame(convergence_records).to_csv(
                OUTPUT_DIR / "convergence_warnings.tsv", sep="\t", index=False
            )
            raise RuntimeError(
                "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
            )
        return search

    def calculate_metrics(labels, scores):
        labels = np.asarray(labels, dtype=int)
        scores = np.asarray(scores, dtype=float)
        if not np.isfinite(scores).all():
            raise ValueError(
                "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
            )
        if np.unique(labels).size < 2:
            return None
        return get_threshold_metrics(labels, scores)

    def coefficient_table(fitted_pipeline, stage):
        classifier = fitted_pipeline.named_steps["classify"]
        return pd.DataFrame(
            {
                "stage": stage,
                "feature": FEATURES,
                "coefficient_per_standardized_feature": classifier.coef_[0],
                "intercept": float(classifier.intercept_[0]),
                "alpha": classifier.alpha,
                "l1_ratio": classifier.l1_ratio,
                "n_iter": int(classifier.n_iter_),
            }
        )

    oof_scores = np.full(len(y), np.nan)
    fold_results = []
    coefficient_results = []
    outer_splits = []
    for fold in [1, 2, 3, 4, 5]:
        train_index = np.flatnonzero(folds.to_numpy() != fold)
        valid_index = np.flatnonzero(folds.to_numpy() == fold)
        outer_splits.append((train_index, valid_index))
        if (
            y.iloc[train_index].nunique() != 2
            or y.iloc[valid_index].nunique() != 2
        ):
            raise ValueError(
                "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
            )
        inner_cv = StratifiedKFold(
            n_splits=5, shuffle=True, random_state=SEED + fold
        )
        search = fit_search(
            X.iloc[train_index],
            y.iloc[train_index],
            cv=inner_cv,
            stage=f"outer_fold_{fold}",
        )
        pd.DataFrame(search.cv_results_).to_csv(
            CV_DIR / f"outer_fold_{fold}_grid_results.tsv",
            sep="\t",
            index=False,
        )
        best_pipeline = search.best_estimator_
        valid_scores = best_pipeline.decision_function(X.iloc[valid_index])
        oof_scores[valid_index] = valid_scores
        metrics = calculate_metrics(y.iloc[valid_index], valid_scores)
        fold_results.append(
            {
                "outer_fold": fold,
                "n_train": len(train_index),
                "n_valid": len(valid_index),
                "n_valid_positive": int(y.iloc[valid_index].sum()),
                "best_alpha": search.best_params_["classify__alpha"],
                "best_l1_ratio": search.best_params_["classify__l1_ratio"],
                "inner_best_AP": search.best_score_,
                "outer_AUROC": metrics["auroc"],
                "outer_AP": metrics["aupr"],
                "n_iter": int(best_pipeline.named_steps["classify"].n_iter_),
            }
        )
        coefficient_results.append(
            coefficient_table(best_pipeline, stage=f"outer_fold_{fold}")
        )
        joblib.dump(
            {
                "pipeline": best_pipeline,
                "features": FEATURES,
                "label": LABEL,
                "training_scope": f"development_outer_fold_{fold}",
                "output_type": "uncalibrated_decision_score",
            },
            MODEL_DIR / f"outer_fold_{fold}.joblib",
        )
    if not np.isfinite(oof_scores).all():
        raise ValueError(
            "Three-gene L2 and Elastic Net comparison: integrity check failed; condition: input or artifact integrity check."
        )
    fold_results = pd.DataFrame(fold_results)
    fold_results.to_csv(
        OUTPUT_DIR / "nested_CV_outer_fold_results.tsv", sep="\t", index=False
    )
    pd.concat(coefficient_results, ignore_index=True).to_csv(
        OUTPUT_DIR / "outer_fold_coefficients.tsv", sep="\t", index=False
    )
    oof_output = development[["acronym", LABEL]].copy()
    oof_output["CV_fold"] = folds
    oof_output["score_SGD_ElasticNet"] = oof_scores
    oof_output["probability_MTAP_only"] = previous["probability_MTAP_only"]
    oof_output["probability_Three_gene_L2"] = previous[
        "probability_Three_gene"
    ]
    oof_output.to_csv(
        OUTPUT_DIR / "development_nested_OOF_predictions.tsv",
        sep="\t",
        index_label="patient_id",
    )
    model_scores = {
        "MTAP_only_L2": previous["probability_MTAP_only"].to_numpy(),
        "Three_gene_L2": previous["probability_Three_gene"].to_numpy(),
        "Three_gene_SGD_ElasticNet": oof_scores,
    }
    metric_rows = []
    curve_results = {}
    for name, scores in model_scores.items():
        metrics = calculate_metrics(y, scores)
        curve_results[name] = metrics
        metric_rows.append(
            {
                "model": name,
                "n_patients": len(y),
                "n_positive": int(y.sum()),
                "AUROC": metrics["auroc"],
                "AUPRC_AP": metrics["aupr"],
                "evaluation": (
                    "Nested_outer_5fold_OOF"
                    if name == "Three_gene_SGD_ElasticNet"
                    else "Existing_fixed_5fold_OOF"
                ),
            }
        )
        metrics["roc_df"].to_csv(
            OUTPUT_DIR / f"{name}_ROC_coordinates.tsv", sep="\t", index=False
        )
        metrics["pr_df"].to_csv(
            OUTPUT_DIR / f"{name}_PR_coordinates.tsv", sep="\t", index=False
        )
    performance = pd.DataFrame(metric_rows)
    performance.to_csv(
        OUTPUT_DIR / "development_model_comparison.tsv", sep="\t", index=False
    )
    cancer_rows = []
    for acronym, subset in development.groupby("acronym"):
        positions = development.index.get_indexer(subset.index)
        labels = y.iloc[positions].to_numpy()
        n_positive = int(labels.sum())
        n_negative = int((labels == 0).sum())
        for name, scores in model_scores.items():
            metrics = calculate_metrics(labels, np.asarray(scores)[positions])
            cancer_rows.append(
                {
                    "acronym": acronym,
                    "model": name,
                    "n_patients": len(labels),
                    "n_positive": n_positive,
                    "n_negative": n_negative,
                    "AUROC": (
                        metrics["auroc"] if metrics is not None else np.nan
                    ),
                    "AUPRC_AP": (
                        metrics["aupr"] if metrics is not None else np.nan
                    ),
                    "support_status": (
                        "Single_class"
                        if metrics is None
                        else (
                            "Low_support"
                            if min(n_positive, n_negative) < 10
                            else "Descriptive"
                        )
                    ),
                }
            )
    cancer_results = pd.DataFrame(cancer_rows)
    cancer_results.to_csv(
        OUTPUT_DIR / "development_per_cancer_performance.tsv",
        sep="\t",
        index=False,
    )
    plt.rcParams.update(
        {
            "font.family": "DejaVu Sans",
            "font.size": 9,
            "pdf.fonttype": 42,
            "ps.fonttype": 42,
            "axes.unicode_minus": False,
        }
    )

