##### Eight-gene Elastic Net and three-gene L2 comparison

# %%
@_nb9_registry.register("s19_0")
def _nb9_stage_s19_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import hashlib
    import json
    import shutil
    import joblib
    import numpy as np
    import pandas as pd
    import matplotlib.pyplot as plt
    from sklearn.metrics import (
        roc_auc_score,
        average_precision_score,
        brier_score_loss,
        log_loss,
        roc_curve,
        precision_recall_curve,
    )

    PROJECT = Path(str(PROJECT_ROOT))
    PRED = PROJECT / "data_processed/MTAP_RNA_prediction"
    EIGHT_MODEL_FILE = (
        PRED
        / "10_region_missingness_sensitivity/models/complete_region_development_candidate.joblib"
    )
    BASELINE_MODEL_FILE = (
        PRED
        / "09_9p21_region_model/signedlog_v2/models/Three_gene_L2_development_candidate.joblib"
    )
    DEV_OOF_FILE = (
        PRED
        / "10_region_missingness_sensitivity/development_three_model_OOF.tsv"
    )
    METADATA_FILE = (
        PRED / "03_baseline_models/cohort_with_three_gene_expression.tsv"
    )
    RNA_FILE = (
        PROJECT
        / "data_raw/PANCAN/TCGA/EBPlusPlusAdjustPANCAN_IlluminaHiSeq_RNASeqV2.geneExp.tsv"
    )
    OUT = PRED / "11_locked_model_TCGA_test"
    LOCK_DIR = OUT / "locked_models"
    FIG_DIR = OUT / "figures"
    for directory in [OUT, LOCK_DIR, FIG_DIR]:
        directory.mkdir(parents=True, exist_ok=True)
    MANIFEST_FILE = OUT / "locked_analysis_manifest.json"
    FINAL_RESULTS_FILE = OUT / "TCGA_test_performance.tsv"
    SEED = 20261016
    N_BOOTSTRAPS = 2000
    LABEL = "label_MTAP_deep"
    DEV_MAIN_PROBABILITY = "probability_Complete_training_region"
    RULES = {
        "positive_min_PPV": 0.9,
        "positive_min_Wilson_lower": 0.85,
        "positive_min_n": 30,
        "negative_min_NPV": 0.98,
        "negative_min_Wilson_lower": 0.97,
        "negative_min_n": 100,
    }
    EXPECTED_EIGHT_IDS = {
        "100048912",
        "1029",
        "1030",
        "401494",
        "4300",
        "4507",
        "54914",
        "55958",
    }
    PALETTE = ["#33539E", "#7FACD6", "#BFB8DA", "#E8B7D4", "#A5678E"]

    def sha256_file(path):
        return hashlib.sha256(path.read_bytes()).hexdigest()

    def signed_log2(frame):
        return np.sign(frame) * np.log1p(np.abs(frame)) / np.log(2.0)

    def wilson_interval(k, n):
        k = np.asarray(k, dtype=float)
        n = np.asarray(n, dtype=float)
        with np.errstate(divide="ignore", invalid="ignore"):
            p = k / n
            z = 1.96
            denominator = 1 + z**2 / n
            center = (p + z**2 / (2 * n)) / denominator
            half = (
                z * np.sqrt(p * (1 - p) / n + z**2 / (4 * n**2)) / denominator
            )
        return (
            np.where(n > 0, center - half, np.nan),
            np.where(n > 0, center + half, np.nan),
        )

    def calibration_table(labels, probabilities, n_bins=10):
        table = pd.DataFrame(
            {
                "label": np.asarray(labels, dtype=int),
                "probability": np.asarray(probabilities, dtype=float),
            }
        )
        table["bin"] = pd.qcut(
            table["probability"], q=n_bins, duplicates="drop"
        )
        return (
            table.groupby("bin", observed=True)
            .agg(
                n=("label", "size"),
                n_positive=("label", "sum"),
                mean_probability=("probability", "mean"),
                observed_fraction=("label", "mean"),
            )
            .reset_index()
        )

    def metric_row(labels, probabilities, model):
        labels = np.asarray(labels, dtype=int)
        probabilities = np.asarray(probabilities, dtype=float)
        return {
            "model": model,
            "n_patients": len(labels),
            "n_positive": int(labels.sum()),
            "AUROC": roc_auc_score(labels, probabilities),
            "AP": average_precision_score(labels, probabilities),
            "Brier_score": brier_score_loss(labels, probabilities),
            "log_loss": log_loss(labels, probabilities, labels=[0, 1]),
        }

    def choose_thresholds(labels, probabilities):
        frame = pd.DataFrame(
            {
                "probability": np.asarray(probabilities, dtype=float),
                "positive": np.asarray(labels, dtype=int),
            }
        )
        grouped = (
            frame.groupby("probability", sort=True)["positive"]
            .agg(["size", "sum"])
            .rename(columns={"size": "n", "sum": "n_positive"})
        )
        n = grouped["n"].to_numpy()
        positive = grouped["n_positive"].to_numpy()
        thresholds = grouped.index.to_numpy(dtype=float)
        n_high = np.cumsum(n[::-1])[::-1]
        positive_high = np.cumsum(positive[::-1])[::-1]
        ppv = positive_high / n_high
        ppv_low, ppv_high = wilson_interval(positive_high, n_high)
        n_low = np.cumsum(n)
        negative_low = np.cumsum(n - positive)
        npv = negative_low / n_low
        npv_low, npv_high = wilson_interval(negative_low, n_low)
        audit = pd.DataFrame(
            {
                "threshold": thresholds,
                "n_high": n_high,
                "n_positive_high": positive_high,
                "PPV_high": ppv,
                "PPV_high_CI95_low": ppv_low,
                "PPV_high_CI95_high": ppv_high,
                "n_low": n_low,
                "n_negative_low": negative_low,
                "NPV_low": npv,
                "NPV_low_CI95_low": npv_low,
                "NPV_low_CI95_high": npv_high,
            }
        )
        positive_candidates = audit.loc[
            audit["PPV_high"].ge(RULES["positive_min_PPV"])
            & audit["PPV_high_CI95_low"].ge(RULES["positive_min_Wilson_lower"])
            & audit["n_high"].ge(RULES["positive_min_n"])
        ]
        if positive_candidates.empty:
            audit.to_csv(
                OUT / "development_threshold_search.tsv", sep="\t", index=False
            )
            raise RuntimeError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        chosen_positive = positive_candidates.sort_values(
            ["n_positive_high", "threshold"], ascending=[False, True]
        ).iloc[0]
        high_threshold = float(chosen_positive["threshold"])
        negative_candidates = audit.loc[
            audit["threshold"].lt(high_threshold)
            & audit["NPV_low"].ge(RULES["negative_min_NPV"])
            & audit["NPV_low_CI95_low"].ge(RULES["negative_min_Wilson_lower"])
            & audit["n_low"].ge(RULES["negative_min_n"])
        ]
        if negative_candidates.empty:
            audit.to_csv(
                OUT / "development_threshold_search.tsv", sep="\t", index=False
            )
            raise RuntimeError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        chosen_negative = negative_candidates.sort_values(
            "n_low", ascending=False
        ).iloc[0]
        low_threshold = float(chosen_negative["threshold"])
        audit.to_csv(
            OUT / "development_threshold_search.tsv", sep="\t", index=False
        )
        chosen = pd.DataFrame(
            [
                {
                    "group": "Predicted_deep_deletion",
                    "threshold": high_threshold,
                    "rule": "probability >= threshold",
                    "n_development": int(chosen_positive["n_high"]),
                    "predictive_value": chosen_positive["PPV_high"],
                    "Wilson_CI95_low": chosen_positive["PPV_high_CI95_low"],
                },
                {
                    "group": "Predicted_non_deep",
                    "threshold": low_threshold,
                    "rule": "probability <= threshold",
                    "n_development": int(chosen_negative["n_low"]),
                    "predictive_value": chosen_negative["NPV_low"],
                    "Wilson_CI95_low": chosen_negative["NPV_low_CI95_low"],
                },
            ]
        )
        chosen.to_csv(
            OUT / "development_selected_thresholds.tsv", sep="\t", index=False
        )
        return (low_threshold, high_threshold)

    def extract_test_expression(test, feature_ids):
        cache = OUT / "TCGA_test_raw_expression.tsv"
        if cache.is_file():
            raw = pd.read_csv(
                cache, sep="\t", dtype={"patient_id": str}
            ).set_index("patient_id")
            raw.columns = raw.columns.astype(str)
            if (
                raw.index.duplicated().any()
                or set(raw.index) != set(test.index)
                or set(raw.columns) != set(feature_ids)
            ):
                raise ValueError(
                    "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
                )
            return raw.reindex(index=test.index, columns=feature_ids).apply(
                pd.to_numeric, errors="raise"
            )
        header = pd.read_csv(RNA_FILE, sep="\t", nrows=0)
        gene_column = header.columns[0]
        patient_set = set(test.index)
        sample_map = {}
        for column in header.columns[1:]:
            barcode = str(column)
            if (
                barcode.startswith("TCGA-")
                and len(barcode) >= 16
                and (barcode[13:15] == "01")
                and (barcode[:12] in patient_set)
            ):
                sample_map[column] = barcode[:12]
        if set(sample_map.values()) != patient_set:
            raise ValueError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        pd.DataFrame(
            {
                "RNA_column": list(sample_map),
                "patient_id": list(sample_map.values()),
            }
        ).to_csv(
            OUT / "TCGA_test_RNA_column_mapping.tsv", sep="\t", index=False
        )
        wanted = set(feature_ids)
        extracted = {}
        for number, chunk in enumerate(
            pd.read_csv(
                RNA_FILE,
                sep="\t",
                usecols=[gene_column, *sample_map],
                chunksize=512,
            ),
            start=1,
        ):
            ids = chunk[gene_column].astype(str).str.rsplit("|", n=1).str[-1]
            selected = chunk.loc[ids.isin(wanted)].copy()
            for _, row in selected.iterrows():
                gene_id = str(row[gene_column]).rsplit("|", 1)[-1]
                if gene_id in extracted:
                    raise ValueError(
                        "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
                    )
                values = pd.to_numeric(
                    row[list(sample_map)], errors="raise"
                ).astype(float)
                values.index = [sample_map[column] for column in sample_map]
                extracted[gene_id] = values.groupby(level=0).mean()
            if number % 10 == 0:
                pass
        if set(extracted) != wanted:
            raise ValueError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        raw = pd.DataFrame(extracted).reindex(
            index=test.index, columns=feature_ids
        )
        raw.to_csv(cache, sep="\t", index_label="patient_id")
        return raw

    def main():
        if FINAL_RESULTS_FILE.is_file():
            return
        for path in [
            EIGHT_MODEL_FILE,
            BASELINE_MODEL_FILE,
            DEV_OOF_FILE,
            METADATA_FILE,
            RNA_FILE,
        ]:
            if not path.is_file():
                raise FileNotFoundError(
                    "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
                )
        if not MANIFEST_FILE.is_file():
            dev = pd.read_csv(
                DEV_OOF_FILE, sep="\t", dtype={"patient_id": str}
            )
            required = {"patient_id", LABEL, DEV_MAIN_PROBABILITY}
            if not required.issubset(dev.columns):
                raise ValueError(
                    "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
                )
            if dev["patient_id"].duplicated().any():
                raise ValueError(
                    "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
                )
            labels = pd.to_numeric(dev[LABEL], errors="raise")
            probabilities = pd.to_numeric(
                dev[DEV_MAIN_PROBABILITY], errors="raise"
            )
            if (
                not labels.isin([0, 1]).all()
                or probabilities.isna().any()
                or (not probabilities.between(0, 1).all())
            ):
                raise ValueError(
                    "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
                )
            if len(dev) != 7431 or int(labels.sum()) != 558:
                raise ValueError(
                    "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
                )
            bundle = joblib.load(EIGHT_MODEL_FILE)
            features = [str(value) for value in bundle["feature_Entrez_order"]]
            if set(features) != EXPECTED_EIGHT_IDS:
                raise ValueError(
                    "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
                )
            if bundle.get("pipeline_input") != "already_signedlog_transformed":
                raise ValueError(
                    "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
                )
            low, high = choose_thresholds(labels, probabilities)
            calibration_table(labels, probabilities).to_csv(
                OUT / "development_calibration_bins.tsv", sep="\t", index=False
            )
            pd.DataFrame(
                [metric_row(labels, probabilities, "Eight_member")]
            ).to_csv(
                OUT / "development_probability_diagnostics.tsv",
                sep="\t",
                index=False,
            )
            locked_main = LOCK_DIR / "Eight_member_locked.joblib"
            locked_baseline = LOCK_DIR / "Three_gene_L2_locked.joblib"
            shutil.copyfile(EIGHT_MODEL_FILE, locked_main)
            shutil.copyfile(BASELINE_MODEL_FILE, locked_baseline)
            manifest = {
                "primary_model": "Eight_member",
                "comparator": "Three_gene_L2",
                "feature_Entrez_order": features,
                "expression_transform": "sign(x)*log2(1+abs(x)); x=patient mean source RNA",
                "additional_probability_calibration": False,
                "rules": RULES,
                "low_threshold": low,
                "high_threshold": high,
                "development_OOF_sha256": sha256_file(DEV_OOF_FILE),
                "main_model_sha256": sha256_file(locked_main),
                "baseline_model_sha256": sha256_file(locked_baseline),
                "seed": SEED,
                "thresholds_selected_without_test": True,
            }
            with open(MANIFEST_FILE, "x", encoding="utf-8") as handle:
                json.dump(manifest, handle, ensure_ascii=False, indent=2)
        with open(MANIFEST_FILE, encoding="utf-8") as handle:
            manifest = json.load(handle)
        locked_main = LOCK_DIR / "Eight_member_locked.joblib"
        locked_baseline = LOCK_DIR / "Three_gene_L2_locked.joblib"
        if (
            sha256_file(locked_main) != manifest["main_model_sha256"]
            or sha256_file(locked_baseline)
            != manifest["baseline_model_sha256"]
            or sha256_file(DEV_OOF_FILE) != manifest["development_OOF_sha256"]
        ):
            raise ValueError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        main_bundle = joblib.load(locked_main)
        baseline_bundle = joblib.load(locked_baseline)
        features = manifest["feature_Entrez_order"]
        baseline_features = [
            str(value) for value in baseline_bundle["feature_Entrez_order"]
        ]
        if not set(baseline_features).issubset(features):
            raise ValueError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        metadata = pd.read_csv(
            METADATA_FILE, sep="\t", dtype={"patient_id": str}
        )
        if metadata["patient_id"].duplicated().any():
            raise ValueError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        test = (
            metadata.loc[metadata["dataset_split"].eq("test")]
            .copy()
            .set_index("patient_id")
            .sort_index()
        )
        dev_ids = set(
            pd.read_csv(DEV_OOF_FILE, sep="\t", usecols=["patient_id"])[
                "patient_id"
            ]
        )
        if dev_ids.intersection(test.index):
            raise ValueError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        mtap_calls = pd.to_numeric(test["MTAP_GISTIC_call"], errors="raise")
        if not mtap_calls.isin([-2, -1, 0, 1, 2]).all():
            raise ValueError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        test_y = mtap_calls.eq(-2).astype(int)
        if len(test) != 1858 or int(test_y.sum()) != 140:
            raise ValueError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        raw = extract_test_expression(test, features)
        if np.isinf(raw.to_numpy(dtype=float)).any():
            raise ValueError(
                "Eight-gene Elastic Net and three-gene L2 comparison: integrity check failed; condition: input or artifact integrity check."
            )
        expression_audit = pd.DataFrame(
            {
                "Entrez_ID": features,
                "n_missing": raw.isna().sum().to_numpy(),
                "n_negative": raw.lt(0).sum().to_numpy(),
                "minimum": raw.min().to_numpy(),
                "maximum": raw.max().to_numpy(),
            }
        )
        expression_audit.to_csv(
            OUT / "TCGA_test_expression_audit.tsv", sep="\t", index=False
        )
        X_test = signed_log2(raw)
        predictions = test[["acronym", "MTAP_GISTIC_call"]].copy()
        for optional in ["CDKN2A_GISTIC_call", "CDKN2B_GISTIC_call"]:
            if optional in test.columns:
                predictions[optional] = test[optional]
        predictions[LABEL] = test_y
        predictions["probability_Eight_member"] = main_bundle[
            "pipeline"
        ].predict_proba(X_test[features])[:, 1]
        predictions["probability_Three_gene_L2"] = baseline_bundle[
            "pipeline"
        ].predict_proba(X_test[baseline_features])[:, 1]
        predictions["n_missing_input_features"] = raw.isna().sum(axis=1)
        low = manifest["low_threshold"]
        high = manifest["high_threshold"]
        probabilities = predictions["probability_Eight_member"]
        predictions["RNA_prediction_group"] = "Uncertain"
        predictions.loc[probabilities.ge(high), "RNA_prediction_group"] = (
            "Predicted_deep_deletion"
        )
        predictions.loc[probabilities.le(low), "RNA_prediction_group"] = (
            "Predicted_non_deep"
        )
        predictions.to_csv(
            OUT / "TCGA_test_patient_predictions.tsv",
            sep="\t",
            index_label="patient_id",
        )
        outputs = {
            "Eight_member": predictions["probability_Eight_member"],
            "Three_gene_L2": predictions["probability_Three_gene_L2"],
        }
        performance = pd.DataFrame(
            [
                metric_row(test_y, probability, name)
                for name, probability in outputs.items()
            ]
        )
        rng = np.random.default_rng(SEED)
        y_array = test_y.to_numpy()
        positive_index = np.flatnonzero(y_array == 1)
        negative_index = np.flatnonzero(y_array == 0)
        boot = {name: np.zeros((N_BOOTSTRAPS, 2)) for name in outputs}
        for iteration in range(N_BOOTSTRAPS):
            sampled = np.concatenate(
                [
                    rng.choice(
                        positive_index, size=len(positive_index), replace=True
                    ),
                    rng.choice(
                        negative_index, size=len(negative_index), replace=True
                    ),
                ]
            )
            for name, probability in outputs.items():
                sampled_p = probability.to_numpy()[sampled]
                boot[name][iteration] = [
                    roc_auc_score(y_array[sampled], sampled_p),
                    average_precision_score(y_array[sampled], sampled_p),
                ]
        for metric_index, metric in enumerate(["AUROC", "AP"]):
            for name in outputs:
                ci_low, ci_high = np.quantile(
                    boot[name][:, metric_index], [0.025, 0.975]
                )
                performance.loc[
                    performance["model"].eq(name), f"{metric}_CI95_low"
                ] = ci_low
                performance.loc[
                    performance["model"].eq(name), f"{metric}_CI95_high"
                ] = ci_high
        group_rows = []
        for group in [
            "Predicted_deep_deletion",
            "Uncertain",
            "Predicted_non_deep",
        ]:
            subset = predictions.loc[
                predictions["RNA_prediction_group"].eq(group)
            ]
            n = len(subset)
            n_positive = int(subset[LABEL].sum())
            if group == "Predicted_deep_deletion":
                k = n_positive
                value_name = "PPV"
            elif group == "Predicted_non_deep":
                k = n - n_positive
                value_name = "NPV"
            else:
                k = n_positive
                value_name = "DNA_positive_fraction"
            ci_low, ci_high = wilson_interval(k, n)
            group_rows.append(
                {
                    "group": group,
                    "n_patients": n,
                    "coverage_fraction": n / len(predictions),
                    "n_DNA_positive": n_positive,
                    "value_name": value_name,
                    "value": k / n if n else np.nan,
                    "Wilson_CI95_low": float(ci_low),
                    "Wilson_CI95_high": float(ci_high),
                }
            )
        group_results = pd.DataFrame(group_rows)
        group_results.to_csv(
            OUT / "TCGA_test_three_group_results.tsv", sep="\t", index=False
        )
        cancer_rows = []
        for acronym, subset in predictions.groupby("acronym"):
            labels = subset[LABEL].astype(int)
            for name in outputs:
                probability = subset[f"probability_{name}"]
                cancer_rows.append(
                    {
                        "acronym": acronym,
                        "model": name,
                        "n_patients": len(subset),
                        "n_positive": int(labels.sum()),
                        "AUROC": (
                            roc_auc_score(labels, probability)
                            if labels.nunique() == 2
                            else np.nan
                        ),
                        "AP": (
                            average_precision_score(labels, probability)
                            if labels.nunique() == 2
                            else np.nan
                        ),
                        "support_status": (
                            "Single_class"
                            if labels.nunique() < 2
                            else (
                                "Low_support"
                                if min(
                                    int(labels.sum()), int((labels == 0).sum())
                                )
                                < 10
                                else "Descriptive"
                            )
                        ),
                    }
                )
        pd.DataFrame(cancer_rows).to_csv(
            OUT / "TCGA_test_per_cancer_performance.tsv", sep="\t", index=False
        )
        plt.rcParams.update(
            {
                "font.family": "DejaVu Sans",
                "font.size": 9,
                "pdf.fonttype": 42,
                "ps.fonttype": 42,
            }
        )
        fig, axes = plt.subplots(1, 3, figsize=(14, 4.3), facecolor="white")
        for (name, probability), color in zip(
            outputs.items(), [PALETTE[0], PALETTE[4]]
        ):
            fpr, tpr, _ = roc_curve(test_y, probability)
            precision, recall, _ = precision_recall_curve(test_y, probability)
            axes[0].plot(
                fpr,
                tpr,
                color=color,
                label=f"{name}: AUC={roc_auc_score(test_y, probability):.3f}",
            )
            axes[1].plot(
                recall,
                precision,
                color=color,
                label=f"{name}: AP={average_precision_score(test_y, probability):.3f}",
            )
            calibration = calibration_table(test_y, probability)
            calibration.to_csv(
                OUT / f"TCGA_test_{name}_calibration.tsv",
                sep="\t",
                index=False,
            )
            axes[2].plot(
                calibration["mean_probability"],
                calibration["observed_fraction"],
                marker="o",
                markersize=4,
                color=color,
                label=name,
            )
        axes[0].plot([0, 1], [0, 1], "--", color="#AAAAAA", linewidth=0.8)
        axes[1].axhline(
            test_y.mean(), linestyle="--", color="#AAAAAA", linewidth=0.8
        )
        axes[2].plot([0, 1], [0, 1], "--", color="#AAAAAA", linewidth=0.8)
        axes[0].set(
            xlabel="False positive rate",
            ylabel="True positive rate",
            title="TCGA held-out ROC",
        )
        axes[1].set(
            xlabel="Recall",
            ylabel="Precision",
            title="TCGA held-out precision-recall",
        )
        axes[2].set(
            xlabel="Mean predicted probability",
            ylabel="Observed deep-deletion fraction",
            title="Calibration: quantile bins",
        )
        for ax in axes:
            ax.set_xlim(0, 1)
            ax.set_ylim(0, 1.02)
            ax.spines["top"].set_visible(False)
            ax.spines["right"].set_visible(False)
            ax.legend(
                frameon=False,
                fontsize=8,
                loc="upper center",
                bbox_to_anchor=(0.5, -0.2),
            )
        fig.subplots_adjust(
            left=0.06, right=0.99, bottom=0.3, top=0.9, wspace=0.32
        )
        for extension in ["pdf", "png"]:
            fig.savefig(
                FIG_DIR / f"TCGA_locked_test_evaluation.{extension}",
                dpi=350,
                bbox_inches="tight",
                facecolor="white",
            )
        plt.show()
        performance.to_csv(FINAL_RESULTS_FILE, sep="\t", index=False)

    main()
    _public_summary(
        globals(), "Eight-gene Elastic Net and three-gene L2 comparison"
    )

# %% [markdown]
##### Forty-five-feature Elastic Net development

# %%
@_nb9_registry.register("s26_0")
def _nb9_stage_s26_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import json
    import time
    import numpy as np
    import pandas as pd
    import joblib
    import matplotlib.pyplot as plt
    from sklearn.compose import ColumnTransformer
    from sklearn.impute import SimpleImputer
    from sklearn.preprocessing import StandardScaler, OneHotEncoder
    from sklearn.pipeline import Pipeline
    from sklearn.linear_model import LogisticRegression
    from sklearn.model_selection import GridSearchCV, StratifiedKFold
    from sklearn.metrics import (
        roc_auc_score,
        average_precision_score,
        brier_score_loss,
        log_loss,
        confusion_matrix,
        roc_curve,
        precision_recall_curve,
    )

    PROJECT = Path(str(PROJECT_ROOT))
    ROOT = PROJECT / "data_processed/MTAP_RNA_prediction"
    INPUT = ROOT / "15_region_multitask_DL/01_training_inputs"
    DL_DIR = ROOT / "15_region_multitask_DL/02_training_v1"
    OUT = ROOT / "15_region_multitask_DL/03_same_input_ElasticNet"
    X_FILE = INPUT / "X_development_signedlog.tsv"
    METADATA_FILE = INPUT / "development_metadata.tsv"
    DL_FILE = DL_DIR / "development_MTAP_OOF_predictions.tsv"
    for path in [X_FILE, METADATA_FILE, DL_FILE]:
        if not path.is_file():
            raise FileNotFoundError(
                "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
            )
    MODEL_DIR = OUT / "models"
    FIGURE_DIR = OUT / "figures"
    for directory in [OUT, MODEL_DIR, FIGURE_DIR]:
        directory.mkdir(parents=True, exist_ok=True)
    SEED = 2026
    INNER_FOLDS = 3
    N_JOBS = 4
    MAX_ITER = 10000
    TOL = 0.0001
    N_BOOTSTRAPS = 2000
    PARAM_GRID = {
        "model__C": [0.01, 0.1, 1.0, 10.0],
        "model__l1_ratio": [0.1, 0.5, 0.9],
    }
    started = time.monotonic()
    metadata = pd.read_csv(
        METADATA_FILE, sep="\t", dtype={"patient_id": str}
    ).set_index("patient_id")
    expression = pd.read_csv(X_FILE, sep="\t", index_col=0)
    dl = pd.read_csv(DL_FILE, sep="\t", dtype={"patient_id": str}).set_index(
        "patient_id"
    )
    expression.index = expression.index.astype(str)
    for name, table in [
        ("metadata", metadata),
        ("expression", expression),
        ("DL OOF", dl),
    ]:
        if table.index.duplicated().any():
            raise ValueError(
                "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
            )
    required_metadata = {"acronym", "dataset_split", "label_MTAP_deep"}
    required_dl = {
        "acronym",
        "label_MTAP_deep",
        "outer_fold",
        "prob_MTAP_deep",
    }
    if not required_metadata.issubset(metadata.columns):
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    if not required_dl.issubset(dl.columns):
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    if set(expression.index) != set(metadata.index) or set(dl.index) != set(
        metadata.index
    ):
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    if not metadata["dataset_split"].eq("development").all():
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    expression = expression.reindex(metadata.index)
    dl = dl.reindex(metadata.index)
    expression = expression.apply(pd.to_numeric, errors="raise")
    if expression.columns.duplicated().any():
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    if np.isinf(expression.to_numpy(dtype=float)).any():
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    y_series = pd.to_numeric(metadata["label_MTAP_deep"], errors="raise")
    if y_series.isna().any() or not y_series.isin([0, 1]).all():
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    y = y_series.to_numpy(dtype=int)
    dl_label = pd.to_numeric(dl["label_MTAP_deep"], errors="raise").to_numpy()
    if not np.array_equal(y, dl_label):
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    if not np.array_equal(
        metadata["acronym"].to_numpy(), dl["acronym"].to_numpy()
    ):
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    fold_values = pd.to_numeric(dl["outer_fold"], errors="raise")
    if (
        fold_values.isna().any()
        or not fold_values.eq(fold_values.astype(int)).all()
    ):
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    folds = fold_values.to_numpy(dtype=int)
    unique_folds = sorted(np.unique(folds))
    if len(unique_folds) != 5:
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    p_dl = pd.to_numeric(dl["prob_MTAP_deep"], errors="raise").to_numpy(
        dtype=float
    )
    if not np.isfinite(p_dl).all() or ((p_dl < 0) | (p_dl > 1)).any():
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    if len(metadata) != 7431 or y.sum() != 558 or expression.shape[1] != 45:
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    if metadata["acronym"].isna().any():
        raise ValueError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    feature_names = expression.columns.tolist()
    cancer_names = sorted(metadata["acronym"].unique())
    X = expression.copy()
    X["acronym"] = metadata["acronym"].astype(str)

    def make_pipeline():
        numeric_pipeline = Pipeline(
            [
                (
                    "imputer",
                    SimpleImputer(strategy="median", keep_empty_features=True),
                ),
                ("scaler", StandardScaler()),
            ]
        )
        preprocessing = ColumnTransformer(
            transformers=[
                ("expression", numeric_pipeline, feature_names),
                (
                    "cancer",
                    OneHotEncoder(
                        categories=[cancer_names],
                        handle_unknown="ignore",
                        sparse_output=False,
                    ),
                    ["acronym"],
                ),
            ],
            remainder="drop",
            sparse_threshold=0,
        )
        return Pipeline(
            [
                ("preprocessing", preprocessing),
                (
                    "model",
                    LogisticRegression(
                        penalty="elasticnet",
                        solver="saga",
                        class_weight=None,
                        max_iter=MAX_ITER,
                        tol=TOL,
                        random_state=SEED,
                    ),
                ),
            ]
        )

    def make_search(seed):
        inner_cv = StratifiedKFold(
            n_splits=INNER_FOLDS, shuffle=True, random_state=seed
        )
        return GridSearchCV(
            estimator=make_pipeline(),
            param_grid=PARAM_GRID,
            scoring="average_precision",
            cv=inner_cv,
            refit=True,
            n_jobs=N_JOBS,
            pre_dispatch=N_JOBS,
            error_score="raise",
            return_train_score=False,
        )

    def positive_probability(estimator, values):
        classes = estimator.named_steps["model"].classes_
        positions = np.flatnonzero(classes == 1)
        if len(positions) != 1:
            raise ValueError(
                "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
            )
        return estimator.predict_proba(values)[:, positions[0]]

    p_en = np.full(len(X), np.nan)
    fold_records = []
    for fold in unique_folds:
        train_index = np.flatnonzero(folds != fold)
        valid_index = np.flatnonzero(folds == fold)
        search = make_search(SEED + int(fold))
        search.fit(X.iloc[train_index], y[train_index])
        best_model = search.best_estimator_
        n_iterations = int(best_model.named_steps["model"].n_iter_.max())
        if n_iterations >= MAX_ITER:
            raise RuntimeError(
                "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
            )
        probability = positive_probability(best_model, X.iloc[valid_index])
        p_en[valid_index] = probability
        en_auc = roc_auc_score(y[valid_index], probability)
        en_ap = average_precision_score(y[valid_index], probability)
        dl_auc = roc_auc_score(y[valid_index], p_dl[valid_index])
        dl_ap = average_precision_score(y[valid_index], p_dl[valid_index])
        fold_records.append(
            {
                "outer_fold": int(fold),
                "n_train": len(train_index),
                "n_valid": len(valid_index),
                "best_C": search.best_params_["model__C"],
                "best_l1_ratio": search.best_params_["model__l1_ratio"],
                "inner_best_AP": search.best_score_,
                "n_iterations": n_iterations,
                "ElasticNet_AUROC": en_auc,
                "DL_AUROC": dl_auc,
                "ElasticNet_AP": en_ap,
                "DL_AP": dl_ap,
                "delta_AP_DL_minus_EN": dl_ap - en_ap,
            }
        )
        pd.DataFrame(search.cv_results_).to_csv(
            OUT / f"inner_search_fold{fold}.tsv", sep="\t", index=False
        )
        joblib.dump(best_model, MODEL_DIR / f"ElasticNet_fold{fold}.joblib")
        pd.DataFrame(fold_records).to_csv(
            OUT / "outer_fold_comparison.tsv", sep="\t", index=False
        )
    if not np.isfinite(p_en).all():
        raise RuntimeError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )

    def calculate_metrics(truth, probability):
        predicted = probability >= 0.5
        tn, fp, fn, tp = confusion_matrix(
            truth, predicted, labels=[0, 1]
        ).ravel()
        return {
            "AUROC": roc_auc_score(truth, probability),
            "AP": average_precision_score(truth, probability),
            "Brier_score": brier_score_loss(truth, probability),
            "log_loss": log_loss(truth, probability, labels=[0, 1]),
            "precision_at_05": tp / (tp + fp) if tp + fp else np.nan,
            "sensitivity_at_05": tp / (tp + fn),
            "specificity_at_05": tn / (tn + fp),
            "TP_at_05": int(tp),
            "FP_at_05": int(fp),
            "FN_at_05": int(fn),
            "TN_at_05": int(tn),
        }

    model_probabilities = {
        "Same_input_ElasticNet": p_en,
        "Regional_multitask_DL_3seed": p_dl,
    }
    performance = pd.DataFrame(
        [
            {
                "model": name,
                "n_patients": len(y),
                "n_positive": int(y.sum()),
                **calculate_metrics(y, probability),
            }
            for name, probability in model_probabilities.items()
        ]
    )
    performance.to_csv(
        OUT / "development_model_comparison.tsv", sep="\t", index=False
    )
    patient_results = pd.DataFrame(
        {
            "patient_id": metadata.index,
            "acronym": metadata["acronym"].to_numpy(),
            "label_MTAP_deep": y,
            "outer_fold": folds,
            "prob_ElasticNet": p_en,
            "prob_DL": p_dl,
        }
    )
    patient_results.to_csv(
        OUT / "paired_development_OOF_predictions.tsv", sep="\t", index=False
    )
    cancer_records = []
    for cancer in cancer_names:
        indices = np.flatnonzero(metadata["acronym"].to_numpy() == cancer)
        truth = y[indices]
        for name, probability in model_probabilities.items():
            record = {
                "acronym": cancer,
                "model": name,
                "n_patients": len(indices),
                "n_positive": int(truth.sum()),
                "n_negative": int((truth == 0).sum()),
            }
            if len(np.unique(truth)) == 2:
                record.update(calculate_metrics(truth, probability[indices]))
            else:
                record["AUROC"] = np.nan
                record["AP"] = np.nan
            cancer_records.append(record)
    pd.DataFrame(cancer_records).to_csv(
        OUT / "per_cancer_comparison.tsv", sep="\t", index=False
    )
    rng = np.random.default_rng(SEED)
    positive_index = np.flatnonzero(y == 1)
    negative_index = np.flatnonzero(y == 0)
    metric_functions = {
        "AUROC": roc_auc_score,
        "AP": average_precision_score,
        "Brier_score": brier_score_loss,
    }
    bootstrap_values = {
        name: {metric: np.empty(N_BOOTSTRAPS) for metric in metric_functions}
        for name in model_probabilities
    }
    for iteration in range(N_BOOTSTRAPS):
        sampled_index = np.concatenate(
            [
                rng.choice(
                    positive_index, size=len(positive_index), replace=True
                ),
                rng.choice(
                    negative_index, size=len(negative_index), replace=True
                ),
            ]
        )
        truth = y[sampled_index]
        for name, probability in model_probabilities.items():
            sampled_probability = probability[sampled_index]
            for metric, function in metric_functions.items():
                bootstrap_values[name][metric][iteration] = function(
                    truth, sampled_probability
                )
        if (iteration + 1) % 500 == 0:
            pass
    interval_records = []
    difference_records = []
    dl_name = "Regional_multitask_DL_3seed"
    en_name = "Same_input_ElasticNet"
    for metric, function in metric_functions.items():
        for name, probability in model_probabilities.items():
            low, high = np.quantile(
                bootstrap_values[name][metric], [0.025, 0.975]
            )
            interval_records.append(
                {
                    "model": name,
                    "metric": metric,
                    "estimate": function(y, probability),
                    "CI95_low": low,
                    "CI95_high": high,
                    "interval_scope": "Conditional_on_fixed_OOF_predictions",
                }
            )
        differences = (
            bootstrap_values[dl_name][metric]
            - bootstrap_values[en_name][metric]
        )
        low, high = np.quantile(differences, [0.025, 0.975])
        difference_records.append(
            {
                "metric": metric,
                "difference_DL_minus_ElasticNet": function(y, p_dl)
                - function(y, p_en),
                "CI95_low": low,
                "CI95_high": high,
                "favorable_direction": (
                    "negative" if metric == "Brier_score" else "positive"
                ),
                "CI_excludes_zero": bool(low > 0 or high < 0),
                "interval_scope": "Conditional_on_fixed_OOF_predictions",
            }
        )
    intervals = pd.DataFrame(interval_records)
    differences = pd.DataFrame(difference_records)
    intervals.to_csv(
        OUT / "paired_bootstrap_metric_intervals.tsv", sep="\t", index=False
    )
    differences.to_csv(
        OUT / "paired_bootstrap_DL_minus_ElasticNet.tsv", sep="\t", index=False
    )
    plt.rcParams.update(
        {
            "font.family": "DejaVu Sans",
            "font.size": 10,
            "pdf.fonttype": 42,
            "ps.fonttype": 42,
        }
    )
    colors = {en_name: "#33539E", dl_name: "#A5678E"}
    labels = {en_name: "Elastic Net", dl_name: "Regional multitask DL"}

# %% [markdown]
##### Model and threshold locking for the regional branch

# %%
@_nb9_registry.register("s27_0")
def _nb9_stage_s27_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    from datetime import datetime, timezone
    from importlib import metadata as package_metadata
    import hashlib
    import json
    import numpy as np
    import pandas as pd
    import torch
    import joblib

    PROJECT = Path(str(PROJECT_ROOT))
    ROOT = PROJECT / "data_processed/MTAP_RNA_prediction"
    BASE = ROOT / "15_region_multitask_DL"
    INPUT = BASE / "01_training_inputs"
    DL_DIR = BASE / "02_training_v1"
    EN_DIR = BASE / "03_same_input_ElasticNet"
    OUT = BASE / "04_locked_models_and_thresholds"
    MODEL_DIR = OUT / "models"
    RECORD_DIR = OUT / "records"
    THRESHOLD_DIR = OUT / "thresholds"
    for directory in [OUT, MODEL_DIR, RECORD_DIR, THRESHOLD_DIR]:
        directory.mkdir(parents=True, exist_ok=True)
    SEEDS = [41, 42, 43]
    RULES = {
        "positive_PPV_target": 0.9,
        "positive_Wilson_lower_min": 0.85,
        "positive_min_n": 30,
        "negative_NPV_target": 0.98,
        "negative_Wilson_lower_min": 0.97,
        "negative_min_n": 100,
        "high_group_rule": "probability >= high_threshold",
        "low_group_rule": "probability <= low_threshold",
        "threshold_selection": "Maximize group coverage among eligible development OOF cutoffs; require low < high",
        "interval_interpretation": "Descriptive after threshold search; not an external performance guarantee",
    }
    SOURCES = {
        "development_metadata": INPUT / "development_metadata.tsv",
        "development_expression": INPUT / "X_development_signedlog.tsv",
        "prediction_targets": INPUT / "prediction_targets.tsv",
        "expression_mapping": INPUT / "expression_member_mapping.tsv",
        "DL_training_manifest": DL_DIR / "training_manifest.json",
        "DL_OOF": DL_DIR / "development_MTAP_OOF_predictions.tsv",
        "paired_OOF": EN_DIR / "paired_development_OOF_predictions.tsv",
        "EN_model": EN_DIR
        / "models"
        / "same_input_ElasticNet_development_candidate.joblib",
    }
    for seed in SEEDS:
        SOURCES[f"DL_seed_{seed}"] = (
            DL_DIR / "models" / f"development_candidate_seed{seed}.pt"
        )
    for name, path in SOURCES.items():
        if not path.is_file():
            raise FileNotFoundError(
                "Model and threshold locking for the regional branch: integrity check failed; condition: input or artifact integrity check."
            )

    def sha256_file(path):
        digest = hashlib.sha256()
        with path.open("rb") as handle:
            for block in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(block)
        return digest.hexdigest()

    def write_once(path, content):
        if isinstance(content, str):
            content = content.encode("utf-8")
        if path.exists():
            if path.read_bytes() != content:
                raise RuntimeError(
                    "Model and threshold locking for the regional branch: integrity check failed; condition: input or artifact integrity check."
                )
        else:
            path.write_bytes(content)

    def copy_once(source, destination):
        write_once(destination, source.read_bytes())

    def save_table_once(table, path, index=False):
        write_once(path, table.to_csv(sep="\t", index=index))

    source_hashes = {name: sha256_file(path) for name, path in SOURCES.items()}
    manifest_file = OUT / "locked_manifest.json"
    old_manifest = None
    if manifest_file.exists():
        old_manifest = json.loads(manifest_file.read_text(encoding="utf-8"))
        if old_manifest["source_hashes"] != source_hashes:
            raise RuntimeError(
                "Model and threshold locking for the regional branch: integrity check failed; condition: input or artifact integrity check."
            )
        if old_manifest["threshold_rules"] != RULES:
            raise RuntimeError(
                "Model and threshold locking for the regional branch: integrity check failed; condition: input or artifact integrity check."
            )
    metadata = pd.read_csv(
        SOURCES["development_metadata"], sep="\t", dtype={"patient_id": str}
    ).set_index("patient_id")
    paired = pd.read_csv(
        SOURCES["paired_OOF"], sep="\t", dtype={"patient_id": str}
    ).set_index("patient_id")
    dl_oof = pd.read_csv(
        SOURCES["DL_OOF"], sep="\t", dtype={"patient_id": str}
    ).set_index("patient_id")
    for name, table in [
        ("metadata", metadata),
        ("paired OOF", paired),
        ("DL OOF", dl_oof),
    ]:
        if table.index.duplicated().any():
            raise ValueError(
                "Model and threshold locking for the regional branch: integrity check failed; condition: input or artifact integrity check."
            )
    if set(metadata.index) != set(paired.index) or set(metadata.index) != set(
        dl_oof.index
    ):
        raise ValueError(
            "Model and threshold locking for the regional branch: integrity check failed; condition: input or artifact integrity check."
        )
    if not metadata["dataset_split"].eq("development").all():
        raise ValueError(
            "Model and threshold locking for the regional branch: integrity check failed; condition: input or artifact integrity check."
        )
    paired = paired.reindex(metadata.index)
    dl_oof = dl_oof.reindex(metadata.index)
    y_series = pd.to_numeric(metadata["label_MTAP_deep"], errors="raise")
    if y_series.isna().any() or not y_series.isin([0, 1]).all():
        raise ValueError(
            "Model and threshold locking for the regional branch: integrity check failed; condition: input or artifact integrity check."
        )
    y = y_series.to_numpy(dtype=int)
