    feature_names = X_df.columns.tolist()
    fold_table = pd.read_csv(FOLD_FILE, sep="\t", dtype={"patient_id": str})
    if "patient_id" not in fold_table.columns:
        raise ValueError(
            "Regional multitask DL training and seed analysis: integrity check failed; condition: input or artifact integrity check."
        )

    def normalize_column_name(name):
        return "".join(
            (character for character in name.lower() if character.isalnum())
        )

    fold_candidates = [
        column
        for column in fold_table.columns
        if normalize_column_name(column)
        in {"fold", "cvfold", "outerfold", "foldid"}
    ]
