@_nb9_registry.register("s72_118")
def _nb9_stage_s72_118():
    module_spec = importlib.util.spec_from_file_location(
        "heldout_locked_TPM44_network", NETWORK_FILE
    )
    network_module = importlib.util.module_from_spec(module_spec)
    module_spec.loader.exec_module(network_module)
    device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
    seed_predictions = []
    for checkpoint_file in DL_FILES:
        checkpoint = torch.load(
            checkpoint_file, map_location="cpu", weights_only=False
        )
        if list(checkpoint["feature_names"]) != features:
            raise ValueError(
                "Final three-model evaluation on the original TCGA holdout: integrity check failed; condition: input or artifact integrity check."
            )
        network = network_module.RegionalMultiTaskNet(checkpoint)
        network.load_state_dict(checkpoint["state_dict"], strict=True)
        network.to(device).eval()
        preprocessing = checkpoint["preprocessing"]
        mean = np.asarray(preprocessing["mean"], dtype=np.float32)
        std = np.asarray(preprocessing["std"], dtype=np.float32)
        if not np.isfinite(mean).all() or not (std > 0).all():
            raise ValueError(
                "Final three-model evaluation on the original TCGA holdout: integrity check failed; condition: input or artifact integrity check."
            )
        values = (X.to_numpy(dtype=np.float32) - mean) / std
        cancer_mapping = checkpoint["cancer_to_index"]
        unknown = set(evaluation_meta["acronym"]) - set(cancer_mapping)
        if unknown:
            raise ValueError(
                "Final three-model evaluation on the original TCGA holdout: integrity check failed; condition: input or artifact integrity check."
            )
        cancer_codes = (
            evaluation_meta["acronym"]
            .map(cancer_mapping)
            .to_numpy(dtype=np.int64)
        )
        batches = []
        with torch.no_grad():
            for start in range(0, len(X), 512):
                expression_tensor = torch.from_numpy(
                    values[start : start + 512]
                ).to(device)
                cancer_tensor = torch.from_numpy(
                    cancer_codes[start : start + 512]
                ).to(device)
                output = torch.softmax(
                    network(expression_tensor, cancer_tensor), dim=-1
                )
                batches.append(
                    output[:, checkpoint["MTAP_INDEX"], 0].cpu().numpy()
                )
        seed_predictions.append(np.concatenate(batches))
        del network
    probabilities["Bulk_DL"] = np.mean(seed_predictions, axis=0)

