@_nb9_registry.register("s37_113")
def _nb9_stage_s37_113():
    network_file = LOCK / "region_multitask_TPM44_network.py"
    module_spec = importlib.util.spec_from_file_location(
        "locked_TPM44_network", network_file
    )
    network_module = importlib.util.module_from_spec(module_spec)
    module_spec.loader.exec_module(network_module)
    device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
    locked_dl = []
    for seed in [41, 42, 43]:
        checkpoint = torch.load(
            LOCK / "models" / f"DL_seed{seed}.pt",
            map_location="cpu",
            weights_only=False,
        )
        network = network_module.RegionalMultiTaskNet(checkpoint)
        network.load_state_dict(checkpoint["state_dict"], strict=True)
        network.to(device)
        network.eval()
        locked_dl.append((seed, checkpoint, network))
    locked_en_bundle = joblib.load(LOCK / "models/ElasticNet_locked.joblib")
    if locked_en_bundle["feature_names"] != features:
        raise ValueError(
            "Forty-four-member Elastic Net training and frozen CPTAC validation: integrity check failed; condition: input or artifact integrity check."
        )

    @torch.no_grad()
    def predict_locked_dl(frame, acronym):
        seed_probabilities = []
        for seed, checkpoint, network in locked_dl:
            expected_features = checkpoint["feature_names"]
            values = frame.loc[:, expected_features].to_numpy(dtype=np.float32)
            preprocessing = checkpoint["preprocessing"]
            mean = np.asarray(preprocessing["mean"], dtype=np.float32)
            std = np.asarray(preprocessing["std"], dtype=np.float32)
            if not np.isfinite(values).all():
                raise ValueError(
                    "Forty-four-member Elastic Net training and frozen CPTAC validation: integrity check failed; condition: input or artifact integrity check."
                )
            values = (values - mean) / std
            cancer_mapping = checkpoint["cancer_to_index"]
            if acronym not in cancer_mapping:
                raise ValueError(
                    "Forty-four-member Elastic Net training and frozen CPTAC validation: integrity check failed; condition: input or artifact integrity check."
                )
            codes = np.full(
                len(frame), cancer_mapping[acronym], dtype=np.int64
            )
            batches = []
            for start in range(0, len(frame), 1024):
                expression = torch.from_numpy(values[start : start + 1024]).to(
                    device
                )
                cancer = torch.from_numpy(codes[start : start + 1024]).to(
                    device
                )
                probabilities = torch.softmax(
                    network(expression, cancer), dim=-1
                )
                batches.append(
                    probabilities[:, checkpoint["MTAP_INDEX"], 0].cpu().numpy()
                )
            seed_probabilities.append(np.concatenate(batches))
        return np.mean(seed_probabilities, axis=0)

    external_tables = []
    external_file_hashes = {}
    for database_cancer, model_cancer in CANCER_MAP.items():
        expression_file = (
            CPTAC_X_DIR / database_cancer / "X_44_log2TPM_plus_1.tsv"
        )
        metadata_file = (
            CPTAC_META_DIR / database_cancer / "paired_patient_metadata.tsv"
        )
        expression = pd.read_csv(expression_file, sep="\t", index_col=0)
        expression.index = expression.index.astype(str)
        if expression.index.duplicated().any():
            raise ValueError(
                "Forty-four-member Elastic Net training and frozen CPTAC validation: integrity check failed; condition: input or artifact integrity check."
            )
        expression = expression.loc[:, features].apply(
            pd.to_numeric, errors="raise"
        )
        if not np.isfinite(expression.to_numpy()).all():
            raise ValueError(
                "Forty-four-member Elastic Net training and frozen CPTAC validation: integrity check failed; condition: input or artifact integrity check."
            )
        probability_dl = predict_locked_dl(expression, model_cancer)
        en_input = expression.copy()
        en_input["acronym"] = model_cancer
        probability_en = locked_en_bundle["pipeline"].predict_proba(en_input)[
            :, 1
        ]
        external_meta = pd.read_csv(
            metadata_file,
            sep="\t",
            usecols=["patient_id", "acronym", "MTAP_GISTIC_call"],
            dtype={"patient_id": str, "acronym": str},
        )
        if external_meta["patient_id"].duplicated().any():
            raise ValueError(
                "Forty-four-member Elastic Net training and frozen CPTAC validation: integrity check failed; condition: input or artifact integrity check."
            )
        external_meta = external_meta.set_index("patient_id")
        if set(external_meta.index) != set(expression.index):
            raise ValueError(
                "Forty-four-member Elastic Net training and frozen CPTAC validation: integrity check failed; condition: input or artifact integrity check."
            )
        external_meta = external_meta.loc[expression.index]
        if set(external_meta["acronym"]) != {model_cancer}:
            raise ValueError(
                "Forty-four-member Elastic Net training and frozen CPTAC validation: integrity check failed; condition: input or artifact integrity check."
            )
        calls = pd.to_numeric(
            external_meta["MTAP_GISTIC_call"], errors="raise"
        )
        if (calls.notna() & ~calls.isin([-2, -1, 0, 1, 2])).any():
            raise ValueError(
                "Forty-four-member Elastic Net training and frozen CPTAC validation: integrity check failed; condition: input or artifact integrity check."
            )
        labels = pd.Series(pd.NA, index=expression.index, dtype="Int64")
        observed = calls.notna()
        labels.loc[observed] = calls.loc[observed].eq(-2).astype(int)
        result = pd.DataFrame(
            {
                "patient_id": expression.index,
                "database_cancer": database_cancer,
                "acronym": model_cancer,
                "MTAP_GISTIC_call": calls.to_numpy(),
                "label_MTAP_deep": labels.to_numpy(),
                "prob_DL": probability_dl,
                "prob_ElasticNet": probability_en,
                "group_DL": classify_groups(
                    probability_dl, locked_thresholds[DL_NAME]
                ),
                "group_ElasticNet": classify_groups(
                    probability_en, locked_thresholds[EN_NAME]
                ),
            }
        )
        external_tables.append(result)
        external_file_hashes[str(expression_file)] = sha256_file(
            expression_file
        )
        external_file_hashes[str(metadata_file)] = sha256_file(metadata_file)
    external_predictions = pd.concat(external_tables, ignore_index=True)
    if external_predictions["patient_id"].duplicated().any():
        duplicated = external_predictions.loc[
            external_predictions["patient_id"].duplicated(keep=False),
            ["patient_id", "database_cancer"],
        ]
        duplicated.to_csv(
            EXTERNAL_OUT / "duplicate_patient_review.tsv",
            sep="\t",
            index=False,
        )
        raise ValueError(
            "Forty-four-member Elastic Net training and frozen CPTAC validation: integrity check failed; condition: input or artifact integrity check."
        )
    external_predictions.to_csv(
        EXTERNAL_OUT / "CPTAC_patient_predictions.tsv", sep="\t", index=False
    )
    evaluation = external_predictions.loc[
        external_predictions["label_MTAP_deep"].notna()
    ].copy()
    evaluation["label_MTAP_deep"] = evaluation["label_MTAP_deep"].astype(int)
    probability_columns = {DL_NAME: "prob_DL", EN_NAME: "prob_ElasticNet"}
    metric_rows = []
    group_rows = []
    difference_rows = []
    subsets = [("ALL_CPTAC", evaluation)]
    subsets += [
        (
            database_cancer,
            evaluation.loc[
                evaluation["database_cancer"].eq(database_cancer)
            ].copy(),
        )
        for database_cancer in CANCER_MAP
    ]
    for subset_position, (cohort, data) in enumerate(subsets):
        data = data.reset_index(drop=True)
        if data.empty:
            continue
        yy = data["label_MTAP_deep"].to_numpy(dtype=int)
        point_metrics = {}
        bootstrap_metrics = {
            name: {metric: [] for metric in ["AUROC", "AP", "Brier_score"]}
            for name in MODEL_NAMES
        }
        for name in MODEL_NAMES:
            point_metrics[name] = performance(
                yy, data[probability_columns[name]].to_numpy()
            )
            group_rows.extend(
                group_summary(
                    yy,
                    data[probability_columns[name]].to_numpy(),
                    locked_thresholds[name],
                    name,
                    cohort,
                )
            )
        strata = list(
            data.groupby(
                ["database_cancer", "label_MTAP_deep"], sort=True
            ).indices.values()
        )
        rng = np.random.default_rng(RANDOM_SEED + subset_position)
        for bootstrap in range(N_BOOTSTRAPS):
            sampled = np.concatenate(
                [
                    rng.choice(indices, size=len(indices), replace=True)
                    for indices in strata
                ]
            )
            y_boot = yy[sampled]
            has_both = len(np.unique(y_boot)) == 2
            for name in MODEL_NAMES:
                p_boot = data[probability_columns[name]].to_numpy()[sampled]
                bootstrap_metrics[name]["AUROC"].append(
                    roc_auc_score(y_boot, p_boot) if has_both else np.nan
                )
                bootstrap_metrics[name]["AP"].append(
                    average_precision_score(y_boot, p_boot)
                    if has_both
                    else np.nan
                )
                bootstrap_metrics[name]["Brier_score"].append(
                    brier_score_loss(y_boot, p_boot)
                )
        n_positive = int(yy.sum())
        n_negative = int((yy == 0).sum())
        if min(n_positive, n_negative) == 0:
            support = "Single_class_no_AUROC_or_AP"
        elif min(n_positive, n_negative) < 10:
            support = "Very_limited_class_support"
        elif min(n_positive, n_negative) < 20:
            support = "Limited_class_support"
        else:
            support = "Descriptive_evaluation"
        for name in MODEL_NAMES:
            row = {
                "cohort": cohort,
                "model": name,
                **point_metrics[name],
                "support_status": support,
            }
            for metric in ["AUROC", "AP", "Brier_score"]:
                values = np.asarray(
                    bootstrap_metrics[name][metric], dtype=float
                )
                values = values[np.isfinite(values)]
                if len(values):
                    low, high = np.quantile(values, [0.025, 0.975])
                else:
                    low, high = (np.nan, np.nan)
                row[f"{metric}_CI95_low"] = low
                row[f"{metric}_CI95_high"] = high
            metric_rows.append(row)
        for metric in ["AUROC", "AP", "Brier_score"]:
            difference = np.asarray(
                bootstrap_metrics[DL_NAME][metric], dtype=float
            ) - np.asarray(bootstrap_metrics[EN_NAME][metric], dtype=float)
            difference = difference[np.isfinite(difference)]
            if len(difference):
                low, high = np.quantile(difference, [0.025, 0.975])
            else:
                low, high = (np.nan, np.nan)
            difference_rows.append(
                {
                    "cohort": cohort,
                    "metric": metric,
                    "difference_DL_minus_ElasticNet": point_metrics[DL_NAME][
                        metric
                    ]
                    - point_metrics[EN_NAME][metric],
                    "CI95_low": low,
                    "CI95_high": high,
                    "favorable_direction": (
                        "negative" if metric == "Brier_score" else "positive"
                    ),
                    "interval_scope": "Conditional_on_frozen_models; cancer_by_label_stratified_patient_bootstrap",
                }
            )
    metrics_table = pd.DataFrame(metric_rows)
    groups_table = pd.DataFrame(group_rows)
    differences_table = pd.DataFrame(difference_rows)
    metrics_table.to_csv(
        EXTERNAL_OUT / "CPTAC_external_performance.tsv", sep="\t", index=False
    )
    groups_table.to_csv(
        EXTERNAL_OUT / "CPTAC_locked_threshold_group_results.tsv",
        sep="\t",
        index=False,
    )
    differences_table.to_csv(
        EXTERNAL_OUT / "CPTAC_paired_model_differences.tsv",
        sep="\t",
        index=False,
    )

# %% [markdown]
##### CPTAC frozen L2 inference and matched three-model metrics

# %%
@_nb9_registry.register("s39_95")
def _nb9_stage_s39_95():
    external = pd.read_csv(
        EXTERNAL_PREDICTIONS_FILE,
        sep="\t",
        dtype={"patient_id": str, "database_cancer": str, "acronym": str},
    )
    if external["patient_id"].duplicated().any():
        raise ValueError(
            "Final TPM three-model comparison and L2 locking: integrity check failed; condition: input or artifact integrity check."
        )
    external["prob_L2"] = np.nan
    external_input_hashes = {}
    for database_cancer, model_cancer in CANCER_MAP.items():
        expression_file = (
            CPTAC_INPUT / database_cancer / "X_44_log2TPM_plus_1.tsv"
        )
        expression = pd.read_csv(expression_file, sep="\t", index_col=0)
        expression.index = expression.index.astype(str)
        if expression.index.duplicated().any():
            raise ValueError(
                "Final TPM three-model comparison and L2 locking: integrity check failed; condition: input or artifact integrity check."
            )
        selected = external["database_cancer"].eq(database_cancer)
        ids = external.loc[selected, "patient_id"].tolist()
        if set(expression.index) != set(ids):
            raise ValueError(
                "Final TPM three-model comparison and L2 locking: integrity check failed; condition: input or artifact integrity check."
            )
        if set(external.loc[selected, "acronym"]) != {model_cancer}:
            raise ValueError(
                "Final TPM three-model comparison and L2 locking: integrity check failed; condition: input or artifact integrity check."
            )
        expression = expression.loc[ids, CORE_GENES].apply(
            pd.to_numeric, errors="raise"
        )
        if not np.isfinite(expression.to_numpy()).all():
            raise ValueError(
                "Final TPM three-model comparison and L2 locking: integrity check failed; condition: input or artifact integrity check."
            )
        model_input = expression.copy()
        model_input["acronym"] = model_cancer
        external.loc[selected, "prob_L2"] = bundle["pipeline"].predict_proba(
            model_input
        )[:, 1]
        external_input_hashes[str(expression_file)] = sha256_file(
            expression_file
        )
    if external["prob_L2"].isna().any():
        raise ValueError(
            "Final TPM three-model comparison and L2 locking: integrity check failed; condition: input or artifact integrity check."
        )
    external["group_L2"] = classify_groups(external["prob_L2"], l2_thresholds)
    external.to_csv(
        OUT / "CPTAC_three_model_patient_predictions.tsv",
        sep="\t",
        index=False,
    )
    observed_labels = pd.to_numeric(
        external["label_MTAP_deep"], errors="raise"
    )
    evaluation = external.loc[observed_labels.notna()].copy()
    evaluation["label_MTAP_deep"] = observed_labels.loc[
        evaluation.index
    ].astype(int)
    if not evaluation["label_MTAP_deep"].isin([0, 1]).all():
        raise ValueError(
            "Final TPM three-model comparison and L2 locking: integrity check failed; condition: input or artifact integrity check."
        )
    metric_rows = []
    group_rows = []
    difference_rows = []
    subsets = [("ALL_CPTAC", evaluation)]
    subsets += [
        (cancer, evaluation.loc[evaluation["database_cancer"].eq(cancer)])
        for cancer in CANCER_MAP
    ]
    for subset_position, (cohort, frame) in enumerate(subsets):
        frame = frame.reset_index(drop=True)
        if frame.empty:
            continue
        yy = frame["label_MTAP_deep"].to_numpy(dtype=int)
        probabilities = {
            name: frame[PROBABILITY_COLUMNS[name]].to_numpy(dtype=float)
            for name in MODEL_NAMES
        }
        points = {
            name: performance(yy, probabilities[name]) for name in MODEL_NAMES
        }
        samples = {
            name: {metric: [] for metric in ["AUROC", "AP", "Brier_score"]}
            for name in MODEL_NAMES
        }
        strata = list(
            frame.groupby(
                ["database_cancer", "label_MTAP_deep"], sort=True
            ).indices.values()
        )
        rng = np.random.default_rng(RANDOM_SEED + subset_position)
        for bootstrap in range(N_BOOTSTRAPS):
            indices = np.concatenate(
                [
                    rng.choice(positions, size=len(positions), replace=True)
                    for positions in strata
                ]
            )
            y_boot = yy[indices]
            has_both = len(np.unique(y_boot)) == 2
            for name in MODEL_NAMES:
                p_boot = probabilities[name][indices]
                samples[name]["AUROC"].append(
                    roc_auc_score(y_boot, p_boot) if has_both else np.nan
                )
                samples[name]["AP"].append(
                    average_precision_score(y_boot, p_boot)
                    if has_both
                    else np.nan
                )
                samples[name]["Brier_score"].append(
                    brier_score_loss(y_boot, p_boot)
                )
        smallest_class = min(int((yy == 1).sum()), int((yy == 0).sum()))
        if smallest_class == 0:
            support = "Single_class_no_AUROC_or_AP"
        elif smallest_class < 10:
            support = "Very_limited_class_support"
        elif smallest_class < 20:
            support = "Limited_class_support"
        else:
            support = "Descriptive_evaluation"
        for name in MODEL_NAMES:
            row = {
                "cohort": cohort,
                "model": name,
                **points[name],
                "support_status": support,
            }
            for metric in ["AUROC", "AP", "Brier_score"]:
                values = np.asarray(samples[name][metric], dtype=float)
                values = values[np.isfinite(values)]
                if len(values):
                    low, high = np.quantile(values, [0.025, 0.975])
                else:
                    low, high = (np.nan, np.nan)
                row[f"{metric}_CI95_low"] = low
                row[f"{metric}_CI95_high"] = high
            metric_rows.append(row)
            group_rows.extend(
                summarize_groups(
                    yy, probabilities[name], all_thresholds[name], name, cohort
                )
            )
        for main_model in [DL_NAME, EN_NAME]:
            for metric in ["AUROC", "AP", "Brier_score"]:
                differences = np.asarray(
                    samples[main_model][metric], dtype=float
                ) - np.asarray(samples[L2_NAME][metric], dtype=float)
                differences = differences[np.isfinite(differences)]
                if len(differences):
                    low, high = np.quantile(differences, [0.025, 0.975])
                else:
                    low, high = (np.nan, np.nan)
                difference_rows.append(
                    {
                        "cohort": cohort,
                        "main_model": main_model,
                        "comparator": L2_NAME,
                        "metric": metric,
                        "difference_main_minus_L2": points[main_model][metric]
                        - points[L2_NAME][metric],
                        "CI95_low": low,
                        "CI95_high": high,
                        "favorable_direction": (
                            "negative"
                            if metric == "Brier_score"
                            else "positive"
                        ),
                        "interval_scope": "Conditional_on_frozen_models;cancer_by_label_stratified_patient_bootstrap",
                    }
                )
    external_metrics = pd.DataFrame(metric_rows)
    external_groups = pd.DataFrame(group_rows)
    external_differences = pd.DataFrame(difference_rows)
    external_metrics.to_csv(
        OUT / "CPTAC_three_model_performance.tsv", sep="\t", index=False
    )
    external_groups.to_csv(
        OUT / "CPTAC_three_model_locked_threshold_groups.tsv",
        sep="\t",
        index=False,
    )
    external_differences.to_csv(
        OUT / "CPTAC_paired_comparison_vs_L2.tsv", sep="\t", index=False
    )
    yy = evaluation["label_MTAP_deep"].to_numpy(dtype=int)

