    review.to_csv(
        OUT / "patient_DNA_and_prediction_review.tsv", sep="\t", index=False
    )
    dna_summary_rows = []
    pattern_rows = []
    subsets = [("ALL_CPTAC", review)]
    subsets += [
        (cancer, review.loc[review["database_cancer"].eq(cancer)])
        for cancer in CANCERS
    ]
    for cohort_name, frame in subsets:
        for model, short_name in [(DL_NAME, "DL"), (L2_NAME, "L2")]:
            error_column = f"{short_name}_error_at_05"
            for (call, error), group in frame.groupby(
                ["MTAP_GISTIC_call", error_column], dropna=False
            ):
                row = {
                    "cohort": cohort_name,
                    "model": model,
                    "MTAP_GISTIC_call": int(call),
                    "error_at_05": error,
                    "n_patients": len(group),
                    "median_probability": group[MODEL_COLUMNS[model]].median(),
                    "n_purity_available": int(
                        group["ABSOLUTE_purity"].notna().sum()
                    ),
                    "median_purity": group["ABSOLUTE_purity"].median(),
                }
                for gene in GENES:
                    column = f"{gene}_DNA_log2ratio"
                    values = group[column].dropna()
                    row[f"{gene}_n_continuous"] = len(values)
                    row[f"{gene}_log2ratio_Q1"] = values.quantile(0.25)
                    row[f"{gene}_log2ratio_median"] = values.median()
                    row[f"{gene}_log2ratio_Q3"] = values.quantile(0.75)
                dna_summary_rows.append(row)
            counts = frame.groupby(
                ["MTAP_GISTIC_call", error_column, "CDKN2A_B_pattern"],
                dropna=False,
            ).size()
            for (call, error, pattern), n in counts.items():
                pattern_rows.append(
                    {
                        "cohort": cohort_name,
                        "model": model,
                        "MTAP_GISTIC_call": int(call),
                        "error_at_05": error,
                        "CDKN2A_B_pattern": pattern,
                        "n_patients": int(n),
                    }
                )
    dna_summary = pd.DataFrame(dna_summary_rows)
    patterns = pd.DataFrame(pattern_rows)
    dna_summary.to_csv(
        OUT / "DNA_signal_by_call_and_prediction_error.tsv",
        sep="\t",
        index=False,
    )
    patterns.to_csv(
        OUT / "CDKN2A_B_patterns_by_prediction_error.tsv",
        sep="\t",
        index=False,
    )
    colors = {DL_NAME: "#33539E", L2_NAME: "#A5678E"}
    from sklearn.metrics import roc_curve, precision_recall_curve

