@_nb9_registry.register("s45_0")
def _nb9_stage_s45_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import importlib.util

    PROJECT = Path(str(PROJECT_ROOT))
    SEARCH_DIRS = [
        PROJECT / "data_raw" / "GBM",
        PROJECT / "data_processed" / "CPTAC_GBM_joint_analysis",
    ]
    H5AD_FILE = None
    if importlib.util.find_spec("h5py") is None:
        raise ImportError(
            "Single-cell input structure audit: integrity check failed; condition: input or artifact integrity check."
        )
    import h5py

    if H5AD_FILE is not None:
        paths = [Path(H5AD_FILE)]
        if not paths[0].is_file():
            raise FileNotFoundError(paths[0])
    else:
        paths = sorted(
            {
                p
                for directory in SEARCH_DIRS
                if directory.exists()
                for p in directory.rglob("*.h5ad")
            }
        )
    for i, p in enumerate(paths, 1):
        pass
    if not paths:
        pass

    def decode_attr(value):
        if isinstance(value, bytes):
            return value.decode("utf-8")
        return value

    def describe_matrix(node):
        """Inspect matrix shape and encoding without loading count values."""
        if isinstance(node, h5py.Dataset):
            return {
                "encoding": "dense",
                "shape": tuple(node.shape),
                "dtype": str(node.dtype),
            }
        shape = node.attrs.get("shape", None)
        return {
            "encoding": decode_attr(
                node.attrs.get("encoding-type", "unknown")
            ),
            "shape": (
                tuple((int(x) for x in shape)) if shape is not None else None
            ),
            "dtype": str(node["data"].dtype) if "data" in node else None,
        }

    inspect_paths = paths if H5AD_FILE is not None else paths[:10]
    for path in inspect_paths:
        try:
            with h5py.File(path, "r") as f:
                if "X" in f:
                    pass
                if "layers" in f:
                    for name, node in f["layers"].items():
                        pass
                if "raw" in f and "X" in f["raw"]:
                    pass
                for axis in ["obs", "var"]:
                    if axis not in f:
                        continue
                    group = f[axis]
                    if axis == "obs":
                        keywords = (
                            "patient",
                            "case",
                            "sample",
                            "donor",
                            "celltype",
                            "cell_type",
                            "annotation",
                            "tumor",
                            "malignan",
                            "cluster",
                            "mtap",
                        )
                        for name, node in group.items():
                            if not any((k in name.lower() for k in keywords)):
                                continue
                            if (
                                isinstance(node, h5py.Group)
                                and "categories" in node
                            ):
                                values = node["categories"][:]
                                values = [decode_attr(x) for x in values]
                            elif isinstance(node, h5py.Dataset):
                                pass
        except Exception as exc:
            pass
    _public_summary(globals(), "Single-cell input structure audit")

