@_nb9_registry.register("s48_0")
def _nb9_stage_s48_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import h5py
    import numpy as np
    import pandas as pd

    PROJECT = Path(str(PROJECT_ROOT))
    SOURCE = PROJECT / "data_raw/GBM/NIHMS1665743/snRNA"
    OUT = (
        PROJECT
        / "data_processed/MTAP_RNA_prediction"
        / "16_scRNA_transfer/02_HDF5_expression_review"
    )
    OUT.mkdir(parents=True, exist_ok=True)
    files = sorted(SOURCE.glob("*_seurat.hdf5"))
    if not files:
        raise FileNotFoundError(
            "Representative HDF5 structure inspection: integrity check failed; condition: input or artifact integrity check."
        )
    for path in files:
        pass
    inventory = []
    for path in files:
        patient = path.name.removesuffix("_seurat.hdf5")
        with h5py.File(path, "r") as f:
            records = []

            def visitor(name, obj):
                if isinstance(obj, h5py.Dataset):
                    interesting = (
                        obj.ndim == 2
                        or any(
                            (
                                key in name.lower()
                                for key in (
                                    "count",
                                    "raw",
                                    "umi",
                                    "barcode",
                                    "cellid",
                                )
                            )
                        )
                        or name.endswith(("/indices", "/indptr"))
                    )
                    if interesting:
                        records.append(
                            {
                                "patient_id": patient,
                                "file": str(path),
                                "dataset": name,
                                "shape": str(tuple(obj.shape)),
                                "dtype": str(obj.dtype),
                            }
                        )

            f.visititems(visitor)
            inventory.extend(records)
            for group_name in ["layers", "assays"]:
                if group_name in f and isinstance(f[group_name], h5py.Group):
                    pass
            matrix_rows = [
                r for r in records if len(f[r["dataset"]].shape) == 2
            ]
            for row in matrix_rows:
                pass
    inventory = pd.DataFrame(inventory)
    inventory.to_csv(
        OUT / "HDF5_expression_dataset_inventory.tsv", sep="\t", index=False
    )
    example = files[0]

    def as_text(x):
        return x.decode("utf-8") if isinstance(x, bytes) else str(x)

    results = []
    with h5py.File(example, "r") as f:
        required = ["row_attrs/Gene", "col_attrs/CellID"]
        missing = [name for name in required if name not in f]
        if missing:
            raise ValueError(
                "Representative HDF5 structure inspection: integrity check failed; condition: input or artifact integrity check."
            )
        n_genes = f["row_attrs/Gene"].size
        n_cells = f["col_attrs/CellID"].size
        selected_cells = np.unique(
            np.linspace(0, n_cells - 1, num=min(8, n_cells), dtype=int)
        )
        expected_counts = {}
        for field in ["nCount_RNA", "nCount_SCT"]:
            location = f"col_attrs/{field}"
            if location in f:
                values = np.asarray(f[location][:]).ravel()
                if len(values) != n_cells:
                    raise ValueError(
                        "Representative HDF5 structure inspection: integrity check failed; condition: input or artifact integrity check."
                    )
                expected_counts[field] = values[selected_cells].astype(float)
        matrices = []

        def find_matrices(name, obj):
            if not isinstance(obj, h5py.Dataset):
                return
            if obj.ndim != 2 or obj.dtype.kind not in "iuf":
                return
            if obj.shape in [(n_genes, n_cells), (n_cells, n_genes)]:
                matrices.append(name)

        f.visititems(find_matrices)
        check_names = [
            name
            for name in matrices
            if (
                "count" in name.lower()
                or "raw" in name.lower()
                or "umi" in name.lower()
                or (name == "matrix")
                or name.lower().endswith("/rna")
            )
            and "scale" not in name.lower()
        ]
        for name in check_names:
            ds = f[name]
            if n_genes == n_cells:
                raise ValueError(
                    "Representative HDF5 structure inspection: integrity check failed; condition: input or artifact integrity check."
                )
            genes_by_cells = ds.shape == (n_genes, n_cells)
            sums = np.zeros(len(selected_cells), dtype=np.float64)
            n_values = 0
            n_nonfinite = 0
            n_negative = 0
            n_noninteger = 0
            for start in range(0, n_genes, 512):
                end = min(start + 512, n_genes)
                if genes_by_cells:
                    block = np.asarray(
                        ds[start:end, selected_cells], dtype=np.float64
                    )
                else:
                    block = np.asarray(
                        ds[selected_cells, start:end], dtype=np.float64
                    ).T
                sums += block.sum(axis=0)
                finite_mask = np.isfinite(block)
                values = block[finite_mask]
                n_values += block.size
                n_nonfinite += int((~finite_mask).sum())
                n_negative += int((values < 0).sum())
                n_noninteger += int(
                    (
                        ~np.isclose(
                            values, np.rint(values), atol=1e-05, rtol=0
                        )
                    ).sum()
                )
            row = {
                "file": example.name,
                "matrix": name,
                "n_sampled_cells": len(selected_cells),
                "n_checked_values": n_values,
                "n_nonfinite": n_nonfinite,
                "n_negative": n_negative,
                "noninteger_fraction_among_finite": (
                    n_noninteger / (n_values - n_nonfinite)
                    if n_values > n_nonfinite
                    else np.nan
                ),
            }
            for field, expected in expected_counts.items():
                valid = (
                    np.isfinite(expected) & np.isfinite(sums) & (expected > 0)
                )
                row[f"median_relative_error_vs_{field}"] = (
                    float(
                        np.median(
                            np.abs(sums[valid] - expected[valid])
                            / expected[valid]
                        )
                    )
                    if valid.any()
                    else np.nan
                )
            results.append(row)
            for key, value in row.items():
                if key not in {"file", "matrix"}:
                    pass
    if results:
        pd.DataFrame(results).to_csv(
            OUT / "representative_matrix_count_comparison.tsv",
            sep="\t",
            index=False,
        )
    _public_summary(globals(), "Representative HDF5 structure inspection")

# %% [markdown]
##### Public GBM source and annotation resolution

# %%
@_nb9_registry.register("s49_0")
def _nb9_stage_s49_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import json
    import re
    import urllib.parse
    import urllib.request
    import pandas as pd

    PROJECT = Path(str(PROJECT_ROOT))
    BASE = PROJECT / "data_processed/MTAP_RNA_prediction/16_scRNA_transfer"
    PATIENT_FILE = (
        BASE / "01_source_resolution/patient_DNA_and_cell_coverage.tsv"
    )
    OUT = BASE / "03_GDC_original_counts_search"
    OUT.mkdir(parents=True, exist_ok=True)
    if not PATIENT_FILE.is_file():
        raise FileNotFoundError(PATIENT_FILE)
    patients = pd.read_csv(PATIENT_FILE, sep="\t", dtype={"patient_id": str})
    required = {"patient_id", "MTAP_GISTIC_call"}
    if not required.issubset(patients.columns):
        raise ValueError(
            "Public GBM source and annotation resolution: integrity check failed; condition: input or artifact integrity check."
        )
    if patients["patient_id"].isna().any():
        raise ValueError(
            "Public GBM source and annotation resolution: integrity check failed; condition: input or artifact integrity check."
        )
    if patients["patient_id"].duplicated().any():
        raise ValueError(
            "Public GBM source and annotation resolution: integrity check failed; condition: input or artifact integrity check."
        )
    patient_ids = patients["patient_id"].tolist()
    filters = {
        "op": "in",
        "content": {"field": "cases.submitter_id", "value": patient_ids},
    }
    fields = [
        "file_id",
        "file_name",
        "file_size",
        "data_category",
        "data_type",
        "data_format",
        "experimental_strategy",
        "access",
        "md5sum",
        "cases.submitter_id",
        "cases.project.project_id",
        "analysis.workflow_type",
    ]
    hits = []
    offset = 0
    page_size = 500
    while True:
        params = {
            "filters": json.dumps(filters),
            "fields": ",".join(fields),
            "format": "JSON",
            "size": page_size,
            "from": offset,
        }
        url = "https://api.gdc.cancer.gov/files?" + urllib.parse.urlencode(
            params
        )
        request = urllib.request.Request(
            url, headers={"Accept": "application/json"}
        )
        try:
            with urllib.request.urlopen(request, timeout=60) as response:
                payload = json.load(response)
        except Exception as exc:
            raise RuntimeError(
                "Public GBM source and annotation resolution: integrity check failed; condition: input or artifact integrity check."
            ) from exc
        data = payload["data"]
        batch = data.get("hits", [])
        total = int(data["pagination"]["total"])
        hits.extend(batch)
        if len(hits) >= total:
            break
        if not batch:
            raise RuntimeError(
                "Public GBM source and annotation resolution: integrity check failed; condition: input or artifact integrity check."
            )
        offset += len(batch)
    with open(OUT / "GDC_file_metadata.json", "w", encoding="utf-8") as handle:
        json.dump(hits, handle, ensure_ascii=False, indent=2)
    records = []
    for hit in hits:
        cases = hit.get("cases", [])
        case_ids = sorted(
            {
                case.get("submitter_id", "")
                for case in cases
                if case.get("submitter_id")
            }
        )
        projects = sorted(
            {
                case.get("project", {}).get("project_id", "")
                for case in cases
                if case.get("project", {}).get("project_id")
            }
        )
        analysis = hit.get("analysis") or {}
        if isinstance(analysis, dict):
            workflow = analysis.get("workflow_type", "")
        else:
            workflow = ""
        records.append(
            {
                "file_id": hit.get("file_id", ""),
                "file_name": hit.get("file_name", ""),
                "file_size_MB": float(hit.get("file_size") or 0) / 1024**2,
                "data_category": hit.get("data_category", ""),
                "data_type": hit.get("data_type", ""),
                "data_format": hit.get("data_format", ""),
                "experimental_strategy": hit.get("experimental_strategy", ""),
                "access": hit.get("access", ""),
                "workflow_type": workflow,
                "patient_ids": ";".join(case_ids),
                "projects": ";".join(projects),
                "md5sum": hit.get("md5sum", ""),
            }
        )
    columns = [
        "file_id",
        "file_name",
        "file_size_MB",
        "data_category",
        "data_type",
        "data_format",
        "experimental_strategy",
        "access",
        "workflow_type",
        "patient_ids",
        "projects",
        "md5sum",
    ]
    table = pd.DataFrame(records, columns=columns)
    table.to_csv(OUT / "all_patient_GDC_files.tsv", sep="\t", index=False)
    if table.empty:
        pass
    else:
        summary = (
            table.groupby(
                [
                    "experimental_strategy",
                    "data_type",
                    "data_format",
                    "access",
                ],
                dropna=False,
            )
            .size()
            .rename("n_files")
            .reset_index()
        )
        summary.to_csv(
            OUT / "GDC_file_type_summary.tsv", sep="\t", index=False
        )
        text = (
            table[
                [
                    "file_name",
                    "experimental_strategy",
                    "data_type",
                    "workflow_type",
                ]
            ]
            .fillna("")
            .astype(str)
            .agg(" ".join, axis=1)
        )
        explicit_single_cell = text.str.contains(
            "single[\\s_-]*(cell|nucle)|scrna|snrna|10x|chromium|cell[\\s_-]*ranger|seurat",
            case=False,
            regex=True,
        )
        rna_or_expression = text.str.contains(
            "rna|expression|transcript", case=False, regex=True
        ) | table["data_category"].str.contains(
            "Transcriptome", case=False, na=False
        )
        candidates = table.loc[explicit_single_cell | rna_or_expression].copy()
        candidates["explicit_single_cell_keyword"] = explicit_single_cell.loc[
            candidates.index
        ]
        candidates.to_csv(
            OUT / "RNA_and_single_cell_candidates.tsv", sep="\t", index=False
        )
        show_columns = [
            "file_name",
            "experimental_strategy",
            "data_type",
            "data_format",
            "access",
            "file_size_MB",
            "explicit_single_cell_keyword",
        ]
        display = candidates.sort_values(
            ["explicit_single_cell_keyword", "access", "file_size_MB"],
            ascending=[False, True, True],
        )
        if len(display) > 60:
            pass
        matched = {
            case_id
            for value in table["patient_ids"]
            for case_id in value.split(";")
            if case_id
        }
    _public_summary(globals(), "Public GBM source and annotation resolution")

# %% [markdown]
##### GBM UMI matrix acquisition and barcode matching

# %%
@_nb9_registry.register("s50_0")
def _nb9_stage_s50_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import gzip
    import hashlib
    import json
    import shutil
    import tarfile
    import urllib.request
    import pandas as pd

    PROJECT = Path(str(PROJECT_ROOT))
    BASE = PROJECT / "data_processed/MTAP_RNA_prediction/16_scRNA_transfer"
    SEARCH = BASE / "03_GDC_original_counts_search"
    PATIENT_FILE = (
        BASE / "01_source_resolution/patient_DNA_and_cell_coverage.tsv"
    )
    TUMOR_FILE = BASE / "01_source_resolution/Tumor_nucleus_metadata.tsv.gz"
    GDC_FILE = SEARCH / "all_patient_GDC_files.tsv"
    DOWNLOAD = PROJECT / "data_raw/GBM/NIHMS1665743/snRNA_UMI_MEX"
    OUT = BASE / "04_UMI_download_and_barcode_matching"
    DOWNLOAD.mkdir(parents=True, exist_ok=True)
    OUT.mkdir(parents=True, exist_ok=True)
    for path in [PATIENT_FILE, TUMOR_FILE, GDC_FILE]:
        if not path.is_file():
            raise FileNotFoundError(path)
    patients = pd.read_csv(PATIENT_FILE, sep="\t", dtype={"patient_id": str})
    tumor = pd.read_csv(
        TUMOR_FILE, sep="\t", dtype={"patient_id": str, "cell_barcode": str}
    )
    files = pd.read_csv(GDC_FILE, sep="\t", dtype=str, keep_default_na=False)
    if "cell_barcode" not in tumor.columns:
        raise ValueError(
            "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
        )
    if patients["patient_id"].duplicated().any():
        raise ValueError(
            "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
        )
    expected_patients = set(patients["patient_id"])
    if set(tumor["patient_id"]) != expected_patients:
        raise ValueError(
            "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
        )
    if tumor.duplicated(["patient_id", "cell_barcode"]).any():
        raise ValueError(
            "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
        )
    mask = (
        files["experimental_strategy"].eq("scRNA-Seq")
        & files["data_type"].eq("Gene Expression Quantification")
        & files["data_format"].eq("MEX")
        & files["access"].eq("open")
        & files["file_name"].str.endswith(
            ".qc_filtered_feature_bc_matrix.tar.gz"
        )
    )
    selected = files.loc[mask].copy()

    def resolve_patient(value):
        ids = {x.strip() for x in str(value).split(";") if x.strip()}
        if len(ids) != 1 or not ids.issubset(expected_patients):
            raise ValueError(
                "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
            )
        return next(iter(ids))

    selected["patient_id"] = selected["patient_ids"].map(resolve_patient)
    selected.to_csv(
        OUT / "selected_QC_filtered_MEX_files.tsv", sep="\t", index=False
    )
    coverage = (
        selected.groupby("patient_id")
        .size()
        .reindex(sorted(expected_patients), fill_value=0)
    )
    if not coverage.eq(1).all():
        raise ValueError(
            "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
        )
    if selected["file_id"].duplicated().any():
        raise ValueError(
            "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
        )
    if not selected["md5sum"].str.fullmatch("[0-9a-fA-F]{32}").all():
        raise ValueError(
            "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
        )
    total_mb = pd.to_numeric(selected["file_size_MB"], errors="raise").sum()

    def md5_file(path):
        h = hashlib.md5()
        with open(path, "rb") as handle:
            for block in iter(lambda: handle.read(8 * 1024 * 1024), b""):
                h.update(block)
        return h.hexdigest()

    def download_checked(file_id, destination, expected_md5):
        expected_md5 = expected_md5.lower()
        if destination.is_file():
            if md5_file(destination) == expected_md5:
                return
            raise ValueError(
                "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
            )
        partial = destination.with_name(destination.name + ".part")
        url = f"https://api.gdc.cancer.gov/data/{file_id}"
        last_error = None
        for attempt in range(1, 4):
            try:
                request = urllib.request.Request(
                    url, headers={"User-Agent": "MTAP-research"}
                )
                with urllib.request.urlopen(
                    request, timeout=60
                ) as response, open(partial, "wb") as handle:
                    shutil.copyfileobj(
                        response, handle, length=8 * 1024 * 1024
                    )
                actual_md5 = md5_file(partial)
                if actual_md5 != expected_md5:
                    raise ValueError(
                        "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
                    )
                partial.replace(destination)
                return
            except Exception as exc:
                last_error = exc
        raise RuntimeError(
            "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
        ) from last_error

    def extract_mex(archive, directory):
        directory.mkdir(parents=True, exist_ok=True)
        accepted = {
            "matrix": {"matrix.mtx", "matrix.mtx.gz"},
            "features": {
                "features.tsv",
                "features.tsv.gz",
                "genes.tsv",
                "genes.tsv.gz",
            },
            "barcodes": {"barcodes.tsv", "barcodes.tsv.gz"},
        }
        outputs = {}
        with tarfile.open(archive, "r:gz") as tf:
            members = [m for m in tf.getmembers() if m.isfile()]
            for role, names in accepted.items():
                matches = [m for m in members if Path(m.name).name in names]
                if len(matches) != 1:
                    raise ValueError(
                        "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
                    )
                member = matches[0]
                target = directory / Path(member.name).name
                partial = target.with_name(target.name + ".part")
                source = tf.extractfile(member)
                if source is None:
                    raise ValueError(
                        "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
                    )
                with source, open(partial, "wb") as handle:
                    shutil.copyfileobj(source, handle, length=8 * 1024 * 1024)
                partial.replace(target)
                outputs[role] = target
        return outputs

    def open_text(path):
        if path.name.endswith(".gz"):
            return gzip.open(path, "rt", encoding="utf-8")
        return open(path, "r", encoding="utf-8")

    def read_mtx_dimensions(path):
        with open_text(path) as handle:
            header = handle.readline().strip()
            if not header.lower().startswith(
                "%%matrixmarket matrix coordinate"
            ):
                raise ValueError(
                    "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
                )
            for line in handle:
                line = line.strip()
                if line and (not line.startswith("%")):
                    values = line.split()
                    if len(values) != 3:
                        raise ValueError(
                            "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
                        )
                    return (header, tuple(map(int, values)))
        raise ValueError(
            "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
        )

    audit_rows = []
    for row in selected.sort_values("patient_id").itertuples(index=False):
        patient = row.patient_id
        patient_dir = DOWNLOAD / patient
        patient_dir.mkdir(parents=True, exist_ok=True)
        archive = patient_dir / Path(row.file_name).name
        download_checked(row.file_id, archive, row.md5sum)
        extracted = extract_mex(archive, patient_dir / "matrix")
        header, (n_features, n_barcodes, nnz) = read_mtx_dimensions(
            extracted["matrix"]
        )
        with open_text(extracted["barcodes"]) as handle:
            barcodes = [line.rstrip("\r\n").split("\t")[0] for line in handle]
        with open_text(extracted["features"]) as handle:
            feature_count = sum((1 for _ in handle))
        if len(barcodes) != n_barcodes:
            raise ValueError(
                "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
            )
        if feature_count != n_features:
            raise ValueError(
                "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
            )
        if len(set(barcodes)) != len(barcodes):
            raise ValueError(
                "GBM UMI matrix acquisition and barcode matching: integrity check failed; condition: input or artifact integrity check."
            )
        existing = tumor.loc[tumor["patient_id"].eq(patient), "cell_barcode"]
        matched = existing.isin(set(barcodes))
        missing = existing.loc[~matched]
        if len(missing):
            missing.to_frame().to_csv(
                OUT / f"{patient}_unmatched_Tumor_barcodes.tsv",
                sep="\t",
                index=False,
            )
        audit_rows.append(
            {
                "patient_id": patient,
                "GDC_file_id": row.file_id,
                "matrix_file": str(extracted["matrix"]),
                "features_file": str(extracted["features"]),
                "barcodes_file": str(extracted["barcodes"]),
                "matrix_header": header,
                "n_features": n_features,
                "n_barcodes": n_barcodes,
                "n_stored_entries": nnz,
                "n_existing_Tumor_nuclei": len(existing),
                "n_matched_Tumor_nuclei": int(matched.sum()),
                "n_unmatched_Tumor_nuclei": len(missing),
                "archive_MD5_verified": True,
            }
        )
        pd.DataFrame(audit_rows).to_csv(
            OUT / "UMI_MEX_download_and_matching.tsv", sep="\t", index=False
        )
    audit = pd.DataFrame(audit_rows)
    if audit["n_unmatched_Tumor_nuclei"].sum() > 0:
        pass
    _public_summary(
        globals(), "GBM UMI matrix acquisition and barcode matching"
    )

# %% [markdown]
##### GBM raw UMI source verification

# %%
@_nb9_registry.register("s51_0")
def _nb9_stage_s51_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import shutil
    import h5py
    import numpy as np
    import pandas as pd

    PROJECT = Path(str(PROJECT_ROOT))
    H5AD = (
        PROJECT
        / "data_processed/CPTAC_GBM_joint_analysis"
        / "CPTAC_GBM_16patients_SCT_merged.h5ad"
    )
    TUMOR_FILE = (
        PROJECT
        / "data_processed/MTAP_RNA_prediction"
        / "16_scRNA_transfer/01_source_resolution"
        / "Tumor_nucleus_metadata.tsv.gz"
    )

    def decode(x):
        return x.decode("utf-8") if isinstance(x, bytes) else x

    def read_vector(node):
        if isinstance(node, h5py.Dataset):
            values = node[:]
            if values.dtype.kind in {"O", "S", "U"}:
                return np.array([decode(x) for x in values], dtype=object)
            return values
        if "codes" in node and "categories" in node:
            codes = node["codes"][:]
            categories = read_vector(node["categories"])
            values = np.empty(len(codes), dtype=object)
            values[:] = pd.NA
            valid = codes >= 0
            values[valid] = categories[codes[valid]]
            return values
        raise ValueError(
            "GBM raw UMI source verification: integrity check failed; condition: input or artifact integrity check."
        )

    tumor = pd.read_csv(
        TUMOR_FILE, sep="\t", dtype={"cell_id": str, "patient_id": str}
    )
    if not {"cell_id", "patient_id"}.issubset(tumor.columns):
        raise ValueError(
            "GBM raw UMI source verification: integrity check failed; condition: input or artifact integrity check."
        )
    with h5py.File(H5AD, "r") as f:
        obs = f["obs"]
        index_name = decode(obs.attrs["_index"])
        reference = pd.DataFrame(
            {
                "cell_id": read_vector(obs[index_name]),
                "patient_id": read_vector(obs["patient_id"]),
                "cell_barcode": read_vector(obs["cell_barcode"]),
            }
        )
    if reference.isna().any().any():
        raise ValueError(
            "GBM raw UMI source verification: integrity check failed; condition: input or artifact integrity check."
        )
    if reference["cell_id"].duplicated().any():
        raise ValueError(
            "GBM raw UMI source verification: integrity check failed; condition: input or artifact integrity check."
        )
    if tumor["cell_id"].isna().any() or tumor["cell_id"].duplicated().any():
        raise ValueError(
            "GBM raw UMI source verification: integrity check failed; condition: input or artifact integrity check."
        )
    reference = reference.set_index("cell_id")
    if not tumor["cell_id"].isin(reference.index).all():
        raise ValueError(
            "GBM raw UMI source verification: integrity check failed; condition: input or artifact integrity check."
        )
    matched = reference.loc[tumor["cell_id"]]
    if not np.array_equal(
        tumor["patient_id"].astype(str).to_numpy(),
        matched["patient_id"].astype(str).to_numpy(),
    ):
        raise ValueError(
            "GBM raw UMI source verification: integrity check failed; condition: input or artifact integrity check."
        )
    barcodes = matched["cell_barcode"].astype(str).to_numpy()
    if "cell_barcode" in tumor.columns:
        if not np.array_equal(
            tumor["cell_barcode"].astype(str).to_numpy(), barcodes
        ):
            raise ValueError(
                "GBM raw UMI source verification: integrity check failed; condition: input or artifact integrity check."
            )
    else:
        tumor["cell_barcode"] = barcodes
    if tumor.duplicated(["patient_id", "cell_barcode"]).any():
        raise ValueError(
            "GBM raw UMI source verification: integrity check failed; condition: input or artifact integrity check."
        )
    backup = TUMOR_FILE.with_name(
        "Tumor_nucleus_metadata.before_barcode_fix.tsv.gz"
    )
    if not backup.exists():
        shutil.copy2(TUMOR_FILE, backup)
    temporary = TUMOR_FILE.with_name("Tumor_nucleus_metadata.repaired.tmp.gz")
    tumor.to_csv(temporary, sep="\t", index=False, compression="gzip")
    temporary.replace(TUMOR_FILE)
    _public_summary(globals(), "GBM raw UMI source verification")

