    N_ADAPTER_REGIONS = 4
    N_ADAPTER_PARAMETERS = 8
    DL_MTAP_TARGET_INDEX = 26
    DL_DEEP_DELETION_CLASS_INDEX = 0
    DL_FROZEN_SEEDS = 3
    MODELS = ["Region_adapter_DL_LOPO", "L2_LOPO", "ElasticNet_LOPO"]
