@_nb9_registry.register("s62_105")
def _nb9_stage_s62_105():
    performance_rows = []
    for model in MODELS:
        for metric_index, metric in enumerate(METRICS):
            lower, upper = percentile_ci(
                bootstrap_results[model][:, metric_index]
            )
            performance_rows.append(
                {
                    "model": model,
                    "display_label": LABELS[model].replace("\n", " "),
                    "metric": metric,
                    "estimate": point_estimates[model][metric],
                    "CI95_low": lower,
                    "CI95_high": upper,
                    "n_patients": len(y),
                    "n_positive": int(y.sum()),
                    "n_negative": int((y == 0).sum()),
                    "descriptive_threshold": THRESHOLD,
                    "bootstrap_retraining": False,
                }
            )
    performance = pd.DataFrame(performance_rows)
    performance.to_csv(
        OUT / "snRNA_adapter_L2_ElasticNet_performance_CI.tsv",
        sep="\t",
        index=False,
    )
    confusion_rows = []
    for model in MODELS:
        result = point_estimates[model]
        confusion_rows.append(
            {
                "model": model,
                "display_label": LABELS[model].replace("\n", " "),
                "threshold": THRESHOLD,
                "TP": result["TP"],
                "FP": result["FP"],
                "FN": result["FN"],
                "TN": result["TN"],
            }
        )
    confusion_table = pd.DataFrame(confusion_rows)
    confusion_table.to_csv(
        OUT / "snRNA_adapter_L2_ElasticNet_confusion_matrix.tsv",
        sep="\t",
        index=False,
    )
    formatted = performance.copy()
    formatted["value"] = formatted.apply(
        lambda row: (
            f"{row['estimate']:.3f} ({row['CI95_low']:.3f}–{row['CI95_high']:.3f})"
            if np.isfinite(row["estimate"])
            else "Undefined"
        ),
        axis=1,
    )
    summary = formatted.pivot(index="model", columns="metric", values="value")
    summary = summary.reindex(index=MODELS, columns=METRICS)
    summary.to_csv(
        OUT / "snRNA_adapter_L2_ElasticNet_performance_summary.tsv", sep="\t"
    )
    FIGURE_METRICS = ["AUROC", "AP", "Balanced_accuracy"]
    FIGURE_TITLES = {
        "AUROC": "AUROC",
        "AP": "Average precision",
        "Balanced_accuracy": "Balanced accuracy",
    }

