@_nb9_registry.register("s64_0")
def _nb9_stage_s64_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    from itertools import combinations
    import json
    import numpy as np
    import pandas as pd
    import matplotlib as mpl
    import matplotlib.pyplot as plt
    from sklearn.metrics import (
        roc_auc_score,
        average_precision_score,
        roc_curve,
        precision_recall_curve,
    )

    PROJECT = Path(str(PROJECT_ROOT))
    COMPARISON_DIR = (
        PROJECT
        / "data_processed"
        / "MTAP_RNA_prediction"
        / "15_region_multitask_DL"
        / "08_TPM_retraining"
        / "06_three_gene_L2_comparison"
    )
    TCGA_PATH = COMPARISON_DIR / "three_model_development_OOF.tsv"
    CPTAC_PATH = COMPARISON_DIR / "CPTAC_three_model_patient_predictions.tsv"
    OUT = COMPARISON_DIR / "TCGA_CPTAC_three_model_performance_figure"
    OUT.mkdir(parents=True, exist_ok=True)
    SEED = 20261018
    THRESHOLD = 0.5
    N_BOOTSTRAP = 1000
    MODEL_ORDER = ["Bulk_DL", "Three_gene_L2", "Elastic_Net"]
    PROBABILITY_COLUMNS = {
        "Bulk_DL": "prob_DL",
        "Three_gene_L2": "prob_L2",
        "Elastic_Net": "prob_ElasticNet",
    }
    MODEL_LABELS = {
        "Bulk_DL": "Bulk DL",
        "Three_gene_L2": "Three-gene L2",
        "Elastic_Net": "Elastic Net",
    }
    MODEL_COLORS = {
        "Bulk_DL": "#A5678E",
        "Three_gene_L2": "#33539E",
        "Elastic_Net": "#7FACD6",
    }
    COHORT_ORDER = ["TCGA_OOF", "CPTAC_external"]
    COHORT_LABELS = {
        "TCGA_OOF": "TCGA development cohort (OOF)",
        "CPTAC_external": "CPTAC external test cohort",
    }
    METRICS = [
        "AUROC",
        "AP",
        "Balanced_accuracy",
        "Sensitivity",
        "Specificity",
        "Accuracy",
        "Precision",
        "F1",
        "Brier",
    ]
    FIGURE_METRICS = ["AUROC", "AP", "Balanced_accuracy"]
    FIGURE_METRIC_LABELS = {
        "AUROC": "AUROC",
        "AP": "Average precision",
        "Balanced_accuracy": "Balanced accuracy",
    }
    mpl.rcParams.update(
        {
            "font.family": "DejaVu Sans",
            "font.size": 9,
            "axes.titlesize": 10,
            "axes.labelsize": 9,
            "legend.fontsize": 8,
            "axes.spines.top": False,
            "axes.spines.right": False,
            "pdf.fonttype": 42,
            "ps.fonttype": 42,
            "savefig.dpi": 400,
        }
    )
    for path in [TCGA_PATH, CPTAC_PATH]:
        if not path.is_file():
            raise FileNotFoundError(
                "TCGA OOF and CPTAC final three-model performance: integrity check failed; condition: input or artifact integrity check."
            )
    tcga = pd.read_csv(TCGA_PATH, sep="\t", dtype={"patient_id": str})
    cptac = pd.read_csv(CPTAC_PATH, sep="\t", dtype={"patient_id": str})
    cohort_frames = {"TCGA_OOF": tcga, "CPTAC_external": cptac}
    REQUIRED_COLUMNS = {
        "patient_id",
        "label_MTAP_deep",
        "prob_DL",
        "prob_L2",
        "prob_ElasticNet",
    }
    audit_rows = []
    for cohort_name, frame in cohort_frames.items():
        missing_columns = REQUIRED_COLUMNS - set(frame.columns)
        if missing_columns:
            raise ValueError(
                "TCGA OOF and CPTAC final three-model performance: integrity check failed; condition: input or artifact integrity check."
            )
        frame["patient_id"] = frame["patient_id"].astype(str).str.strip()
        if frame["patient_id"].isna().any():
            raise ValueError(
                "TCGA OOF and CPTAC final three-model performance: integrity check failed; condition: input or artifact integrity check."
            )
        if frame["patient_id"].duplicated().any():
            duplicated = frame.loc[
                frame["patient_id"].duplicated(keep=False), "patient_id"
            ].tolist()
            raise ValueError(
                "TCGA OOF and CPTAC final three-model performance: integrity check failed; condition: input or artifact integrity check."
            )
        frame["label_MTAP_deep"] = pd.to_numeric(
            frame["label_MTAP_deep"], errors="raise"
        )
        if not frame["label_MTAP_deep"].isin([0, 1]).all():
            invalid_labels = sorted(
                frame.loc[
                    ~frame["label_MTAP_deep"].isin([0, 1]), "label_MTAP_deep"
                ].unique()
            )
            raise ValueError(
                "TCGA OOF and CPTAC final three-model performance: integrity check failed; condition: input or artifact integrity check."
            )
        for model_name, probability_column in PROBABILITY_COLUMNS.items():
            frame[probability_column] = pd.to_numeric(
                frame[probability_column], errors="raise"
            )
            probabilities = frame[probability_column].to_numpy(dtype=float)
            if not np.isfinite(probabilities).all():
                raise ValueError(
                    "TCGA OOF and CPTAC final three-model performance: integrity check failed; condition: input or artifact integrity check."
                )
            if not ((probabilities >= 0) & (probabilities <= 1)).all():
                raise ValueError(
                    "TCGA OOF and CPTAC final three-model performance: integrity check failed; condition: input or artifact integrity check."
                )
        y = frame["label_MTAP_deep"].astype(int).to_numpy()
        if len(np.unique(y)) != 2:
            raise ValueError(
                "TCGA OOF and CPTAC final three-model performance: integrity check failed; condition: input or artifact integrity check."
            )
        audit_rows.append(
            {
                "cohort": cohort_name,
                "cohort_label": COHORT_LABELS[cohort_name],
                "n_patients": len(frame),
                "n_positive": int(y.sum()),
                "n_negative": int((y == 0).sum()),
                "positive_fraction": float(y.mean()),
                "prediction_type": (
                    "Patient-level out-of-fold predictions"
                    if cohort_name == "TCGA_OOF"
                    else "Frozen-model external predictions"
                ),
                "n_cancers": (
                    int(frame["acronym"].nunique())
                    if "acronym" in frame.columns
                    else np.nan
                ),
            }
        )
    audit = pd.DataFrame(audit_rows)
    audit.to_csv(OUT / "cohort_audit.tsv", sep="\t", index=False)

    def safe_ratio(numerator, denominator):
        """Return a missing value when a performance denominator is zero."""
        if denominator == 0:
            return np.nan
        return numerator / denominator

    def evaluate_model(y_true, probabilities, threshold=0.5):
        """Calculate patient-level metrics using the prespecified threshold."""
        predicted_positive = probabilities >= threshold
        tp = int(((y_true == 1) & predicted_positive).sum())
        fp = int(((y_true == 0) & predicted_positive).sum())
        fn = int(((y_true == 1) & ~predicted_positive).sum())
        tn = int(((y_true == 0) & ~predicted_positive).sum())
        sensitivity = safe_ratio(tp, tp + fn)
        specificity = safe_ratio(tn, tn + fp)
        return {
            "AUROC": roc_auc_score(y_true, probabilities),
            "AP": average_precision_score(y_true, probabilities),
            "Balanced_accuracy": (sensitivity + specificity) / 2,
            "Sensitivity": sensitivity,
            "Specificity": specificity,
            "Accuracy": safe_ratio(tp + tn, len(y_true)),
            "Precision": safe_ratio(tp, tp + fp),
            "F1": safe_ratio(2 * tp, 2 * tp + fp + fn),
            "Brier": float(np.mean((probabilities - y_true) ** 2)),
            "TP": tp,
            "FP": fp,
            "FN": fn,
            "TN": tn,
        }

    def percentile_ci(values):
        """Calculate a percentile bootstrap confidence interval."""
        values = np.asarray(values, dtype=float)
        values = values[np.isfinite(values)]
        if len(values) == 0:
            return (np.nan, np.nan)
        lower, upper = np.quantile(values, [0.025, 0.975])
        return (float(lower), float(upper))

    point_estimates = {}
    bootstrap_estimates = {}
    bootstrap_indices = {}
    for cohort_index, cohort_name in enumerate(COHORT_ORDER):
        frame = cohort_frames[cohort_name]
        y = frame["label_MTAP_deep"].astype(int).to_numpy()
        positive_indices = np.flatnonzero(y == 1)
        negative_indices = np.flatnonzero(y == 0)
        rng = np.random.default_rng(SEED + cohort_index)
        sampled_indices_list = []
        for bootstrap_index in range(N_BOOTSTRAP):
            sampled_positive = rng.choice(
                positive_indices, size=len(positive_indices), replace=True
            )
            sampled_negative = rng.choice(
                negative_indices, size=len(negative_indices), replace=True
            )
            sampled_indices = np.concatenate(
                [sampled_positive, sampled_negative]
            )
            sampled_indices = rng.permutation(sampled_indices)
            sampled_indices_list.append(sampled_indices)
        bootstrap_indices[cohort_name] = sampled_indices_list
        for model_name in MODEL_ORDER:
            probability_column = PROBABILITY_COLUMNS[model_name]
            probabilities = frame[probability_column].to_numpy(dtype=float)
            point_estimates[cohort_name, model_name] = evaluate_model(
                y, probabilities, threshold=THRESHOLD
            )
            model_bootstrap = np.full((N_BOOTSTRAP, len(METRICS)), np.nan)
            for bootstrap_index, sampled_indices in enumerate(
                sampled_indices_list
            ):
                bootstrap_result = evaluate_model(
                    y[sampled_indices],
                    probabilities[sampled_indices],
                    threshold=THRESHOLD,
                )
                model_bootstrap[bootstrap_index] = [
                    bootstrap_result[metric] for metric in METRICS
                ]
            bootstrap_estimates[cohort_name, model_name] = model_bootstrap
    performance_rows = []
    for cohort_name in COHORT_ORDER:
        frame = cohort_frames[cohort_name]
        y = frame["label_MTAP_deep"].astype(int).to_numpy()
        for model_name in MODEL_ORDER:
            point_result = point_estimates[cohort_name, model_name]
            model_bootstrap = bootstrap_estimates[cohort_name, model_name]
            for metric_index, metric in enumerate(METRICS):
                lower, upper = percentile_ci(model_bootstrap[:, metric_index])
                performance_rows.append(
                    {
                        "cohort": cohort_name,
                        "cohort_label": COHORT_LABELS[cohort_name],
                        "model": model_name,
                        "model_label": MODEL_LABELS[model_name],
                        "metric": metric,
                        "estimate": point_result[metric],
                        "CI95_low": lower,
                        "CI95_high": upper,
                        "n_patients": len(y),
                        "n_positive": int(y.sum()),
                        "n_negative": int((y == 0).sum()),
                        "threshold": THRESHOLD,
                        "bootstrap_retraining": False,
                        "prediction_source": (
                            "OOF"
                            if cohort_name == "TCGA_OOF"
                            else "Frozen external"
                        ),
                    }
                )
    performance = pd.DataFrame(performance_rows)
    performance.to_csv(OUT / "performance_with_CI.tsv", sep="\t", index=False)
    formatted = performance.copy()
    formatted["estimate_CI95"] = formatted.apply(
        lambda row: f"{row['estimate']:.3f} ({row['CI95_low']:.3f}–{row['CI95_high']:.3f})",
        axis=1,
    )
    summary = formatted.pivot_table(
        index=["cohort", "model"],
        columns="metric",
        values="estimate_CI95",
        aggfunc="first",
    )
    summary = summary.reindex(
        pd.MultiIndex.from_product(
            [COHORT_ORDER, MODEL_ORDER], names=["cohort", "model"]
        )
    )
    summary.to_csv(OUT / "performance_summary.tsv", sep="\t")
    confusion_rows = []
    for cohort_name in COHORT_ORDER:
        frame = cohort_frames[cohort_name]
        y = frame["label_MTAP_deep"].astype(int).to_numpy()
        for model_name in MODEL_ORDER:
            result = point_estimates[cohort_name, model_name]
            confusion_rows.append(
                {
                    "cohort": cohort_name,
                    "model": model_name,
                    "model_label": MODEL_LABELS[model_name],
                    "threshold": THRESHOLD,
                    "n_patients": len(y),
                    "n_positive": int(y.sum()),
                    "TP": result["TP"],
                    "FP": result["FP"],
                    "FN": result["FN"],
                    "TN": result["TN"],
                }
            )
    confusion_table = pd.DataFrame(confusion_rows)
    confusion_table.to_csv(
        OUT / "confusion_matrix_at_0.5.tsv", sep="\t", index=False
    )
    PAIRWISE_METRICS = ["AUROC", "AP", "Balanced_accuracy", "Brier"]
    pairwise_rows = []
    model_pairs = [
        ("Bulk_DL", "Three_gene_L2"),
        ("Bulk_DL", "Elastic_Net"),
        ("Three_gene_L2", "Elastic_Net"),
    ]
    for cohort_name in COHORT_ORDER:
        for model_a, model_b in model_pairs:
            point_a = point_estimates[cohort_name, model_a]
            point_b = point_estimates[cohort_name, model_b]
            bootstrap_a = bootstrap_estimates[cohort_name, model_a]
            bootstrap_b = bootstrap_estimates[cohort_name, model_b]
            for metric in PAIRWISE_METRICS:
                metric_index = METRICS.index(metric)
                point_difference = point_a[metric] - point_b[metric]
                bootstrap_difference = (
                    bootstrap_a[:, metric_index] - bootstrap_b[:, metric_index]
                )
                lower, upper = percentile_ci(bootstrap_difference)
                if metric == "Brier":
                    favorable_interpretation = f"Negative difference favors {MODEL_LABELS[model_a]}; positive difference favors {MODEL_LABELS[model_b]}"
                else:
                    favorable_interpretation = f"Positive difference favors {MODEL_LABELS[model_a]}; negative difference favors {MODEL_LABELS[model_b]}"
                pairwise_rows.append(
                    {
                        "cohort": cohort_name,
                        "model_A": model_a,
                        "model_B": model_b,
                        "metric": metric,
                        "difference_A_minus_B": point_difference,
                        "CI95_low": lower,
                        "CI95_high": upper,
                        "CI_excludes_zero": bool(lower > 0 or upper < 0),
                        "interpretation": favorable_interpretation,
                        "interval_scope": "Patient-level stratified paired percentile bootstrap",
                    }
                )
    pairwise_comparison = pd.DataFrame(pairwise_rows)
    pairwise_comparison.to_csv(
        OUT / "paired_model_differences.tsv", sep="\t", index=False
    )
    GENERALIZATION_METRICS = ["AUROC", "AP", "Balanced_accuracy", "Brier"]
    generalization_rows = []
    for model_name in MODEL_ORDER:
        for metric in GENERALIZATION_METRICS:
            metric_index = METRICS.index(metric)
            tcga_point = point_estimates["TCGA_OOF", model_name][metric]
            cptac_point = point_estimates["CPTAC_external", model_name][metric]
            point_difference = cptac_point - tcga_point
            difference_distribution = (
                bootstrap_estimates["CPTAC_external", model_name][
                    :, metric_index
                ]
                - bootstrap_estimates["TCGA_OOF", model_name][:, metric_index]
            )
            lower, upper = percentile_ci(difference_distribution)
            generalization_rows.append(
                {
                    "model": model_name,
                    "model_label": MODEL_LABELS[model_name],
                    "metric": metric,
                    "TCGA_OOF_estimate": tcga_point,
                    "CPTAC_external_estimate": cptac_point,
                    "difference_CPTAC_minus_TCGA": point_difference,
                    "CI95_low": lower,
                    "CI95_high": upper,
                    "CI_excludes_zero": bool(lower > 0 or upper < 0),
                    "interval_scope": "Independent-cohort stratified bootstrap",
                }
            )
    generalization = pd.DataFrame(generalization_rows)
    generalization.to_csv(
        OUT / "generalization_gap_CPTAC_minus_TCGA.tsv", sep="\t", index=False
    )

# %% [markdown]
##### TCGA holdout bootstrap intervals and model comparisons

# %%
@_nb9_registry.register("s72_129")
def _nb9_stage_s72_129():
    MODEL_ORDER = ["Bulk_DL", "Three_gene_L2", "Elastic_Net"]
    COLORS = {
        "Three_gene_L2": "#33539E",
        "Elastic_Net": "#7FACD6",
        "Bulk_DL": "#A5678E",
    }

    def metrics(labels, probability):
        predicted = probability >= THRESHOLD
        tn, fp, fn, tp = confusion_matrix(
            labels, predicted, labels=[0, 1]
        ).ravel()
        sensitivity = tp / (tp + fn)
        specificity = tn / (tn + fp)
        return {
            "AUROC": roc_auc_score(labels, probability),
            "AP": average_precision_score(labels, probability),
            "Brier": brier_score_loss(labels, probability),
            "Sensitivity": sensitivity,
            "Specificity": specificity,
            "Balanced_accuracy": (sensitivity + specificity) / 2,
            "PPV": tp / (tp + fp) if tp + fp else np.nan,
            "Accuracy": (tp + tn) / len(labels),
        }

    point = {name: metrics(y, probabilities[name]) for name in MODEL_ORDER}
    metric_names = list(point[MODEL_ORDER[0]])
    bootstrap = {
        name: np.empty((N_BOOTSTRAP, len(metric_names)))
        for name in MODEL_ORDER
    }
    positive_indices = np.flatnonzero(y == 1)
    negative_indices = np.flatnonzero(y == 0)
    rng = np.random.default_rng(SEED)
    for b in range(N_BOOTSTRAP):
        indices = np.concatenate(
            [
                rng.choice(
                    positive_indices, len(positive_indices), replace=True
                ),
                rng.choice(
                    negative_indices, len(negative_indices), replace=True
                ),
            ]
        )
        for name in MODEL_ORDER:
            result = metrics(y[indices], probabilities[name][indices])
            bootstrap[name][b] = [result[m] for m in metric_names]
        if (b + 1) % 250 == 0:
            pass
    records = []
    for name in MODEL_ORDER:
        for j, metric in enumerate(metric_names):
            lower, upper = np.nanpercentile(bootstrap[name][:, j], [2.5, 97.5])
            records.append(
                {
                    "cohort": "TCGA_original_holdout_TPM_matched",
                    "model": name,
                    "metric": metric,
                    "estimate": point[name][metric],
                    "CI95_low": lower,
                    "CI95_high": upper,
                    "n_patients": len(y),
                    "n_positive": int(y.sum()),
                    "classification_threshold": THRESHOLD,
                    "bootstrap_retraining": False,
                }
            )
    performance = pd.DataFrame(records)
    performance.to_csv(
        OUT / "06_performance_with_CI.tsv", sep="\t", index=False
    )
    confusion_records = []
    for name in MODEL_ORDER:
        tn, fp, fn, tp = confusion_matrix(
            y, probabilities[name] >= THRESHOLD, labels=[0, 1]
        ).ravel()
        confusion_records.append(
            {
                "model": name,
                "threshold": THRESHOLD,
                "TP": tp,
                "FP": fp,
                "FN": fn,
                "TN": tn,
            }
        )
    pd.DataFrame(confusion_records).to_csv(
        OUT / "07_confusion_counts.tsv", sep="\t", index=False
    )
    difference_records = []
    for comparator in ["Elastic_Net", "Bulk_DL"]:
        for j, metric in enumerate(metric_names):
            differences = (
                bootstrap["Three_gene_L2"][:, j] - bootstrap[comparator][:, j]
            )
            lower, upper = np.nanpercentile(differences, [2.5, 97.5])
            difference_records.append(
                {
                    "comparison": f"Three_gene_L2_minus_{comparator}",
                    "metric": metric,
                    "difference": point["Three_gene_L2"][metric]
                    - point[comparator][metric],
                    "CI95_low": lower,
                    "CI95_high": upper,
                }
            )
    pd.DataFrame(difference_records).to_csv(
        OUT / "08_paired_model_differences.tsv", sep="\t", index=False
    )
    cancer_records = []
    for cancer, group in predictions.groupby("acronym"):
        labels = group["label_MTAP_deep"].to_numpy(dtype=int)
        if len(np.unique(labels)) < 2:
            cancer_records.append(
                {
                    "acronym": cancer,
                    "model": "Not_evaluable_for_AUROC",
                    "n_patients": len(labels),
                    "n_positive": int(labels.sum()),
                }
            )
            continue
        for name in MODEL_ORDER:
            cancer_records.append(
                {
                    "acronym": cancer,
                    "model": name,
                    "n_patients": len(labels),
                    "n_positive": int(labels.sum()),
                    **metrics(labels, group[f"prob_{name}"].to_numpy()),
                }
            )
    pd.DataFrame(cancer_records).to_csv(
        OUT / "09_per_cancer_descriptive_performance.tsv",
        sep="\t",
        index=False,
    )

