    if not pred["OGM_deep_deletion_label"].isin([0, 1]).all():
        raise RuntimeError(
            "GSE327167 three-model comparison at threshold 0.75: integrity check failed; condition: input or artifact integrity check."
        )
    for model in MODELS:
        if (
            not np.isfinite(pred[model]).all()
            or not pred[model].between(0, 1).all()
        ):
            raise RuntimeError(
                "GSE327167 three-model comparison at threshold 0.75: integrity check failed; condition: input or artifact integrity check."
            )
    evaluation_sets = {
        "Whole_31": pred.loc[pred["input_scope"].eq("Whole")].copy(),
        "Malignant_any_author_tumor": pred.loc[
            pred["input_scope"].eq("Malignant") & pred["n_cells"].gt(0)
        ].copy(),
        "Malignant_ge50_primary": pred.loc[
            pred["input_scope"].eq("Malignant") & pred["n_cells"].ge(50)
        ].copy(),
    }
    for scope, frame in evaluation_sets.items():
        if not frame["patient_id"].is_unique:
            raise RuntimeError(
                "GSE327167 three-model comparison at threshold 0.75: integrity check failed; condition: input or artifact integrity check."
            )
        if frame["OGM_deep_deletion_label"].nunique() != 2:
            raise RuntimeError(
                "GSE327167 three-model comparison at threshold 0.75: integrity check failed; condition: input or artifact integrity check."
            )
        evaluation_sets[scope] = frame.sort_values("patient_id").reset_index(
            drop=True
        )
    previous_ci = None
    if PREVIOUS_CI_FILE.is_file():
        previous_ci = pd.read_csv(PREVIOUS_CI_FILE, sep="\t")

    def divide(a, b):
        a, b = np.broadcast_arrays(
            np.asarray(a, dtype=float), np.asarray(b, dtype=float)
        )
        result = np.full(a.shape, np.nan, dtype=float)
        np.divide(a, b, out=result, where=b != 0)
        return result

    def threshold_metrics(y, p):
        """Evaluate one cohort or batched bootstrap arrays along the patient axis."""
        call = p >= THRESHOLD
        positive = y == 1
        negative = y == 0
        tp = np.sum(call & positive, axis=-1)
        fp = np.sum(call & negative, axis=-1)
        fn = np.sum(~call & positive, axis=-1)
        tn = np.sum(~call & negative, axis=-1)
        sensitivity = divide(tp, tp + fn)
        specificity = divide(tn, tn + fp)
        return {
            "Balanced_accuracy": (sensitivity + specificity) / 2,
            "Sensitivity": sensitivity,
            "Specificity": specificity,
            "PPV": divide(tp, tp + fp),
            "NPV": divide(tn, tn + fn),
            "TP": tp,
            "FP": fp,
            "FN": fn,
            "TN": tn,
        }

    def percentile_ci(values):
        values = np.asarray(values, dtype=float)
        values = values[np.isfinite(values)]
        if len(values) == 0:
            return (np.nan, np.nan)
        return tuple(np.percentile(values, [2.5, 97.5]))

    rows = []
    patient_call_tables = []
    for scope_index, scope in enumerate(SCOPES):
        frame = evaluation_sets[scope]
        y = frame["OGM_deep_deletion_label"].to_numpy(dtype=int)
        positive_index = np.flatnonzero(y == 1)
        negative_index = np.flatnonzero(y == 0)
        rng = np.random.default_rng(RANDOM_SEED + scope_index)
        bootstrap_index = np.concatenate(
            [
                rng.choice(
                    positive_index,
                    size=(N_BOOTSTRAP, len(positive_index)),
                    replace=True,
                ),
                rng.choice(
                    negative_index,
                    size=(N_BOOTSTRAP, len(negative_index)),
                    replace=True,
                ),
            ],
            axis=1,
        )
        bootstrap_y = y[bootstrap_index]
        calls = frame[
            ["patient_id", "input_scope", "n_cells", "OGM_deep_deletion_label"]
        ].copy()
        calls["evaluation_set"] = scope
        calls["threshold"] = THRESHOLD
        for model in MODELS:
            p = frame[model].to_numpy(dtype=float)
            point = threshold_metrics(y, p)
            boot = threshold_metrics(bootstrap_y, p[bootstrap_index])
            row = {
                "evaluation_set": scope,
                "model": model,
                "n_patients": len(y),
                "n_positive": int(y.sum()),
                "n_negative": int((y == 0).sum()),
                "threshold": THRESHOLD,
                "AUROC": roc_auc_score(y, p),
                "AP": average_precision_score(y, p),
                "Brier": brier_score_loss(y, p),
            }
            for metric in [
                "Balanced_accuracy",
                "Sensitivity",
                "Specificity",
                "PPV",
                "NPV",
            ]:
                row[metric] = float(point[metric])
                low, high = percentile_ci(boot[metric])
                if not np.isfinite(row[metric]):
                    low, high = (np.nan, np.nan)
                row[f"{metric}_CI95_low"] = low
                row[f"{metric}_CI95_high"] = high
            for count in ["TP", "FP", "FN", "TN"]:
                row[count] = int(point[count])
            previous_record = None
            if previous_ci is not None:
                matched = previous_ci.loc[
                    previous_ci["evaluation_set"].eq(scope)
                    & previous_ci["model"].eq(model)
                ]
                if len(matched) == 1:
                    candidate = matched.iloc[0]
                    same_points = all(
                        (
                            metric in candidate.index
                            and np.isclose(
                                float(candidate[metric]),
                                row[metric],
                                atol=1e-08,
                            )
                            for metric in ["AUROC", "AP", "Brier"]
                        )
                    )
                    if same_points:
                        previous_record = candidate
            for metric in ["AUROC", "AP", "Brier"]:
                low_key = f"{metric}_CI95_low"
                high_key = f"{metric}_CI95_high"
                if (
                    previous_record is not None
                    and low_key in previous_record.index
                    and (high_key in previous_record.index)
                ):
                    low = previous_record[low_key]
                    high = previous_record[high_key]
                elif metric == "Brier":
                    low, high = percentile_ci(
                        np.mean(
                            (p[bootstrap_index] - bootstrap_y) ** 2, axis=1
                        )
                    )
                else:
                    function = (
                        roc_auc_score
                        if metric == "AUROC"
                        else average_precision_score
                    )
                    values = [
                        function(bootstrap_y[i], p[bootstrap_index[i]])
                        for i in range(N_BOOTSTRAP)
                    ]
                    low, high = percentile_ci(values)
                row[low_key] = low
                row[high_key] = high
            rows.append(row)
            calls[f"{model}_probability"] = p
            calls[f"{model}_call_075"] = (p >= THRESHOLD).astype(int)
        patient_call_tables.append(calls)
    result = pd.DataFrame(rows)
    result_file = (
        OUTPUT_DIR / "09_GSE327167_performance_threshold_075_with_CI.tsv"
    )
    result.to_csv(result_file, sep="\t", index=False)
    pd.concat(patient_call_tables, ignore_index=True).to_csv(
        OUTPUT_DIR / "10_GSE327167_patient_predictions_threshold_075.tsv",
        sep="\t",
        index=False,
    )
    lookup = result.set_index(["evaluation_set", "model"])
    row_labels = []
    for scope in SCOPES:
        frame = evaluation_sets[scope]
        row_labels.append(
            f"{SCOPE_LABELS[scope]}\nn={len(frame)}; OGM+={int(frame['OGM_deep_deletion_label'].sum())}"
        )

    def text_color(value, norm, cmap):
        r, g, b, _ = cmap(norm(value))
        luminance = 0.2126 * r + 0.7152 * g + 0.0722 * b
        return "white" if luminance < 0.54 else "#202020"

    def style_matrix_axis(axis):
        axis.set_xticks(range(len(MODELS)))
        axis.set_xticklabels(MODEL_LABELS, fontsize=8.5)
        axis.set_yticks(range(len(SCOPES)))
        axis.set_xticks(np.arange(-0.5, len(MODELS), 1), minor=True)
        axis.set_yticks(np.arange(-0.5, len(SCOPES), 1), minor=True)
        axis.grid(which="minor", color="white", linewidth=1.5)
        axis.tick_params(which="both", length=0, pad=6)
        for spine in axis.spines.values():
            spine.set_color("#777777")
            spine.set_linewidth(0.7)

