@_nb9_registry.register("s15_0")
def _nb9_stage_s15_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import numpy as np
    import pandas as pd
    from sklearn.metrics import roc_auc_score, average_precision_score

    PROJECT = Path(str(PROJECT_ROOT))
    PRED_DIR = PROJECT / "data_processed/MTAP_RNA_prediction"
    MODEL_DIR = PRED_DIR / "09_9p21_region_model/signedlog_v2"
    OOF_FILE = MODEL_DIR / "development_OOF_predictions.tsv"
    BASELINE_METADATA_FILE = (
        PRED_DIR / "03_baseline_models/cohort_with_three_gene_expression.tsv"
    )
    RAW_CACHE = (
        PRED_DIR / "09_9p21_region_model/development_region_raw_expression.tsv"
    )
    OUT = MODEL_DIR / "development_review"
    OUT.mkdir(parents=True, exist_ok=True)
    LABEL = "label_MTAP_deep"
    MODELS = {
        "Three_gene_L2": "probability_Three_gene_L2",
        "Region_ElasticNet": "probability_Region_ElasticNet",
    }
    SEED = 20261016
    N_BOOTSTRAPS = 2000
    for path in [OOF_FILE, BASELINE_METADATA_FILE, RAW_CACHE]:
        if not path.is_file():
            raise FileNotFoundError(
                "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
            )
    data = pd.read_csv(OOF_FILE, sep="\t", dtype={"patient_id": str})
    metadata = pd.read_csv(
        BASELINE_METADATA_FILE, sep="\t", dtype={"patient_id": str}
    )
    required_oof = {
        "patient_id",
        "acronym",
        LABEL,
        "CV_fold",
        *MODELS.values(),
    }
    required_metadata = {
        "patient_id",
        "dataset_split",
        "MTAP_GISTIC_call",
        "CDKN2A_GISTIC_call",
        "CDKN2B_GISTIC_call",
    }
    if not required_oof.issubset(data.columns):
        raise ValueError(
            "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
        )
    if not required_metadata.issubset(metadata.columns):
        raise ValueError(
            "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
        )
    if (
        data["patient_id"].duplicated().any()
        or metadata["patient_id"].duplicated().any()
    ):
        raise ValueError(
            "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
        )
    dev_metadata = metadata.loc[
        metadata["dataset_split"].eq("development"), list(required_metadata)
    ].copy()
    del metadata
    if set(data["patient_id"]) != set(dev_metadata["patient_id"]):
        raise ValueError(
            "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
        )
    data = data.merge(
        dev_metadata, on="patient_id", how="left", validate="one_to_one"
    )
    numeric_columns = [
        LABEL,
        "MTAP_GISTIC_call",
        "CDKN2A_GISTIC_call",
        "CDKN2B_GISTIC_call",
        *MODELS.values(),
    ]
    for column in numeric_columns:
        data[column] = pd.to_numeric(data[column], errors="raise")
    if not data[LABEL].isin([0, 1]).all():
        raise ValueError(
            "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
        )
    if not data["MTAP_GISTIC_call"].isin([-2, -1, 0, 1, 2]).all():
        raise ValueError(
            "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
        )
    if not np.array_equal(
        data[LABEL].to_numpy(),
        data["MTAP_GISTIC_call"].eq(-2).astype(int).to_numpy(),
    ):
        raise ValueError(
            "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
        )
    for column in MODELS.values():
        if data[column].isna().any() or not data[column].between(0, 1).all():
            raise ValueError(
                "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
            )
    data = data.sort_values("patient_id").reset_index(drop=True)
    if len(data) != 7431 or int(data[LABEL].sum()) != 558:
        raise ValueError(
            "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
        )
    y = data[LABEL].astype(int).to_numpy()
    strata = [
        np.asarray(indices, dtype=int)
        for indices in data.groupby(
            ["acronym", LABEL], sort=True
        ).indices.values()
    ]
    rng = np.random.default_rng(SEED)
    boot = {name: np.zeros((N_BOOTSTRAPS, 2)) for name in MODELS}
    for iteration in range(N_BOOTSTRAPS):
        sampled = np.concatenate(
            [
                rng.choice(indices, size=len(indices), replace=True)
                for indices in strata
            ]
        )
        sampled_y = y[sampled]
        for name, column in MODELS.items():
            probabilities = data[column].to_numpy()[sampled]
            boot[name][iteration, 0] = roc_auc_score(sampled_y, probabilities)
            boot[name][iteration, 1] = average_precision_score(
                sampled_y, probabilities
            )
        if (iteration + 1) % 500 == 0:
            pass
    metric_names = ["AUROC", "AP"]
    summary_rows = []
    difference_rows = []
    for metric_index, metric in enumerate(metric_names):
        for name, column in MODELS.items():
            if metric == "AUROC":
                estimate = roc_auc_score(y, data[column])
            else:
                estimate = average_precision_score(y, data[column])
            low, high = np.quantile(
                boot[name][:, metric_index], [0.025, 0.975]
            )
            summary_rows.append(
                {
                    "model": name,
                    "metric": metric,
                    "estimate": estimate,
                    "CI95_low": low,
                    "CI95_high": high,
                    "n_bootstraps": N_BOOTSTRAPS,
                    "interval_scope": "Conditional_on_fixed_OOF_predictions",
                }
            )
        difference = (
            boot["Region_ElasticNet"][:, metric_index]
            - boot["Three_gene_L2"][:, metric_index]
        )
        low, high = np.quantile(difference, [0.025, 0.975])
        region_values = data[MODELS["Region_ElasticNet"]]
        core_values = data[MODELS["Three_gene_L2"]]
        metric_function = (
            roc_auc_score if metric == "AUROC" else average_precision_score
        )
        difference_rows.append(
            {
                "metric": metric,
                "difference_region_minus_core": metric_function(
                    y, region_values
                )
                - metric_function(y, core_values),
                "CI95_low": low,
                "CI95_high": high,
                "CI_excludes_zero": bool(low > 0 or high < 0),
                "n_bootstraps": N_BOOTSTRAPS,
                "interval_scope": "Conditional_on_fixed_OOF_predictions",
            }
        )
    summary = pd.DataFrame(summary_rows)
    differences = pd.DataFrame(difference_rows)
    summary.to_csv(
        OUT / "paired_bootstrap_model_metrics.tsv", sep="\t", index=False
    )
    differences.to_csv(
        OUT / "paired_bootstrap_performance_differences.tsv",
        sep="\t",
        index=False,
    )
    cancer_rows = []
    for acronym, subset in data.groupby("acronym"):
        labels = subset[LABEL].astype(int)
        n_positive = int(labels.sum())
        n_negative = int((labels == 0).sum())
        row = {
            "acronym": acronym,
            "n_patients": len(subset),
            "n_positive": n_positive,
            "n_negative": n_negative,
            "adequate_for_macro_summary": n_positive >= 10
            and n_negative >= 10,
        }
        for name, column in MODELS.items():
            row[f"{name}_AUROC"] = (
                roc_auc_score(labels, subset[column])
                if labels.nunique() == 2
                else np.nan
            )
            row[f"{name}_AP"] = (
                average_precision_score(labels, subset[column])
                if labels.nunique() == 2
                else np.nan
            )
        for metric in metric_names:
            row[f"delta_{metric}"] = (
                row[f"Region_ElasticNet_{metric}"]
                - row[f"Three_gene_L2_{metric}"]
            )
        cancer_rows.append(row)
    cancers = pd.DataFrame(cancer_rows)
    cancers.to_csv(
        OUT / "per_cancer_paired_comparison.tsv", sep="\t", index=False
    )
    supported = cancers.loc[cancers["adequate_for_macro_summary"]]
    macro_rows = []
    for name in MODELS:
        macro_rows.append(
            {
                "model": name,
                "n_cancers": len(supported),
                "macro_AUROC": supported[f"{name}_AUROC"].mean(),
                "macro_AP": supported[f"{name}_AP"].mean(),
                "scope": "Descriptive_equal_cancer_weight",
            }
        )
    pd.DataFrame(macro_rows).to_csv(
        OUT / "descriptive_macro_performance.tsv", sep="\t", index=False
    )
    positive = data[LABEL].eq(1)
    negative = data[LABEL].eq(0)
    a_deep = data["CDKN2A_GISTIC_call"].eq(-2)
    b_deep = data["CDKN2B_GISTIC_call"].eq(-2)
    subgroups = {
        "All_MTAP_deep": positive,
        "All_MTAP_non_deep": negative,
        "CDKN2A_deep_MTAP_non_deep": a_deep & negative,
        "CDKN2B_deep_MTAP_non_deep": b_deep & negative,
        "CDKN2A_or_B_deep_MTAP_non_deep": (a_deep | b_deep) & negative,
        "MTAP_deep_without_CDKN2B_deep": positive
        & data["CDKN2B_GISTIC_call"].notna()
        & ~b_deep,
    }
    subgroup_rows = []
    for subgroup, mask in subgroups.items():
        subset = data.loc[mask]
        for name, column in MODELS.items():
            probabilities = subset[column]
            n = len(subset)
            subgroup_rows.append(
                {
                    "subgroup": subgroup,
                    "model": name,
                    "n_patients": n,
                    "n_DNA_positive": int(subset[LABEL].sum()),
                    "mean_probability": probabilities.mean(),
                    "median_probability": probabilities.median(),
                    "n_predicted_positive_at_05": int(
                        probabilities.ge(0.5).sum()
                    ),
                    "fraction_predicted_positive_at_05": (
                        probabilities.ge(0.5).mean() if n else np.nan
                    ),
                    "threshold_scope": "Descriptive_not_final",
                }
            )
    subgroup_results = pd.DataFrame(subgroup_rows)
    subgroup_results.to_csv(
        OUT / "DNA_subgroup_prediction_review.tsv", sep="\t", index=False
    )
    raw = pd.read_csv(
        RAW_CACHE, sep="\t", dtype={"patient_id": str}
    ).set_index("patient_id")
    if raw.index.duplicated().any() or set(raw.index) != set(
        data["patient_id"]
    ):
        raise ValueError(
            "Regional Elastic Net model-comparison summaries: integrity check failed; condition: input or artifact integrity check."
        )
    raw = raw.reindex(data["patient_id"])
    raw = raw.apply(pd.to_numeric, errors="raise")
    technical = pd.DataFrame(
        {
            "patient_id": data["patient_id"].to_numpy(),
            "acronym": data["acronym"].to_numpy(),
            "n_negative_features": raw.lt(0).sum(axis=1).to_numpy(),
            "n_missing_features": raw.isna().sum(axis=1).to_numpy(),
        }
    )
    technical["has_negative"] = technical["n_negative_features"] > 0
    technical["has_missing"] = technical["n_missing_features"] > 0
    technical_summary = technical.groupby("acronym", as_index=False).agg(
        n_patients=("patient_id", "size"),
        n_patients_with_negative=("has_negative", "sum"),
        n_patients_with_missing=("has_missing", "sum"),
        mean_negative_features=("n_negative_features", "mean"),
        mean_missing_features=("n_missing_features", "mean"),
    )
    technical_summary.to_csv(
        OUT / "technical_coverage_by_cancer.tsv", sep="\t", index=False
    )
    technical.to_csv(
        OUT / "technical_coverage_by_patient.tsv", sep="\t", index=False
    )
    _public_summary(
        globals(), "Regional Elastic Net model-comparison summaries"
    )

