    require(
        calls.isin([-2, -1, 0, 1, 2]).all(),
        "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: calls.isin([-2, -1, 0, 1, 2]).all().",
    )
    y = calls.eq(-2).astype(int)
    immune_names = {
        "tam",
        "tams",
        "monocytes",
        "monocyte",
        "t_cells",
        "t_cell",
        "b_plasma",
        "b_cells",
        "b_cell",
        "plasma",
        "nk",
        "nk_cells",
        "myeloid",
        "macrophages",
        "macrophage",
        "dendritic",
        "dendritic_cells",
        "mast",
    }
    normalised_labels = (
        obs["cell_type_manual"]
        .str.strip()
        .str.lower()
        .str.replace("[\\s/-]+", "_", regex=True)
    )
    obs["is_immune_for_descriptive_analysis"] = normalised_labels.isin(
        immune_names
    )
    obs.groupby(
        ["patient_id", "cell_type_manual"], observed=True
    ).size().rename("n_cells").reset_index().to_csv(
        OUT / "all_nuclei_annotation_counts.tsv", sep="\t", index=False
    )

    def resolve_barcodes(cell_meta, mex_barcodes, tumor_patient):
        candidates = {
            "cell_id_exact": pd.Series(
                cell_meta.index.to_numpy(), index=cell_meta.index, dtype=str
            )
        }
        for col in [
            "cell_barcode",
            "barcode",
            "barcodes",
            "original_barcode",
            "source_cell_id",
        ]:
            if col in cell_meta:
                candidates[f"obs:{col}"] = (
                    cell_meta[col].fillna("").astype(str)
                )
        barcode_pattern = re.compile(
            "(?<![ACGTN])([ACGTN]{14,20}-\\d+)(?!\\d)"
        )
        extracted = []
        for cell_id in cell_meta.index:
            hits = barcode_pattern.findall(str(cell_id))
            extracted.append(hits[0] if len(hits) == 1 else "")
        candidates["unique_10x_barcode_in_cell_id"] = pd.Series(
            extracted, index=cell_meta.index, dtype=str
        )
        known = tumor_patient.set_index("cell_id")["cell_barcode"]
        valid = []
        for method, values in candidates.items():
            if (
                values.eq("").any()
                or values.duplicated().any()
                or (not values.isin(mex_barcodes).all())
            ):
                continue
            if not known.index.isin(values.index).all():
                continue
            if not np.array_equal(
                values.reindex(known.index).to_numpy(), known.to_numpy()
            ):
                continue
            valid.append((method, values))
        require(
            len(valid) > 0,
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: len(valid) > 0.",
        )
        first_method, first_values = valid[0]
        for _, values in valid[1:]:
            require(
                np.array_equal(values.to_numpy(), first_values.to_numpy()),
                "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: np.array_equal(values.to_numpy(), first_values.to_numpy()).",
            )
        return (first_values, ";".join((method for method, _ in valid)))

    whole_expression = {}
    tumor_expression = {}
    raw_count_rows = []
    prediction_rows = []
    mapping_rows = []
    model_rows = []
    old_probability_column = next(
        (
            col
            for col in ["full_pseudobulk_probability", "probability"]
            if col in old_p
        ),
        None,
    )
    require(
        old_probability_column is not None,
        "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: old_probability_column is not None.",
    )
    for record in mex.sort_values("patient_id").itertuples(index=False):
        patient = record.patient_id
        cell_meta = obs.loc[obs["patient_id"].eq(patient)].copy()
        tumor_patient = tumor.loc[tumor["patient_id"].eq(patient)].copy()
        expected_n = int(patients.loc[patient, "n_all_nuclei"])
        require(
            len(cell_meta) == expected_n,
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: len(cell_meta) == expected_n.",
        )
        model_path = MODEL_DIR / f"L2_held_out_{patient}.joblib"
        require(
            model_path.is_file(),
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: model_path.is_file().",
        )
        bundle = joblib.load(model_path)
        require(
            bundle.get("held_out_patient") == patient,
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: bundle.get('held_out_patient') == patient.",
        )
        require(
            list(bundle.get("feature_names", [])) == CORE,
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: list(bundle.get('feature_names', [])) == CORE.",
        )
        training_patients = set(bundle.get("training_patients", []))
        require(
            training_patients == expected - {patient},
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: training_patients == expected - {patient}.",
        )
        pipeline = bundle["pipeline"]
        model_rows.append(
            {
                "held_out_patient": patient,
                "model_file": str(model_path),
                "model_sha256": sha256_file(model_path),
                "n_training_patients": len(training_patients),
            }
        )
        matrix_path = Path(record.matrix_file)
        features_path = Path(record.features_file)
        barcodes_path = Path(record.barcodes_file)
        for path in [matrix_path, features_path, barcodes_path]:
            require(
                path.is_file(),
                "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: path.is_file().",
            )
        features = pd.read_csv(
            features_path,
            sep="\t",
            header=None,
            dtype=str,
            keep_default_na=False,
        )
        require(
            features.shape[1] in {2, 3},
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: features.shape[1] in {2, 3}.",
        )
        with open_text(barcodes_path) as handle:
            barcodes = pd.Index(
                [line.rstrip("\r\n").split("\t")[0] for line in handle]
            )
        require(
            barcodes.is_unique,
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: barcodes.is_unique.",
        )
        gene_ids = features.iloc[:, 0].str.replace("\\.\\d+$", "", regex=True)
        if features.shape[1] == 3:
            gene_mask = features.iloc[:, 2].eq("Gene Expression").to_numpy()
        else:
            require(
                gene_ids.str.fullmatch("ENSG\\d+").all(),
                "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: gene_ids.str.fullmatch('ENSG\\\\d+').all().",
            )
            gene_mask = np.ones(len(features), dtype=bool)
        gene_index = pd.Index(gene_ids.loc[gene_mask])
        require(
            gene_mask.any(),
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: gene_mask.any().",
        )
        require(
            gene_index.is_unique,
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: gene_index.is_unique.",
        )
        core_positions = gene_index.get_indexer([ENSEMBL[g] for g in CORE])
        require(
            (core_positions >= 0).all(),
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: (core_positions >= 0).all().",
        )
        cell_barcodes, barcode_method = resolve_barcodes(
            cell_meta, barcodes, tumor_patient
        )
        positions = barcodes.get_indexer(cell_barcodes)
        mapping_rows.append(
            {
                "patient_id": patient,
                "n_QC_nuclei": len(cell_meta),
                "n_MEX_barcodes": len(barcodes),
                "n_MEX_barcodes_not_used": len(barcodes) - len(cell_meta),
                "barcode_mapping_method": barcode_method,
                "all_QC_nuclei_matched": bool((positions >= 0).all()),
                "Tumor_crosswalk_reproduced": True,
            }
        )
        with open(matrix_path, "rb") as raw_handle:
            if matrix_path.name.endswith(".gz"):
                with gzip.GzipFile(fileobj=raw_handle) as handle:
                    raw = mmread(handle)
            else:
                raw = mmread(raw_handle)
        require(
            sparse.issparse(raw),
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: sparse.issparse(raw).",
        )
        require(
            raw.shape == (len(features), len(barcodes)),
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: raw.shape == (len(features), len(barcodes)).",
        )
        for start in range(0, len(raw.data), 1000000):
            values = raw.data[start : start + 1000000]
            require(
                np.isfinite(values).all()
                and (values >= 0).all()
                and np.equal(values, np.rint(values)).all(),
                "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: np.isfinite(values).all() and (values >= 0).all() and np.equal(values, np.rint(values)).all().",
            )
        raw = raw.astype(np.int64, copy=False).tocsc()
        counts = raw[gene_mask, :][:, positions].tocsc()
        del raw
        per_cell_total = (
            np.asarray(counts.sum(axis=0)).ravel().astype(np.int64)
        )
        require(
            (per_cell_total > 0).all(),
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: (per_cell_total > 0).all().",
        )
        core_counts = counts[core_positions, :].toarray()
        tumor_mask = cell_meta.index.isin(tumor_ids)
        require(
            int(tumor_mask.sum()) == len(tumor_patient),
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: int(tumor_mask.sum()) == len(tumor_patient).",
        )
        scope_inputs = {}
        scope_totals = {}
        for scope, mask in [
            ("Tumor", tumor_mask),
            ("Whole_tissue", np.ones(len(cell_meta), dtype=bool)),
        ]:
            gene_sum = core_counts[:, mask].sum(axis=1, dtype=np.int64)
            total_umi = int(per_cell_total[mask].sum())
            require(
                total_umi > 0,
                "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: total_umi > 0.",
            )
            logcpm = np.log2(
                1.0 + gene_sum.astype(float) / total_umi * 1000000.0
            )
            scope_inputs[scope] = pd.DataFrame(
                [logcpm], index=[patient], columns=CORE
            )
            scope_totals[scope] = total_umi
            for gene, value in zip(CORE, gene_sum):
                raw_count_rows.append(
                    {
                        "patient_id": patient,
                        "scope": scope,
                        "gene": gene,
                        "raw_UMI": int(value),
                        "total_gene_expression_UMI": total_umi,
                        "n_nuclei": int(mask.sum()),
                    }
                )
        reconstructed = scope_inputs["Tumor"].iloc[0].to_numpy()
        previous = old_x.loc[patient, CORE].to_numpy(dtype=float)
        require(
            np.allclose(reconstructed, previous, rtol=0, atol=1e-08),
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: np.allclose(reconstructed, previous, rtol=0, atol=1e-08).",
        )
        p_tumor = float(
            positive_probability(pipeline, scope_inputs["Tumor"])[0]
        )
        p_whole = float(
            positive_probability(pipeline, scope_inputs["Whole_tissue"])[0]
        )
        p_previous = float(old_p.loc[patient, old_probability_column])
        require(
            abs(p_tumor - p_previous) <= 1e-08,
            "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: abs(p_tumor - p_previous) <= 1e-08.",
        )
        whole_expression[patient] = (
            scope_inputs["Whole_tissue"].iloc[0].to_numpy()
        )
        tumor_expression[patient] = reconstructed
        fraction_tumor = float(tumor_mask.mean())
        fraction_immune = float(
            cell_meta["is_immune_for_descriptive_analysis"].mean()
        )
        prediction_rows.append(
            {
                "patient_id": patient,
                "MTAP_GISTIC_call": int(calls.loc[patient]),
                "label_MTAP_deep": int(y.loc[patient]),
                "n_all_nuclei": len(cell_meta),
                "n_Tumor_nuclei": int(tumor_mask.sum()),
                "Tumor_cell_fraction": fraction_tumor,
                "immune_cell_fraction": fraction_immune,
                "Tumor_UMI_fraction": scope_totals["Tumor"]
                / scope_totals["Whole_tissue"],
                "Tumor_LOPO_probability": p_tumor,
                "Whole_tissue_transfer_probability": p_whole,
                "delta_whole_minus_Tumor": p_whole - p_tumor,
                "absolute_probability_difference": abs(p_whole - p_tumor),
                "Tumor_call_at_05": int(p_tumor >= THRESHOLD),
                "Whole_tissue_call_at_05": int(p_whole >= THRESHOLD),
                "discordant_at_05": (p_tumor >= THRESHOLD)
                != (p_whole >= THRESHOLD),
                "Tumor_input_reproduced": True,
                "Tumor_prediction_reproduced": True,
                "held_out_patient_excluded_from_training": True,
            }
        )
        pd.DataFrame(prediction_rows).to_csv(
            OUT / "patient_paired_predictions.tsv", sep="\t", index=False
        )
        del counts, core_counts, cell_meta
        gc.collect()
    pred = pd.DataFrame(prediction_rows).set_index("patient_id")
    require(
        len(pred) == 16,
        "GBM whole-tissue versus malignant-cell L2 comparison: required condition failed: len(pred) == 16.",
    )
    for values, name in [
        (whole_expression, "Whole_tissue_three_gene_log2CPM_plus_1.tsv"),
        (tumor_expression, "Reproduced_Tumor_three_gene_log2CPM_plus_1.tsv"),
    ]:
        pd.DataFrame.from_dict(
            values, orient="index", columns=CORE
        ).rename_axis("patient_id").to_csv(OUT / name, sep="\t")
    pd.DataFrame(raw_count_rows).to_csv(
        OUT / "three_gene_raw_UMI_and_denominators.tsv", sep="\t", index=False
    )
    pd.DataFrame(mapping_rows).to_csv(
        OUT / "barcode_mapping_audit.tsv", sep="\t", index=False
    )
    pd.DataFrame(model_rows).to_csv(
        OUT / "held_out_model_audit.tsv", sep="\t", index=False
    )
    score_columns = {
        "Tumor_LOPO": "Tumor_LOPO_probability",
        "Whole_tissue_transfer": "Whole_tissue_transfer_probability",
    }
    truth = pred["label_MTAP_deep"].to_numpy(dtype=int)

    def metrics(truth, probability):
        tn, fp, fn, tp = confusion_matrix(
            truth, probability >= THRESHOLD, labels=[0, 1]
        ).ravel()
        return {
            "AUROC": roc_auc_score(truth, probability),
            "AP": average_precision_score(truth, probability),
            "Brier": brier_score_loss(truth, probability),
            "sensitivity_at_05": tp / (tp + fn),
            "specificity_at_05": tn / (tn + fp),
            "precision_at_05": tp / (tp + fp) if tp + fp else np.nan,
            "accuracy_at_05": (tp + tn) / len(truth),
            "TP_at_05": int(tp),
            "FP_at_05": int(fp),
            "FN_at_05": int(fn),
            "TN_at_05": int(tn),
        }

    metric_rows = []
    for name, column in score_columns.items():
        metric_rows.append(
            {
                "analysis": name,
                "n_patients": len(pred),
                "n_DNA_deep_deletion": int(truth.sum()),
                **metrics(truth, pred[column].to_numpy()),
            }
        )
    performance = pd.DataFrame(metric_rows)
    performance.to_csv(
        OUT / "patient_level_performance.tsv", sep="\t", index=False
    )
    rng = np.random.default_rng(SEED)
    positive = np.flatnonzero(truth == 1)
    negative = np.flatnonzero(truth == 0)
    bootstrap_rows = []
    for repeat in range(2000):
        selected = np.concatenate(
            [
                rng.choice(positive, len(positive), replace=True),
                rng.choice(negative, len(negative), replace=True),
            ]
        )
        a = metrics(
            truth[selected],
            pred["Tumor_LOPO_probability"].to_numpy()[selected],
        )
        b = metrics(
            truth[selected],
            pred["Whole_tissue_transfer_probability"].to_numpy()[selected],
        )
        bootstrap_rows.append(
            {
                metric: b[metric] - a[metric]
                for metric in ["AUROC", "AP", "Brier"]
            }
        )
    bootstrap = pd.DataFrame(bootstrap_rows)
    difference_rows = []
    for metric in ["AUROC", "AP", "Brier"]:
        difference_rows.append(
            {
                "metric": metric,
                "difference_whole_minus_Tumor": performance.loc[
                    performance["analysis"].eq("Whole_tissue_transfer"), metric
                ].iloc[0]
                - performance.loc[
                    performance["analysis"].eq("Tumor_LOPO"), metric
                ].iloc[0],
                "bootstrap_CI95_low": bootstrap[metric].quantile(0.025),
                "bootstrap_CI95_high": bootstrap[metric].quantile(0.975),
                "interval_scope": "Conditional_on_fixed_patient_predictions",
            }
        )
    pd.DataFrame(difference_rows).to_csv(
        OUT / "paired_performance_differences.tsv", sep="\t", index=False
    )
    correlation_rows = []
    for composition in [
        "Tumor_cell_fraction",
        "immune_cell_fraction",
        "Tumor_UMI_fraction",
    ]:
        for outcome in [
            "delta_whole_minus_Tumor",
            "absolute_probability_difference",
        ]:
            x = pred[composition].to_numpy()
            z = pred[outcome].to_numpy()
            if np.unique(x).size > 1 and np.unique(z).size > 1:
                rho, pvalue = spearmanr(x, z)
            else:
                rho, pvalue = (np.nan, np.nan)
            correlation_rows.append(
                {
                    "composition": composition,
                    "outcome": outcome,
                    "n_patients": len(pred),
                    "Spearman_rho": rho,
                    "p_value_exploratory_unadjusted": pvalue,
                }
            )
    pd.DataFrame(correlation_rows).to_csv(
        OUT / "composition_associations_exploratory.tsv", sep="\t", index=False
    )
    COLORS = {0: "#33539E", 1: "#C56B9A"}

