    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)

    def sha256_file(path):
        h = hashlib.sha256()
        with open(path, "rb") as handle:
            for block in iter(lambda: handle.read(8 * 1024 * 1024), b""):
                h.update(block)
        return h.hexdigest()

    def read_indexed(path):
        frame = pd.read_csv(path, sep="\t", index_col=0)
        frame.index = frame.index.astype(str)
        require(
            frame.index.is_unique,
            "Whole-tissue three-model comparison: required condition failed: frame.index.is_unique.",
        )
        return frame

    def open_text(path):
        path = Path(path)
        if path.name.endswith(".gz"):
            return gzip.open(path, "rt", encoding="utf-8")
        return open(path, "r", encoding="utf-8")

    def positive_probability(model, values):
        classes = list(model.classes_)
        require(
            1 in classes,
            "Whole-tissue three-model comparison: required condition failed: 1 in classes.",
        )
        result = model.predict_proba(values)[:, classes.index(1)]
        require(
            np.isfinite(result).all()
            and ((result >= 0) & (result <= 1)).all(),
            "Whole-tissue three-model comparison: required condition failed: np.isfinite(result).all() and ((result >= 0) & (result <= 1)).all().",
        )
        return result

    def savefig(fig, name):
        for extension in ["pdf", "png"]:
            fig.savefig(
                FIG / f"{name}.{extension}",
                dpi=400 if extension == "pdf" else 250,
                bbox_inches="tight",
            )
        plt.close(fig)

