@_nb9_registry.register("s70_0")
def _nb9_stage_s70_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    from datetime import datetime
    import hashlib
    import json
    import joblib
    import numpy as np
    import pandas as pd
    import matplotlib.pyplot as plt
    import matplotlib as mpl
    from scipy.stats import beta
    from sklearn.metrics import (
        confusion_matrix,
        roc_auc_score,
        average_precision_score,
        brier_score_loss,
        matthews_corrcoef,
    )

    PROJECT = Path(str(PROJECT_ROOT))
    MODEL_ROOT = (
        PROJECT
        / "data_processed/MTAP_RNA_prediction/16_scRNA_transfer"
        / "08_L2_cell_number_stability_and_candidate"
    )
    MODEL_FILE = MODEL_ROOT / "models/GBM_snRNA_three_gene_L2_candidate.joblib"
    VALIDATION_FILE = (
        MODEL_ROOT / "reproduced_full_pseudobulk_LOPO_predictions.tsv"
    )
    THRESHOLDS = [0.5, 0.75, 0.8]
    TARGET_SPECIFICITY = 0.95
    PATIENT_COLUMN = "patient_id"
    LABEL_COLUMN = "label_MTAP_deep"
    GISTIC_COLUMN = "MTAP_GISTIC_call"
    PROBABILITY_COLUMN = "full_pseudobulk_probability"
    OUT = (
        PROJECT
        / "data_processed/MTAP_prediction_registry/threshold_evaluation"
        / (
            datetime.now().strftime("%Y%m%d_%H%M%S_%f")
            + "_GBM_LOPO_three_thresholds"
        )
    )
    FONT_FAMILY = "DejaVu Sans"
    PDF_DPI = 400
    mpl.rcParams.update(
        {
            "font.family": FONT_FAMILY,
            "font.size": 10,
            "pdf.fonttype": 42,
            "ps.fonttype": 42,
        }
    )

    def require(condition, message):
        if not condition:
            raise RuntimeError(message)

    def sha256_file(path):
        h = hashlib.sha256()
        with Path(path).open("rb") as handle:
            for block in iter(lambda: handle.read(8 * 1024 * 1024), b""):
                h.update(block)
        return h.hexdigest()

    def safe_divide(numerator, denominator):
        return numerator / denominator if denominator else np.nan

    def exact_binomial_ci(successes, total, alpha=0.05):
        """Compute a Clopper-Pearson exact binomial confidence interval."""
        if total == 0:
            return (np.nan, np.nan)
        lower = (
            0.0
            if successes == 0
            else float(beta.ppf(alpha / 2, successes, total - successes + 1))
        )
        upper = (
            1.0
            if successes == total
            else float(
                beta.ppf(1 - alpha / 2, successes + 1, total - successes)
            )
        )
        return (lower, upper)

    require(
        MODEL_FILE.is_file(),
        "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: MODEL_FILE.is_file().",
    )
    if not VALIDATION_FILE.is_file():
        candidates = sorted(MODEL_ROOT.parent.rglob("*LOPO*predictions*.tsv"))
        for path in candidates[:30]:
            pass
        raise FileNotFoundError(
            "GBM threshold sensitivity at 0.50, 0.75, and 0.80: integrity check failed; condition: input or artifact integrity check."
        )
    OUT.mkdir(parents=True, exist_ok=False)
    bundle = joblib.load(MODEL_FILE)
    require(
        isinstance(bundle, dict),
        "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: isinstance(bundle, dict).",
    )
    for key in [
        "model_status",
        "feature_names",
        "expression_unit",
        "normalization",
        "prediction_unit",
        "target",
        "training_positive_fraction",
        "pan_cancer_transfer_validated",
        "deployment_threshold_locked",
        "parameters",
    ]:
        pass
    pipeline = bundle.get("pipeline")
    require(
        pipeline is not None,
        "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: pipeline is not None.",
    )
    for name, step in pipeline.steps:
        parameters = step.get_params(deep=False)
        selected_parameters = {
            key: parameters[key]
            for key in [
                "C",
                "penalty",
                "class_weight",
                "solver",
                "max_iter",
                "with_mean",
                "with_std",
            ]
            if key in parameters
        }
    data = pd.read_csv(
        VALIDATION_FILE, sep="\t", dtype=str, keep_default_na=False
    )
    required_columns = [
        PATIENT_COLUMN,
        LABEL_COLUMN,
        GISTIC_COLUMN,
        PROBABILITY_COLUMN,
    ]
    if not set(required_columns).issubset(data.columns):
        raise RuntimeError(
            "GBM threshold sensitivity at 0.50, 0.75, and 0.80: integrity check failed; condition: input or artifact integrity check."
        )
    data[PATIENT_COLUMN] = data[PATIENT_COLUMN].str.strip()
    require(
        data[PATIENT_COLUMN].ne("").all(),
        "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: data[PATIENT_COLUMN].ne('').all().",
    )
    require(
        not data[PATIENT_COLUMN].duplicated().any(),
        "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: not data[PATIENT_COLUMN].duplicated().any().",
    )
    for column in [LABEL_COLUMN, GISTIC_COLUMN, PROBABILITY_COLUMN]:
        data[column] = pd.to_numeric(data[column], errors="raise")
    require(
        data[LABEL_COLUMN].isin([0, 1]).all(),
        "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: data[LABEL_COLUMN].isin([0, 1]).all().",
    )
    require(
        data[GISTIC_COLUMN].isin([-2, -1, 0, 1, 2]).all(),
        "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: data[GISTIC_COLUMN].isin([-2, -1, 0, 1, 2]).all().",
    )
    require(
        np.array_equal(
            data[LABEL_COLUMN].to_numpy(dtype=int),
            data[GISTIC_COLUMN].eq(-2).to_numpy(dtype=int),
        ),
        "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: np.array_equal(data[LABEL_COLUMN].to_numpy(dtype=int), data[GISTIC_COLUMN].eq(-2).to_numpy(dtype=int)).",
    )
    require(
        np.isfinite(data[PROBABILITY_COLUMN]).all()
        and data[PROBABILITY_COLUMN].between(0, 1).all(),
        "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: np.isfinite(data[PROBABILITY_COLUMN]).all() and data[PROBABILITY_COLUMN].between(0, 1).all().",
    )
    training_patients = bundle.get("training_patients")
    if isinstance(training_patients, (list, tuple, np.ndarray)):
        if all(
            (isinstance(x, (str, int, np.integer)) for x in training_patients)
        ):
            saved_patients = {str(x).strip() for x in training_patients}
            observed_patients = set(data[PATIENT_COLUMN])
            require(
                observed_patients == saved_patients,
                "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: observed_patients == saved_patients.",
            )
    training_calls = bundle.get("training_GISTIC_calls")
    if isinstance(training_calls, dict):
        calls = {str(k).strip(): v for k, v in training_calls.items()}
        if set(data[PATIENT_COLUMN]).issubset(calls):
            saved_calls = pd.to_numeric(
                data[PATIENT_COLUMN].map(calls), errors="coerce"
            )
            if saved_calls.notna().all():
                require(
                    np.array_equal(
                        saved_calls.to_numpy(), data[GISTIC_COLUMN].to_numpy()
                    ),
                    "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: np.array_equal(saved_calls.to_numpy(), data[GISTIC_COLUMN].to_numpy()).",
                )
    y = data[LABEL_COLUMN].to_numpy(dtype=int)
    p = data[PROBABILITY_COLUMN].to_numpy(dtype=float)
    require(
        len(np.unique(y)) == 2,
        "GBM threshold sensitivity at 0.50, 0.75, and 0.80: required condition failed: len(np.unique(y)) == 2.",
    )
    n_positive = int(y.sum())
    n_negative = int((y == 0).sum())
    scope_columns = [
        c
        for c in ["input_scope", "scope", "cell_type", "prediction_unit"]
        if c in data
    ]
    for column in scope_columns:
        pass
    metric_rows = []
    patient_results = data.copy()
    for threshold in THRESHOLDS:
        prediction = (p >= threshold).astype(int)
        tn, fp, fn, tp = confusion_matrix(y, prediction, labels=[0, 1]).ravel()
        sensitivity = safe_divide(tp, tp + fn)
        specificity = safe_divide(tn, tn + fp)
        ppv = safe_divide(tp, tp + fp)
        npv = safe_divide(tn, tn + fn)
        sensitivity_ci = exact_binomial_ci(int(tp), int(tp + fn))
        specificity_ci = exact_binomial_ci(int(tn), int(tn + fp))
        metric_rows.append(
            {
                "threshold": threshold,
                "n_patients": len(y),
                "TP": int(tp),
                "FP": int(fp),
                "TN": int(tn),
                "FN": int(fn),
                "sensitivity": sensitivity,
                "sensitivity_CI_low": sensitivity_ci[0],
                "sensitivity_CI_high": sensitivity_ci[1],
                "specificity": specificity,
                "specificity_CI_low": specificity_ci[0],
                "specificity_CI_high": specificity_ci[1],
                "PPV_in_this_validation_set": ppv,
                "NPV_in_this_validation_set": npv,
                "accuracy": safe_divide(tp + tn, len(y)),
                "balanced_accuracy": (sensitivity + specificity) / 2,
                "Youden_J": sensitivity + specificity - 1,
                "F1": safe_divide(2 * tp, 2 * tp + fp + fn),
                "MCC": matthews_corrcoef(y, prediction),
                "n_predicted_positive": int(prediction.sum()),
                "predicted_positive_fraction": float(prediction.mean()),
                "meets_specificity_point_target": specificity
                >= TARGET_SPECIFICITY,
                "specificity_CI_low_meets_target": specificity_ci[0]
                >= TARGET_SPECIFICITY,
            }
        )
        suffix = f"{threshold:.2f}"
        patient_results[f"prediction_t{suffix}"] = prediction
        patient_results[f"correct_t{suffix}"] = prediction == y
    metrics = pd.DataFrame(metric_rows).sort_values("threshold")
    display_columns = [
        "threshold",
        "TP",
        "FP",
        "TN",
        "FN",
        "sensitivity",
        "specificity",
        "balanced_accuracy",
        "MCC",
        "n_predicted_positive",
    ]
    prediction_columns = [
        f"prediction_t{threshold:.2f}" for threshold in THRESHOLDS
    ]
    changed = patient_results[
        patient_results[prediction_columns].nunique(axis=1).gt(1)
    ].copy()
    if changed.empty:
        pass
    base_prediction = (p >= 0.5).astype(int)
    for threshold in THRESHOLDS:
        if threshold == 0.5:
            continue
        current = (p >= threshold).astype(int)
        positive_to_negative = (base_prediction == 1) & (current == 0)
        removed_fp = int((positive_to_negative & (y == 0)).sum())
        added_fn = int((positive_to_negative & (y == 1)).sum())
    best_ba = metrics["balanced_accuracy"].max()
    ba_best = metrics.loc[np.isclose(metrics["balanced_accuracy"], best_ba)]
    eligible = metrics.loc[metrics["specificity"] >= TARGET_SPECIFICITY].copy()
    if eligible.empty:
        high_specificity_candidates = []
    else:
        max_sensitivity = eligible["sensitivity"].max()
        high_specificity_best = eligible.loc[
            np.isclose(eligible["sensitivity"], max_sensitivity)
        ]
        high_specificity_candidates = high_specificity_best[
            "threshold"
        ].tolist()
        if not high_specificity_best["specificity_CI_low_meets_target"].all():
            pass
    colors = ["#4477AA", "#EE9977", "#228833"]
    x = np.arange(len(metrics))

# %% [markdown]
#### Unified three-model performance across all evaluation settings
#
#Read source prediction files for TCGA OOF, TCGA holdout, CPTAC, GBM
#snRNA, and GSE327167 scRNA. Compute all common source metrics plus
#accuracy, F1, MCC, NPV, log loss, and the four confusion counts.
#Every model within a cohort uses the same evaluable patients.
#Missing cohorts are reported explicitly; no result is imputed.
#
#Classification summaries are computed at 0.50 and 0.75. AUROC, AP,
#Brier score, and log loss are threshold-independent. Existing source
#bootstrap analyses remain in their original stages. This unified
#point-estimate summary does not replace those confidence intervals.

# %%
from pathlib import Path
import hashlib
import json

import numpy as np
import pandas as pd
from IPython.display import display
from sklearn.metrics import (
    accuracy_score,
    average_precision_score,
    balanced_accuracy_score,
    brier_score_loss,
    confusion_matrix,
    f1_score,
    log_loss,
    matthews_corrcoef,
    roc_auc_score,
)


def _nb9_latest_file(root, pattern, environment_key):
    """Resolve an explicit override or the latest timestamped source output."""
    override = os.environ.get(environment_key)
    if override:
        candidate = Path(override).expanduser()
        return candidate if candidate.is_absolute() else root / candidate
    candidates = list(root.glob(pattern))
    return (
        max(candidates, key=lambda p: (p.parent.name, p.stat().st_mtime_ns))
        if candidates
        else None
    )


def _nb9_prediction_specs(root):
    """Use prediction schemas and relative locations recorded in Model."""
    base = root / "data_processed/MTAP_RNA_prediction"
    tpm = base / "15_region_multitask_DL/08_TPM_retraining"
    comparison = tpm / "06_three_gene_L2_comparison"
