@_nb9_registry.register("s24_140")
def _nb9_stage_s24_140():
    fig, axes = plt.subplots(1, 2, figsize=(10, 4.2))
    fpr, tpr, _ = roc_curve(y_binary, mtap_oof)
    axes[0].plot(
        fpr,
        tpr,
        color="#33539E",
        linewidth=2,
        label=f"AUROC = {performance.iloc[0]['AUROC']:.3f}",
    )
    axes[0].plot([0, 1], [0, 1], linestyle="--", color="0.7")
    axes[0].set(
        xlabel="False positive rate",
        ylabel="Sensitivity",
        title="Development OOF ROC",
    )
    axes[0].legend(frameon=False)
    precision, recall, _ = precision_recall_curve(y_binary, mtap_oof)
    axes[1].plot(
        recall,
        precision,
        color="#A5678E",
        linewidth=2,
        label=f"AP = {performance.iloc[0]['AP']:.3f}",
    )
    axes[1].axhline(
        y_binary.mean(),
        linestyle="--",
        color="0.7",
        label="Positive prevalence",
    )
    axes[1].set(
        xlabel="Recall",
        ylabel="Precision",
        title="Development OOF precision–recall",
    )
    axes[1].legend(frameon=False)
    for axis in axes:
        axis.spines["top"].set_visible(False)
        axis.spines["right"].set_visible(False)
    fig.tight_layout()
    fig.savefig(
        FIGURE_DIR / "development_MTAP_OOF_ROC_PR.pdf", bbox_inches="tight"
    )
    fig.savefig(
        FIGURE_DIR / "development_MTAP_OOF_ROC_PR.png",
        dpi=300,
        bbox_inches="tight",
    )
    plt.show()
    plt.close(fig)
    final_epochs = max(1, int(np.median(selected_epochs)))
    full_preprocessing = fit_preprocessor(X)
    full_x = transform_values(X, full_preprocessing)
    for seed in SEEDS:
        final_model, _, _, final_history = fit_network(
            full_x,
            Y,
            cancer_codes,
            seed=seed,
            epochs=final_epochs,
            description=f"Full development/seed{seed}",
        )
        save_checkpoint(
            final_model,
            full_preprocessing,
            MODEL_DIR / f"development_candidate_seed{seed}.pt",
            extra={
                "seed": seed,
                "epochs": final_epochs,
                "status": "development_candidate",
            },
        )
        pd.DataFrame(final_history).to_csv(
            OUT / f"full_development_history_seed{seed}.tsv",
            sep="\t",
            index=False,
        )
        del final_model
        if DEVICE.type == "cuda":
            torch.cuda.empty_cache()
    manifest = {
        "model": "RCANE-inspired regional multitask classifier",
        "not_original_RCANE_reproduction": True,
        "n_patients": n_patients,
        "n_MTAP_positive": int(y_binary.sum()),
        "n_expression_features": X.shape[1],
        "n_targets": n_targets,
        "feature_names": feature_names,
        "target_Entrez_order": target_ids,
        "MTAP_target_index": MTAP_INDEX,
        "outer_fold_source": str(FOLD_FILE),
        "seeds": SEEDS,
        "region_hidden": REGION_HIDDEN,
        "shared_hidden": SHARED_HIDDEN,
        "cancer_embedding": CANCER_EMBEDDING,
        "dropout": DROPOUT,
        "learning_rate": LEARNING_RATE,
        "weight_decay": WEIGHT_DECAY,
        "auxiliary_weight": AUXILIARY_WEIGHT,
        "final_epochs": final_epochs,
        "class_weights_used": False,
        "test_evaluated": False,
        "final_threshold_selected": False,
        "evaluation_scope": "Exploratory development OOF; independent external validation required",
    }
    (OUT / "training_manifest.json").write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    _public_summary(
        globals(), "Regional multitask DL training and seed analysis"
    )

