@_nb9_registry.register("s26_104")
def _nb9_stage_s26_104():
    fig, axes = plt.subplots(1, 2, figsize=(10, 4.2))
    for name, probability in model_probabilities.items():
        fpr, tpr, _ = roc_curve(y, probability)
        precision, recall, _ = precision_recall_curve(y, probability)
        auc = roc_auc_score(y, probability)
        ap = average_precision_score(y, probability)
        axes[0].plot(
            fpr,
            tpr,
            color=colors[name],
            linewidth=2,
            label=f"{labels[name]}: {auc:.3f}",
        )
        axes[1].plot(
            recall,
            precision,
            color=colors[name],
            linewidth=2,
            label=f"{labels[name]}: {ap:.3f}",
        )
    axes[0].plot([0, 1], [0, 1], linestyle="--", color="0.75")
    axes[1].axhline(y.mean(), linestyle="--", color="0.75")
    axes[0].set(
        xlabel="False positive rate",
        ylabel="Sensitivity",
        title="Development OOF ROC",
    )
    axes[1].set(
        xlabel="Recall",
        ylabel="Precision",
        title="Development OOF precision–recall",
    )
    for axis in axes:
        axis.legend(frameon=False, fontsize=8)
        axis.spines["top"].set_visible(False)
        axis.spines["right"].set_visible(False)
    fig.tight_layout()
    for extension in ["pdf", "png"]:
        fig.savefig(
            FIGURE_DIR / f"same_input_ROC_PR.{extension}",
            dpi=300,
            bbox_inches="tight",
        )
    plt.show()
    plt.close(fig)
    full_search = make_search(SEED)
    full_search.fit(X, y)
    full_model = full_search.best_estimator_
    if full_model.named_steps["model"].n_iter_.max() >= MAX_ITER:
        raise RuntimeError(
            "Forty-five-feature Elastic Net development: integrity check failed; condition: input or artifact integrity check."
        )
    joblib.dump(
        {
            "pipeline": full_model,
            "expression_feature_names": feature_names,
            "input_columns": X.columns.tolist(),
            "outcome": "MTAP GISTIC -2 versus non--2",
            "best_params": full_search.best_params_,
        },
        MODEL_DIR / "same_input_ElasticNet_development_candidate.joblib",
    )
    transformed_feature_names = full_model.named_steps[
        "preprocessing"
    ].get_feature_names_out()
    coefficients = pd.DataFrame(
        {
            "feature": transformed_feature_names,
            "coefficient": full_model.named_steps["model"].coef_[0],
        }
    )
    coefficients.to_csv(
        OUT / "full_development_coefficients.tsv", sep="\t", index=False
    )
    manifest = {
        "comparison": "Same expression features and cancer information; MTAP binary endpoint",
        "n_patients": int(len(y)),
        "n_positive": int(y.sum()),
        "n_expression_features": len(feature_names),
        "feature_names": feature_names,
        "outer_fold_source": str(DL_FILE),
        "inner_cv_folds": INNER_FOLDS,
        "parameter_grid": PARAM_GRID,
        "full_development_best_params": full_search.best_params_,
        "DL_retrained": False,
        "test_evaluated": False,
        "threshold_selected": False,
        "bootstrap_iterations": N_BOOTSTRAPS,
        "bootstrap_scope": "Paired, class-stratified, conditional on fixed OOF",
        "interpretation_limit": "Compares complete prediction approaches; does not isolate multitask or ensemble effects",
    }
    (OUT / "comparison_manifest.json").write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    _public_summary(globals(), "Forty-five-feature Elastic Net development")

