@_nb9_registry.register("s37_144")
def _nb9_stage_s37_144():
    fig, axes = plt.subplots(1, 2, figsize=(10, 4.2))
    yy = evaluation["label_MTAP_deep"].to_numpy(dtype=int)
    if len(np.unique(yy)) == 2:
        for name in MODEL_NAMES:
            pp = evaluation[probability_columns[name]].to_numpy()
            fpr, tpr, _ = roc_curve(yy, pp)
            precision, recall, _ = precision_recall_curve(yy, pp)
            auc = roc_auc_score(yy, pp)
            ap = average_precision_score(yy, pp)
            axes[0].plot(
                fpr,
                tpr,
                color=COLORS[name],
                linewidth=2,
                label=f"{name}: AUC={auc:.3f}",
            )
            axes[1].plot(
                recall,
                precision,
                color=COLORS[name],
                linewidth=2,
                label=f"{name}: AP={ap:.3f}",
            )
    axes[0].plot([0, 1], [0, 1], "--", color="#BFB8DA", linewidth=1)
    axes[1].axhline(
        yy.mean(),
        linestyle="--",
        color="#BFB8DA",
        linewidth=1,
        label=f"Positive fraction={yy.mean():.3f}",
    )
    axes[0].set(
        xlabel="False-positive rate",
        ylabel="Sensitivity",
        title="CPTAC external ROC",
        xlim=(0, 1),
        ylim=(0, 1.02),
    )
    axes[1].set(
        xlabel="Recall",
        ylabel="Precision",
        title="CPTAC external precision–recall",
        xlim=(0, 1),
        ylim=(0, 1.02),
    )
    for ax in axes:
        ax.legend(frameon=False, fontsize=7, loc="lower left")
    fig.tight_layout()
    for extension in ["pdf", "png"]:
        fig.savefig(
            FIGURES / f"CPTAC_overall_ROC_PR.{extension}",
            dpi=300,
            bbox_inches="tight",
        )
    plt.close(fig)
    cancers = list(CANCER_MAP)
    fig, ax = plt.subplots(figsize=(8, 6))
    labels_for_axis = []
    for position, cohort in enumerate(cancers):
        cohort_data = evaluation.loc[evaluation["database_cancer"].eq(cohort)]
        n_pos = int(cohort_data["label_MTAP_deep"].sum())
        n_total = len(cohort_data)
        labels_for_axis.append(f"{cohort}  ({n_pos}/{n_total} positive)")
        for name, offset in [(DL_NAME, -0.12), (EN_NAME, 0.12)]:
            row = metrics_table.loc[
                metrics_table["cohort"].eq(cohort)
                & metrics_table["model"].eq(name)
            ]
            if row.empty:
                continue
            row = row.iloc[0]
            if not np.isfinite(row["AUROC"]):
                continue
            low = row["AUROC_CI95_low"]
            high = row["AUROC_CI95_high"]
            if np.isfinite(low) and np.isfinite(high):
                ax.hlines(
                    position + offset,
                    low,
                    high,
                    color=COLORS[name],
                    linewidth=1.4,
                )
            ax.plot(
                row["AUROC"],
                position + offset,
                "o",
                color=COLORS[name],
                markersize=4,
            )
    ax.axvline(0.5, linestyle="--", color="#BFB8DA", linewidth=1)
    ax.set_yticks(range(len(cancers)))
    ax.set_yticklabels(labels_for_axis)
    ax.invert_yaxis()
    ax.set_xlim(0, 1.02)
    ax.set_xlabel("AUROC with conditional bootstrap 95% CI")
    ax.set_title("CPTAC external validation by cancer")
    for name in MODEL_NAMES:
        ax.plot([], [], "o", color=COLORS[name], label=name)
    ax.legend(frameon=False, loc="lower left", fontsize=8)
    fig.tight_layout()
    for extension in ["pdf", "png"]:
        fig.savefig(
            FIGURES / f"CPTAC_per_cancer_AUROC.{extension}",
            dpi=300,
            bbox_inches="tight",
        )
    plt.close(fig)
    bins = [0, 0.01, 0.025, 0.05, 0.1, 0.2, 0.4, 0.6, 0.8, 1]
    calibration_rows = []
    fig, ax = plt.subplots(figsize=(5, 4.5))
    for name in MODEL_NAMES:
        calibration_data = pd.DataFrame(
            {
                "probability": evaluation[
                    probability_columns[name]
                ].to_numpy(),
                "label": yy,
            }
        )
        calibration_data["bin"] = pd.cut(
            calibration_data["probability"], bins=bins, include_lowest=True
        )
        model_rows = []
        for interval, group in calibration_data.groupby("bin", observed=True):
            n = len(group)
            n_pos = int(group["label"].sum())
            low, high = wilson_interval(n_pos, n)
            row = {
                "model": name,
                "probability_bin": str(interval),
                "n_patients": n,
                "n_positive": n_pos,
                "mean_probability": group["probability"].mean(),
                "observed_positive_fraction": n_pos / n,
                "Wilson_CI95_low": low,
                "Wilson_CI95_high": high,
            }
            calibration_rows.append(row)
            model_rows.append(row)
        curve = pd.DataFrame(model_rows)
        ax.plot(
            curve["mean_probability"],
            curve["observed_positive_fraction"],
            "-o",
            color=COLORS[name],
            markersize=4,
            label=name,
        )
    ax.plot([0, 1], [0, 1], "--", color="#BFB8DA")
    ax.set(
        xlabel="Mean predicted probability",
        ylabel="Observed DNA-positive fraction",
        title="CPTAC external calibration",
        xlim=(0, 1),
        ylim=(0, 1),
    )
    ax.legend(frameon=False, fontsize=8)
    fig.tight_layout()
    for extension in ["pdf", "png"]:
        fig.savefig(
            FIGURES / f"CPTAC_external_calibration.{extension}",
            dpi=300,
            bbox_inches="tight",
        )
    plt.close(fig)
    pd.DataFrame(calibration_rows).to_csv(
        EXTERNAL_OUT / "CPTAC_calibration_bins.tsv", sep="\t", index=False
    )
    save_json(
        {
            "locked_manifest_SHA256": sha256_file(LOCK_MANIFEST),
            "external_input_hashes": external_file_hashes,
            "n_patients_predicted": len(external_predictions),
            "n_patients_evaluated": len(evaluation),
            "n_DNA_positive": int(evaluation["label_MTAP_deep"].sum()),
            "n_bootstraps": N_BOOTSTRAPS,
            "bootstrap_strata": "database_cancer × DNA label",
            "external_preprocessing_fitted": False,
            "thresholds_changed_after_external_evaluation": False,
            "interpretation": "Predicted non-deep is not confirmed DNA-neutral. Bulk validation does not establish scRNA validity.",
        },
        EXTERNAL_OUT / "external_validation_manifest.json",
    )
    _public_summary(
        globals(),
        "Forty-four-member Elastic Net training and frozen CPTAC validation",
    )

