    manifest = {
        "analysis": "Frozen model transfer error diagnosis",
        "models": MODEL_NAMES,
        "n_development": len(development),
        "n_external": len(patient_diagnostics),
        "retrained": False,
        "thresholds_changed": False,
        "external_distribution_adjusted": False,
        "final_fit_predictions": "Technical diagnostics only; not independent validation",
        "expression_z": "Diagnostic relative to same-cancer TCGA development distribution; not used as replacement model input",
        "purity": "Not analysed in this step; no purity values inferred or substituted",
        "causal_interpretation": False,
    }
