@_nb9_registry.register("s42_61")
def _nb9_stage_s42_61():
    for model in MODELS:
        for call in [-2, -1, 0]:
            if call == -2:
                error_name, correct_name = ("FN", "TP")
            else:
                error_name, correct_name = ("FP", "TN")
            fig, axes = plt.subplots(2, 5, figsize=(15, 7), squeeze=False)
            for ax, cancer in zip(axes.ravel(), CANCERS):
                subset = long_data.loc[
                    long_data["model"].eq(model)
                    & long_data["database_cancer"].eq(cancer)
                    & long_data["MTAP_GISTIC_call"].eq(call)
                ]
                for position, group_name, color in [
                    (0, correct_name, "#33539E"),
                    (1, error_name, "#A5678E"),
                ]:
                    values = (
                        subset.loc[
                            subset["prediction_error"].eq(group_name),
                            "MTAP_DNA_log2ratio",
                        ]
                        .dropna()
                        .to_numpy(dtype=float)
                    )
                    if len(values) == 0:
                        continue
                    box = ax.boxplot(
                        [values],
                        positions=[position],
                        widths=0.5,
                        patch_artist=True,
                        showfliers=False,
                        manage_ticks=False,
                    )
                    box["boxes"][0].set_facecolor(color)
                    box["boxes"][0].set_alpha(0.25)
                    box["medians"][0].set_color(color)
                    jitter = plot_rng.uniform(-0.13, 0.13, size=len(values))
                    ax.scatter(
                        position + jitter,
                        values,
                        s=10,
                        color=color,
                        alpha=0.65,
                        rasterized=True,
                    )
                n_correct = int(
                    subset.loc[
                        subset["prediction_error"].eq(correct_name),
                        "MTAP_DNA_log2ratio",
                    ]
                    .notna()
                    .sum()
                )
                n_error = int(
                    subset.loc[
                        subset["prediction_error"].eq(error_name),
                        "MTAP_DNA_log2ratio",
                    ]
                    .notna()
                    .sum()
                )
                row = mtap_results.loc[
                    mtap_results["model"].eq(model)
                    & mtap_results["database_cancer"].eq(cancer)
                    & mtap_results["MTAP_GISTIC_call"].eq(call)
                ]
                if not row.empty and np.isfinite(
                    row.iloc[0]["q_BH_all_new_tests"]
                ):
                    annotation = (
                        f"BH q={row.iloc[0]['q_BH_all_new_tests']:.3g}"
                    )
                else:
                    annotation = "Descriptive"
                ax.set_title(f"{cancer}\n{annotation}", fontsize=10)
                ax.set_xticks([0, 1])
                ax.set_xticklabels(
                    [
                        f"{correct_name}\nn={n_correct}",
                        f"{error_name}\nn={n_error}",
                    ]
                )
                ax.set_xlim(-0.5, 1.5)
                ax.set_ylabel("MTAP DNA log2 ratio")
                if n_correct + n_error == 0:
                    ax.text(
                        0.5,
                        0.5,
                        "No samples",
                        transform=ax.transAxes,
                        ha="center",
                        va="center",
                        color="grey",
                    )
            fig.suptitle(
                f"{model}: MTAP GISTIC {call}; {error_name} versus {correct_name}",
                fontsize=13,
            )
            fig.tight_layout(rect=(0, 0, 1, 0.94))
            filename = (
                f"{model}_MTAP_GISTIC_{call}_{error_name}_vs_{correct_name}"
            )
            for extension in ["pdf", "png"]:
                fig.savefig(
                    FIGURES / f"{filename}.{extension}",
                    dpi=300,
                    bbox_inches="tight",
                )
            plt.close(fig)
    digest = hashlib.sha256()
    with INPUT_FILE.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    manifest = {
        "input_file": str(INPUT_FILE),
        "input_SHA256": digest.hexdigest(),
        "models": list(MODELS),
        "genes_examined": GENES,
        "diagnostic_probability_threshold": DIAGNOSTIC_THRESHOLD,
        "comparison_direction": "Error minus correct",
        "minimum_observed_patients_per_group_for_test": MIN_N_PER_GROUP,
        "test": "Two-sided Mann-Whitney U",
        "multiple_testing": "BH across all valid new tests over models, cancers, GISTIC states and genes",
        "bootstrap": "Within-group patient bootstrap for median differences; conditional on fixed predictions",
        "n_bootstraps": N_BOOTSTRAPS,
        "model_retrained": False,
        "classification_threshold_changed": False,
        "DNA_labels_changed": False,
        "purity_adjusted": False,
    }
    with (OUT / "analysis_manifest.json").open(
        "w", encoding="utf-8"
    ) as handle:
        json.dump(manifest, handle, ensure_ascii=False, indent=2)
    display_columns = [
        "model",
        "database_cancer",
        "MTAP_GISTIC_call",
        "comparison",
        "n_error_continuous",
        "n_correct_continuous",
        "error_median",
        "correct_median",
        "median_difference_error_minus_correct",
        "median_difference_CI95_low",
        "median_difference_CI95_high",
        "p_value",
        "q_BH_all_new_tests",
        "status",
    ]
    display_rows = mtap_results.loc[
        mtap_results["MTAP_GISTIC_call"].isin([-2, -1, 0])
        & mtap_results["n_error_continuous"].gt(0)
        & mtap_results["n_correct_continuous"].gt(0)
    ]
    significant = results.loc[results["q_BH_all_new_tests"].lt(0.05)]
    if significant.empty:
        pass
    _public_summary(globals(), "CPTAC fixed comparison summaries")

