    fig, axes = plt.subplots(
        nrows=2,
        ncols=3,
        figsize=(11.5, 7.2),
        sharey=True,
        constrained_layout=True,
    )
    for cohort_index, cohort_name in enumerate(COHORT_ORDER):
        cohort_frame = cohort_frames[cohort_name]
        cohort_y = cohort_frame["label_MTAP_deep"].astype(int).to_numpy()
        for metric_index, metric in enumerate(FIGURE_METRICS):
            ax = axes[cohort_index, metric_index]
            metric_table = (
                performance.loc[
                    performance["cohort"].eq(cohort_name)
                    & performance["metric"].eq(metric)
                ]
                .set_index("model")
                .reindex(MODEL_ORDER)
            )
            for model_index, model_name in enumerate(MODEL_ORDER):
                row = metric_table.loc[model_name]
                ax.vlines(
                    x=model_index,
                    ymin=row["CI95_low"],
                    ymax=row["CI95_high"],
                    color=MODEL_COLORS[model_name],
                    linewidth=2,
                    zorder=2,
                )
                ax.hlines(
                    y=[row["CI95_low"], row["CI95_high"]],
                    xmin=model_index - 0.07,
                    xmax=model_index + 0.07,
                    color=MODEL_COLORS[model_name],
                    linewidth=1.4,
                    zorder=2,
                )
                ax.scatter(
                    model_index,
                    row["estimate"],
                    color=MODEL_COLORS[model_name],
                    edgecolor="white",
                    linewidth=0.6,
                    s=65,
                    zorder=3,
                )
                ax.annotate(
                    f"{row['estimate']:.3f}",
                    (model_index, row["estimate"]),
                    xytext=(0, 8),
                    textcoords="offset points",
                    ha="center",
                    va="bottom",
                    fontsize=7.5,
                )
            if metric == "AP":
                baseline = float(cohort_y.mean())
            else:
                baseline = 0.5
            ax.axhline(
                baseline,
                color="#AAAAAA",
                linestyle="--",
                linewidth=1,
                zorder=1,
            )
            ax.set_xticks(range(len(MODEL_ORDER)))
            ax.set_xticklabels(
                [MODEL_LABELS[model_name] for model_name in MODEL_ORDER],
                fontsize=8,
                rotation=0,
            )
            ax.set_xlim(-0.5, len(MODEL_ORDER) - 0.5)
            ax.set_ylim(0, 1.08)
            ax.grid(axis="y", alpha=0.15, linewidth=0.7)
            if cohort_index == 0:
                ax.set_title(FIGURE_METRIC_LABELS[metric], pad=10)
            if metric_index == 0:
                n_total = len(cohort_y)
                n_positive = int(cohort_y.sum())
                ax.set_ylabel(
                    f"{COHORT_LABELS[cohort_name]}\nN={n_total}; MTAP GISTIC −2={n_positive}\nPerformance",
                    fontsize=8.5,
                )
    fig.suptitle(
        "Bulk RNA-based prediction of MTAP deep deletion", fontsize=12
    )
    for extension in ["pdf", "png"]:
        fig.savefig(
            OUT / f"TCGA_CPTAC_three_model_performance.{extension}",
            dpi=400,
            bbox_inches="tight",
        )
    plt.show()
    plt.close(fig)
    fig, axes = plt.subplots(
        nrows=2, ncols=2, figsize=(9.5, 8), constrained_layout=True
    )
    for cohort_index, cohort_name in enumerate(COHORT_ORDER):
        frame = cohort_frames[cohort_name]
        y = frame["label_MTAP_deep"].astype(int).to_numpy()
        roc_ax = axes[cohort_index, 0]
        pr_ax = axes[cohort_index, 1]
        for model_name in MODEL_ORDER:
            probability_column = PROBABILITY_COLUMNS[model_name]
            probabilities = frame[probability_column].to_numpy(dtype=float)
            fpr, tpr, _ = roc_curve(y, probabilities)
            precision, recall, _ = precision_recall_curve(y, probabilities)
            auroc = point_estimates[cohort_name, model_name]["AUROC"]
            average_precision = point_estimates[cohort_name, model_name]["AP"]
            roc_ax.plot(
                fpr,
                tpr,
                color=MODEL_COLORS[model_name],
                linewidth=2,
                label=f"{MODEL_LABELS[model_name]}: AUROC={auroc:.3f}",
            )
            pr_ax.step(
                recall,
                precision,
                where="post",
                color=MODEL_COLORS[model_name],
                linewidth=2,
                label=f"{MODEL_LABELS[model_name]}: AP={average_precision:.3f}",
            )
        roc_ax.plot(
            [0, 1], [0, 1], color="#AAAAAA", linestyle="--", linewidth=1
        )
        pr_ax.axhline(
            float(y.mean()),
            color="#AAAAAA",
            linestyle="--",
            linewidth=1,
            label=f"Prevalence={y.mean():.3f}",
        )
        roc_ax.set_title(
            f"{COHORT_LABELS[cohort_name]}\nReceiver operating characteristic"
        )
        pr_ax.set_title(
            f"{COHORT_LABELS[cohort_name]}\nPrecision–recall curve"
        )
        roc_ax.set_xlabel("False-positive rate")
        roc_ax.set_ylabel("Sensitivity")
        pr_ax.set_xlabel("Recall")
        pr_ax.set_ylabel("Precision")
        for ax in [roc_ax, pr_ax]:
            ax.set_xlim(0, 1)
            ax.set_ylim(0, 1.03)
            ax.grid(alpha=0.15, linewidth=0.7)
            ax.legend(loc="best", frameon=False, fontsize=7.5)
    for extension in ["pdf", "png"]:
        fig.savefig(
            OUT / f"TCGA_CPTAC_three_model_ROC_PR.{extension}",
            dpi=400,
            bbox_inches="tight",
        )
    plt.show()
    plt.close(fig)
    manifest = {
        "analysis": "Bulk DL versus three-gene L2 versus Elastic Net",
        "target": "MTAP GISTIC -2 versus non--2",
        "TCGA_prediction_file": str(TCGA_PATH),
        "TCGA_prediction_type": "Patient-level out-of-fold predictions",
        "CPTAC_prediction_file": str(CPTAC_PATH),
        "CPTAC_prediction_type": "Frozen-model external predictions",
        "models": {
            "Bulk_DL": {
                "probability_column": "prob_DL",
                "description": "44-input regional multitask deep-learning model; three frozen seeds",
                "color": MODEL_COLORS["Bulk_DL"],
            },
            "Three_gene_L2": {
                "probability_column": "prob_L2",
                "features": ["MTAP", "CDKN2A", "CDKN2B"],
                "color": MODEL_COLORS["Three_gene_L2"],
            },
            "Elastic_Net": {
                "probability_column": "prob_ElasticNet",
                "description": "44-input Elastic Net",
                "color": MODEL_COLORS["Elastic_Net"],
            },
        },
        "classification_threshold": THRESHOLD,
        "bootstrap": {
            "method": "Patient-level stratified percentile bootstrap",
            "paired_between_models": True,
            "paired_between_cohorts": False,
            "model_retraining": False,
            "n_bootstrap": N_BOOTSTRAP,
        },
        "seed": SEED,
        "interpretation": "TCGA results are based on OOF predictions rather than apparent full-training-set predictions. CPTAC results represent frozen-model external evaluation.",
    }
    with (OUT / "analysis_manifest.json").open(
        "w", encoding="utf-8"
    ) as handle:
        json.dump(manifest, handle, indent=2, ensure_ascii=False)
    for model_name in MODEL_ORDER:
        pass
    _public_summary(
        globals(), "TCGA OOF and CPTAC final three-model performance"
    )

