@_nb9_registry.register("s66_121")
def _nb9_stage_s66_121():
    fig, ax = plt.subplots(figsize=(6, 5.5))
    for state in [0, 1]:
        sub = pred.loc[pred["label_MTAP_deep"].eq(state)]
        ax.scatter(
            sub["Tumor_LOPO_probability"],
            sub["Whole_tissue_transfer_probability"],
            s=55,
            color=COLORS[state],
            label="DNA deep deletion" if state else "DNA non-deep deletion",
        )
    for patient, row in pred.iterrows():
        ax.annotate(
            patient.replace("C3L-", "L-").replace("C3N-", "N-"),
            (
                row["Tumor_LOPO_probability"],
                row["Whole_tissue_transfer_probability"],
            ),
            xytext=(3, 3),
            textcoords="offset points",
            fontsize=7,
        )
    ax.plot([0, 1], [0, 1], "--", color="#777777", linewidth=1)
    ax.axvline(0.5, color="#BBBBBB", linewidth=0.8)
    ax.axhline(0.5, color="#BBBBBB", linewidth=0.8)
    ax.set(
        xlim=(-0.03, 1.03),
        ylim=(-0.03, 1.03),
        xlabel="Tumor-subset LOPO score",
        ylabel="Whole-tissue transfer score",
        title="Same held-out L2 model; different cell scope",
    )
    ax.legend(frameon=False, fontsize=8)
    fig.tight_layout()
    save_figure(fig, "Figure1_paired_prediction_scores")
    fig, axes = plt.subplots(1, 2, figsize=(10, 4))
    for ax, variable, xlabel in [
        (axes[0], "Tumor_cell_fraction", "Tumor cell fraction"),
        (axes[1], "immune_cell_fraction", "Immune cell fraction"),
    ]:
        for state in [0, 1]:
            sub = pred.loc[pred["label_MTAP_deep"].eq(state)]
            ax.scatter(
                sub[variable],
                sub["delta_whole_minus_Tumor"],
                color=COLORS[state],
                s=50,
            )
        ax.axhline(0, color="#777777", linestyle="--", linewidth=1)
        ax.set(xlabel=xlabel, ylabel="Whole-tissue score − Tumor score")
    fig.tight_layout()
    save_figure(fig, "Figure2_prediction_difference_vs_composition")
    fig, axes = plt.subplots(1, 2, figsize=(10, 4.2))
    for name, column, color in [
        ("Tumor subset", "Tumor_LOPO_probability", "#33539E"),
        ("Whole tissue", "Whole_tissue_transfer_probability", "#C56B9A"),
    ]:
        probability = pred[column].to_numpy()
        fpr, tpr, _ = roc_curve(truth, probability)
        precision, recall, _ = precision_recall_curve(truth, probability)
        axes[0].plot(
            fpr,
            tpr,
            color=color,
            linewidth=2,
            label=f"{name}: AUC={roc_auc_score(truth, probability):.3f}",
        )
        axes[1].plot(
            recall,
            precision,
            color=color,
            linewidth=2,
            label=f"{name}: AP={average_precision_score(truth, probability):.3f}",
        )
    axes[0].plot([0, 1], [0, 1], "--", color="#AAAAAA")
    axes[1].axhline(truth.mean(), linestyle="--", color="#AAAAAA")
    axes[0].set(
        xlabel="False-positive rate", ylabel="Sensitivity", title="ROC"
    )
    axes[1].set(xlabel="Recall", ylabel="Precision", title="Precision–recall")
    for ax in axes:
        ax.legend(frameon=False, fontsize=8)
    fig.tight_layout()
    save_figure(fig, "Figure3_ROC_PR")
    completion = {
        "status": "WHOLE_TISSUE_TRANSFER_TEST_COMPLETED",
        "n_patients": len(pred),
        "n_DNA_deep_deletion": int(truth.sum()),
        "n_DNA_non_deep_deletion": int((truth == 0).sum()),
        "n_all_QC_nuclei": int(pred["n_all_nuclei"].sum()),
        "n_Tumor_nuclei": int(pred["n_Tumor_nuclei"].sum()),
        "model": "Existing GBM Tumor-subset L2 held-out-patient models",
        "prediction_input": "Whole-tissue QC-filtered raw-UMI pseudobulk",
        "input_scale": "log2(1 + summed_gene_UMI / summed_all_gene_UMI * 1e6)",
        "all_Tumor_inputs_and_predictions_reproduced": True,
        "test_patient_excluded_from_classifier_training": True,
        "n_discordant_at_descriptive_threshold_05": int(
            pred["discordant_at_05"].sum()
        ),
        "threshold_05_is_deployment_validated": False,
        "model_retrained": False,
        "adapter_fitted": False,
        "original_files_modified": False,
        "pan_cancer_transfer_validated": False,
        "sequencing_modality_comparison_possible": False,
        "note": "Patient-level GBM snRNA input-scope comparison. Whole-tissue fractions describe captured QC nuclei, not unbiased tissue composition. Non-deep deletion includes GISTIC -1 and is not synonymous with copy-neutral. Bootstrap intervals condition on fixed predictions and do not include model retraining uncertainty.",
    }
    with open(OUT / "completion.json", "w", encoding="utf-8") as handle:
        json.dump(completion, handle, ensure_ascii=False, indent=2)
    bundle_path = OUT / "GBM_whole_tissue_L2_review.zip"
    with zipfile.ZipFile(
        bundle_path, "w", compression=zipfile.ZIP_DEFLATED
    ) as archive:
        for path in sorted(OUT.rglob("*")):
            if path.is_file() and path != bundle_path:
                archive.write(path, arcname=str(path.relative_to(OUT)))
    _public_summary(
        globals(), "GBM whole-tissue versus malignant-cell L2 comparison"
    )

# %% [markdown]
##### Paired whole-tissue and malignant-cell metric visualization

# %%
@_nb9_registry.register("s67_0")
def _nb9_stage_s67_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    import numpy as np
    import pandas as pd
    import matplotlib.pyplot as plt
    from sklearn.metrics import (
        roc_auc_score,
        average_precision_score,
        brier_score_loss,
        confusion_matrix,
    )

    comparison_base = Path(
        str(
            PROJECT_ROOT
            / "data_processed/MTAP_RNA_prediction/16_scRNA_transfer"
        )
    )
    comparison_out = None
    if "OUT" in globals():
        candidate = Path(OUT)
        if (candidate / "patient_paired_predictions.tsv").is_file():
            comparison_out = candidate
    if comparison_out is None:
        candidates = sorted(
            [
                path
                for path in comparison_base.glob(
                    "10_whole_tissue_L2_paired_test_*"
                )
                if (path / "patient_paired_predictions.tsv").is_file()
                and (path / "completion.json").is_file()
            ],
            key=lambda path: path.name,
        )
        if not candidates:
            raise RuntimeError(
                "Paired whole-tissue and malignant-cell metric visualization: integrity check failed; condition: input or artifact integrity check."
            )
        comparison_out = candidates[-1]
    prediction_file = comparison_out / "patient_paired_predictions.tsv"
    comparison_fig_dir = comparison_out / "figures"
    comparison_fig_dir.mkdir(parents=True, exist_ok=True)
    paired = pd.read_csv(prediction_file, sep="\t", dtype={"patient_id": str})
    required_columns = [
        "patient_id",
        "label_MTAP_deep",
        "Tumor_LOPO_probability",
        "Whole_tissue_transfer_probability",
    ]
    missing_columns = sorted(set(required_columns) - set(paired.columns))
    if missing_columns:
        raise RuntimeError(
            "Paired whole-tissue and malignant-cell metric visualization: integrity check failed; condition: input or artifact integrity check."
        )
    if (
        len(paired) != 16
        or paired["patient_id"].isna().any()
        or (not paired["patient_id"].is_unique)
    ):
        raise RuntimeError(
            "Paired whole-tissue and malignant-cell metric visualization: integrity check failed; condition: input or artifact integrity check."
        )
    for column in required_columns[1:]:
        paired[column] = pd.to_numeric(paired[column], errors="raise")
    truth = paired["label_MTAP_deep"].to_numpy(dtype=int)
    if (
        not paired["label_MTAP_deep"].isin([0, 1]).all()
        or int(truth.sum()) != 8
    ):
        raise RuntimeError(
            "Paired whole-tissue and malignant-cell metric visualization: integrity check failed; condition: input or artifact integrity check."
        )
    PLOT_THRESHOLD = 0.5
    scope_columns = {
        "Whole tissue": "Whole_tissue_transfer_probability",
        "Tumour cell": "Tumor_LOPO_probability",
    }
    scope_colors = {"Whole tissue": "#33539E", "Tumour cell": "#A5678E"}

    def safe_divide(a, b):
        return float(a / b) if b else np.nan

    rows = []
    for scope, column in scope_columns.items():
        probability = paired[column].to_numpy(dtype=float)
        if (
            not np.isfinite(probability).all()
            or np.any(probability < 0)
            or np.any(probability > 1)
        ):
            raise RuntimeError(
                "Paired whole-tissue and malignant-cell metric visualization: integrity check failed; condition: input or artifact integrity check."
            )
        predicted = (probability >= PLOT_THRESHOLD).astype(int)
        tn, fp, fn, tp = confusion_matrix(
            truth, predicted, labels=[0, 1]
        ).ravel()
        sensitivity = safe_divide(tp, tp + fn)
        specificity = safe_divide(tn, tn + fp)
        rows.append(
            {
                "Input": scope,
                "n_patients": len(truth),
                "threshold": PLOT_THRESHOLD,
                "AUROC": roc_auc_score(truth, probability),
                "AP": average_precision_score(truth, probability),
                "Balanced accuracy": (sensitivity + specificity) / 2,
                "Sensitivity": sensitivity,
                "Specificity": specificity,
                "PPV": safe_divide(tp, tp + fp),
                "NPV": safe_divide(tn, tn + fn),
                "Accuracy": safe_divide(tp + tn, len(truth)),
                "Brier": brier_score_loss(truth, probability),
                "TP": int(tp),
                "FP": int(fp),
                "FN": int(fn),
                "TN": int(tn),
            }
        )
    bar_performance = pd.DataFrame(rows).set_index("Input")
    bar_performance.to_csv(
        comparison_out / "Whole_vs_Tumour_L2_barplot_source_data.tsv",
        sep="\t",
        index=True,
    )
    plt.rcParams.update(
        {
            "font.family": "DejaVu Sans",
            "font.size": 10,
            "axes.linewidth": 0.9,
            "pdf.fonttype": 42,
            "ps.fonttype": 42,
            "axes.unicode_minus": False,
        }
    )
    metrics_to_plot = [
        "AUROC",
        "AP",
        "Balanced accuracy",
        "Sensitivity",
        "Specificity",
        "PPV",
        "NPV",
        "Accuracy",
    ]
    metric_labels = [
        "AUROC",
        "AP",
        "Balanced\naccuracy",
        "Sensitivity",
        "Specificity",
        "PPV",
        "NPV",
        "Accuracy",
    ]

