@_nb9_registry.register("s70_77")
def _nb9_stage_s70_77():
    fig, axes = plt.subplots(1, 3, figsize=(14, 4))
    for offset, metric, label, color in [
        (-0.08, "sensitivity", "Sensitivity", "#4477AA"),
        (0.08, "specificity", "Specificity", "#CC6677"),
    ]:
        center = metrics[metric].to_numpy()
        lower = metrics[f"{metric}_CI_low"].to_numpy()
        upper = metrics[f"{metric}_CI_high"].to_numpy()
        axes[0].errorbar(
            x + offset,
            center,
            yerr=np.vstack([center - lower, upper - center]),
            fmt="o",
            capsize=4,
            color=color,
            label=label,
        )
    axes[0].set_xticks(x, [f"{t:.2f}" for t in metrics.threshold])
