@_nb9_registry.register("s75_53")
def _nb9_stage_s75_53():
    figure = plt.figure(figsize=(17.2, 9.4), facecolor="white")
    grid = figure.add_gridspec(
        nrows=2,
        ncols=4,
        left=0.12,
        right=0.93,
        bottom=0.12,
        top=0.9,
        wspace=0.18,
        hspace=0.3,
    )
    normalizer = Normalize(vmin=0.0, vmax=1.0)
    panel_letters = list("ABCDEFGH")
    for panel_index, metric in enumerate(METRICS):
        axis = figure.add_subplot(grid[panel_index // 4, panel_index % 4])
        raw_matrix, low_matrix, high_matrix = metric_matrix(metric)
        color_matrix = favourable_color_matrix(metric, raw_matrix)
        masked_color_matrix = np.ma.masked_invalid(color_matrix)
        axis.imshow(
            masked_color_matrix,
            cmap=PERFORMANCE_CMAP,
            norm=normalizer,
            aspect="auto",
            interpolation="nearest",
        )
        for row_index in range(len(EVALUATION_ORDER)):
            for column_index in range(len(MODELS)):
                value = raw_matrix[row_index, column_index]
                low = low_matrix[row_index, column_index]
                high = high_matrix[row_index, column_index]
                color_value = color_matrix[row_index, column_index]
                if np.isfinite(color_value):
                    rgba = PERFORMANCE_CMAP(normalizer(color_value))
                    text_color = contrast_text_color(rgba)
                else:
                    text_color = "#505050"
                axis.text(
                    column_index,
                    row_index,
                    format_metric_annotation(value, low, high),
                    ha="center",
                    va="center",
                    fontsize=8.1,
                    color=text_color,
                    linespacing=1.25,
                )
        axis.set_xticks(np.arange(len(MODELS)))
        axis.set_xticklabels(
            [MODEL_LABELS[model] for model in MODELS], fontsize=8.5
        )
