# %% [markdown]
##### Final single-cell L2 coefficient extraction and visualization

# %%
@_nb9_registry.register("s78_0")
def _nb9_stage_s78_0():
    _publication_previous_tables = {
        name: id(value)
        for name, value in list(globals().items())
        if isinstance(value, pd.DataFrame)
    }
    from pathlib import Path
    from datetime import datetime
    import hashlib
    import json
    import joblib
    import numpy as np
    import pandas as pd
    import matplotlib.pyplot as plt
    from sklearn.pipeline import Pipeline
    from sklearn.preprocessing import StandardScaler
    from sklearn.linear_model import LogisticRegression
    from scipy.special import expit

    PROJECT = Path(str(PROJECT_ROOT))
    MODEL_FILE = (
        PROJECT
        / "data_processed/MTAP_RNA_prediction/16_scRNA_transfer/08_L2_cell_number_stability_and_candidate/models/GBM_snRNA_three_gene_L2_candidate.joblib"
    )
    RUN_ID = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    OUTPUT_DIR = (
        PROJECT
        / "data_processed/MTAP_prediction_registry/model_interpretation"
        / f"{RUN_ID}_GBM_snRNA_three_gene_L2"
    )
    GENES = ["MTAP", "CDKN2A", "CDKN2B"]
    COLORS = {"MTAP": "#33539E", "CDKN2A": "#BFB8DA", "CDKN2B": "#A5678E"}

    def require(condition, message):
        if not bool(condition):
            raise RuntimeError(message)

    def sha256_file(path):
        digest = hashlib.sha256()
        with Path(path).open("rb") as handle:
            for block in iter(lambda: handle.read(8 * 1024 * 1024), b""):
                digest.update(block)
        return digest.hexdigest()

    require(
        MODEL_FILE.is_file(),
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: MODEL_FILE.is_file().",
    )
    bundle = joblib.load(MODEL_FILE)
    require(
        isinstance(bundle, dict),
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: isinstance(bundle, dict).",
    )
    require(
        "pipeline" in bundle and "feature_names" in bundle,
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: 'pipeline' in bundle and 'feature_names' in bundle.",
    )
    pipeline = bundle["pipeline"]
    feature_names = list(bundle["feature_names"])
    require(
        feature_names == GENES,
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: feature_names == GENES.",
    )
    require(
        bundle.get("expression_unit") == "log2(CPM+1)",
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: bundle.get('expression_unit') == 'log2(CPM+1)'.",
    )
    require(
        isinstance(pipeline, Pipeline),
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: isinstance(pipeline, Pipeline).",
    )
    classifier = pipeline.steps[-1][1]
    require(
        isinstance(classifier, LogisticRegression),
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: isinstance(classifier, LogisticRegression).",
    )
    preprocessors = []
    for name, step in pipeline.steps[:-1]:
        if step is None:
            continue
        if isinstance(step, str) and step == "passthrough":
            continue
        preprocessors.append((name, step))
    require(
        len(preprocessors) == 1
        and isinstance(preprocessors[0][1], StandardScaler),
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: len(preprocessors) == 1 and isinstance(preprocessors[0][1], StandardScaler).",
    )
    scaler = preprocessors[0][1]
    require(
        scaler.with_std,
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: scaler.with_std.",
    )
    require(
        classifier.coef_.shape == (1, 3),
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: classifier.coef_.shape == (1, 3).",
    )
    require(
        np.array_equal(classifier.classes_, np.array([0, 1])),
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: np.array_equal(classifier.classes_, np.array([0, 1])).",
    )
    for name, estimator in [
        ("pipeline", pipeline),
        ("scaler", scaler),
        ("classifier", classifier),
    ]:
        if hasattr(estimator, "feature_names_in_"):
            require(
                list(estimator.feature_names_in_) == feature_names,
                "Final single-cell L2 coefficient extraction and visualization: required condition failed: list(estimator.feature_names_in_) == feature_names.",
            )
    params = classifier.get_params()
    is_l2 = params.get("penalty") == "l2" or (
        params.get("penalty") == "elasticnet" and params.get("l1_ratio") == 0
    )
    require(
        is_l2,
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: is_l2.",
    )
    for key in ["penalty", "C", "solver", "class_weight", "fit_intercept"]:
        pass
    beta = np.asarray(classifier.coef_[0], dtype=float)
    intercept = float(classifier.intercept_[0])
    scale = np.asarray(scaler.scale_, dtype=float)
    center = (
        np.asarray(scaler.mean_, dtype=float)
        if scaler.with_mean
        else np.zeros(3)
    )
    require(
        scale.shape == (3,)
        and center.shape == (3,)
        and np.isfinite(scale).all()
        and np.isfinite(center).all()
        and np.isfinite(beta).all()
        and np.isfinite(intercept)
        and (scale > 0).all(),
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: scale.shape == (3,) and center.shape == (3,) and np.isfinite(scale).all() and np.isfinite(center).all() and np.isfinite(beta).all() and np.isfinite(intercept) and (scale > 0).all().",
    )
    beta_expression = beta / scale
    intercept_expression = float(intercept - np.sum(beta * center / scale))
    with np.errstate(over="ignore"):
        model_or = np.exp(beta)
    table = pd.DataFrame(
        {
            "gene": feature_names,
            "standardization_center": center,
            "standardization_scale": scale,
            "standardized_coefficient": beta,
            "absolute_standardized_coefficient": np.abs(beta),
            "model_OR_per_scaled_unit": model_or,
            "expression_scale_coefficient": beta_expression,
        }
    )
    table["direction"] = [
        (
            "Higher expression increases predicted deletion probability"
            if value > 0
            else (
                "Higher expression decreases predicted deletion probability"
                if value < 0
                else "Zero coefficient"
            )
        )
        for value in beta
    ]
    rng = np.random.default_rng(20261106)
    test_x = center + rng.normal(size=(20, 3)) * scale
    test_input = (
        pd.DataFrame(test_x, columns=feature_names)
        if hasattr(pipeline, "feature_names_in_")
        else test_x
    )
    model_logit = pipeline.decision_function(test_input)
    formula_logit = intercept_expression + test_x @ beta_expression
    require(
        np.allclose(model_logit, formula_logit, rtol=1e-08, atol=1e-08),
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: np.allclose(model_logit, formula_logit, rtol=1e-08, atol=1e-08).",
    )
    require(
        np.allclose(
            pipeline.predict_proba(test_input)[:, 1],
            expit(formula_logit),
            rtol=1e-08,
            atol=1e-08,
        ),
        "Final single-cell L2 coefficient extraction and visualization: required condition failed: np.allclose(pipeline.predict_proba(test_input)[:, 1], expit(formula_logit), rtol=1e-08, atol=1e-08).",
    )
    OUTPUT_DIR.mkdir(parents=True, exist_ok=False)
    standardized_terms = " ".join(
        (
            f"{value:+.10g} * z_{gene}"
            for gene, value in zip(feature_names, beta)
        )
    )
    expression_terms = " ".join(
        (
            f"{value:+.10g} * x_{gene}"
            for gene, value in zip(feature_names, beta_expression)
        )
    )
    formula = f"Model: {MODEL_FILE}\nSHA256: {sha256_file(MODEL_FILE)}\nPositive class: 1 = MTAP deep deletion\nExpression unit: log2(CPM+1)\n\nStandardized input:\nz_j = (x_j - center_j) / scale_j\nS = {intercept:.10g} {standardized_terms}\n\nEquivalent expression-scale equation:\nS = {intercept_expression:.10g} {expression_terms}\n\nP(deletion) = 1 / (1 + exp(-S))\nV5 classification rule described in this project: P(deletion) >= 0.75\nThe classification threshold does not alter coefficients.\n"
    table.to_csv(
        OUTPUT_DIR / "three_gene_L2_coefficients.tsv", sep="\t", index=False
    )
    (OUTPUT_DIR / "three_gene_L2_formula.txt").write_text(
        formula, encoding="utf-8"
    )
    audit = {
        "model_file": str(MODEL_FILE),
        "model_sha256": sha256_file(MODEL_FILE),
        "feature_order": feature_names,
        "expression_unit": bundle["expression_unit"],
        "standardized_intercept": intercept,
        "expression_scale_intercept": intercept_expression,
        "penalty": params.get("penalty"),
        "C": float(params["C"]),
        "formula_verified": True,
        "model_refitted": False,
    }
    (OUTPUT_DIR / "model_coefficient_audit.json").write_text(
        json.dumps(audit, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    plt.rcParams.update(
        {
            "font.family": "DejaVu Sans",
            "font.size": 10,
            "axes.linewidth": 0.9,
            "pdf.fonttype": 42,
            "ps.fonttype": 42,
            "axes.unicode_minus": False,
        }
    )

# %% [markdown]
#### Cross-cohort metric heatmaps

# %%
import matplotlib.pyplot as plt
from matplotlib.colors import LinearSegmentedColormap, Normalize


def _nb9_plot_metrics(performance, project_root):
    """Show comparable metric panels with raw numeric annotations."""
    if performance.empty:
        return
    palette = ["#33539E", "#7FACD6", "#BFB8DA", "#E8B7D4", "#A5678E"]
    cmap = LinearSegmentedColormap.from_list("MTAP_nine_part", palette)
    cmap.set_bad("#ECECEC")
    models = ["L2", "Elastic Net", "DL"]
    cohorts = performance["cohort"].drop_duplicates().tolist()
    metrics = [
        ("AUROC", "AUROC", True),
        ("AUPRC_AP", "Average precision", True),
        ("Brier", "Brier score", False),
        ("Log_loss", "Log loss", False),
        ("Accuracy", "Accuracy", True),
        ("Balanced_accuracy", "Balanced accuracy", True),
        ("Sensitivity", "Sensitivity", True),
        ("Specificity", "Specificity", True),
        ("PPV", "PPV", True),
        ("NPV", "NPV", True),
        ("F1", "F1", True),
        ("MCC", "MCC", True),
    ]
    output = project_root / "outputs/nine_part_model_comparison/figures"
    output.mkdir(parents=True, exist_ok=True)
    for threshold in (0.50, 0.75):
        subset = performance.loc[performance["threshold"].eq(threshold)]
        figure, axes = plt.subplots(
            3, 4, figsize=(18, max(10, len(cohorts) * 1.25))
        )
        figure.subplots_adjust(
            left=0.18,
            right=0.98,
            bottom=0.08,
            top=0.91,
            hspace=0.5,
            wspace=0.42,
        )
        for panel, (metric, title, higher_better) in enumerate(metrics):
            axis = axes.flat[panel]
            matrix = subset.pivot(
                index="cohort", columns="model", values=metric
            ).reindex(index=cohorts, columns=models)
            raw = matrix.to_numpy(dtype=float)
            if metric == "MCC":
                normalizer = Normalize(-1, 1)
            elif metric == "Log_loss":
                normalizer = Normalize(0, max(1.0, float(np.nanmax(raw))))
            else:
                normalizer = Normalize(0, 1)
            panel_cmap = cmap if higher_better else cmap.reversed()
            panel_cmap.set_bad("#ECECEC")
            image = axis.imshow(
                np.ma.masked_invalid(raw),
                cmap=panel_cmap,
                norm=normalizer,
                aspect="auto",
            )
            for row in range(len(cohorts)):
                for column in range(len(models)):
                    value = raw[row, column]
                    annotation = (
                        "NA" if not np.isfinite(value) else f"{value:.3f}"
                    )
                    rgba = (
                        panel_cmap(normalizer(value))
                        if np.isfinite(value)
                        else (0.9, 0.9, 0.9, 1)
                    )
                    luminance = (
                        0.2126 * rgba[0] + 0.7152 * rgba[1] + 0.0722 * rgba[2]
                    )
                    axis.text(
                        column,
                        row,
                        annotation,
                        ha="center",
                        va="center",
                        fontsize=7.5,
                        color="white" if luminance < 0.5 else "#202020",
                    )
            axis.set_xticks(range(3), models, fontsize=8)
            axis.set_yticks(range(len(cohorts)))
            axis.set_yticklabels(
                cohorts if panel % 4 == 0 else [""] * len(cohorts),
                fontsize=7.7,
            )
            axis.set_xticks(np.arange(-0.5, 3, 1), minor=True)
            axis.set_yticks(np.arange(-0.5, len(cohorts), 1), minor=True)
            axis.grid(which="minor", color="white", linewidth=1)
            axis.tick_params(which="both", length=0)
            direction = "higher" if higher_better else "lower"
            axis.set_title(
                f"{chr(65 + panel)}  {title}\n({direction} is better)",
                fontsize=9,
            )
            figure.colorbar(
                image, ax=axis, fraction=0.035, pad=0.025
            ).ax.tick_params(labelsize=6)
        figure.suptitle(
            f"Patient-level MTAP prediction across cohorts | threshold = {threshold:.2f}",
            fontsize=14,
            fontweight="bold",
        )
        figure.text(
            0.18,
            0.025,
            "Source-specific patient sets; TCGA development uses OOF scores. Raw point estimates are shown. NA denotes an undefined metric.",
            fontsize=8,
        )
        stem = f"all_cohort_three_model_metrics_threshold_{int(threshold * 100):03d}"
        figure.savefig(output / f"{stem}.pdf", bbox_inches="tight")
        figure.savefig(output / f"{stem}.png", dpi=300, bbox_inches="tight")
        plt.show()
        if "inline" not in plt.get_backend().lower():
            display(figure)
        plt.close(figure)

